async function withRetry<T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> {
    let lastError: Error;
    for (let i = 0; i < retries; i++) {
        try {
            return await fn();
        } catch (error: any) {
            lastError = error;
            console.warn(`Attempt ${i + 1} failed. Retrying in ${delay}ms...`, error);
            if (i < retries - 1) {
                await new Promise(res => setTimeout(res, delay));
                delay *= 2; // Exponential backoff
            }
        }
    }
    throw lastError;
};

const getNextRecurrenceDate = (currentEndDate: string, interval: 'daily' | 'weekly' | 'monthly'): string => {
    const date = new Date(currentEndDate);
    date.setDate(date.getDate() + 1);
    switch (interval) {
        case 'daily': break;
        case 'weekly': date.setDate(date.getDate() + 6); break;
        case 'monthly': date.setMonth(date.getMonth() + 1); break;
    }
    return date.toISOString().split('T')[0];
};

const getPromptFunction = (docTitle, phase) => {
    const title = docTitle.toLowerCase();
    if (phase === 1 && title.includes('concept proposal')) return PROMPTS.phase1;
    if (title.includes('resources & skills')) return PROMPTS.phase2;
    if (title.includes('swot') || title.includes('risk analysis')) return PROMPTS.phase3;
    if (title.includes('kickoff briefing')) return PROMPTS.phase4;
    if (title.includes('statement of work') || title.includes('sow')) return PROMPTS.phase5;
    if (title.includes('preliminary review')) return PROMPTS.phase6;
    if (title.includes('detailed plans')) return PROMPTS.phase7;

    if (phase === 8) {
        if (title.includes('sprint requirements') || title.includes('user story backlog')) return PROMPTS.phase8_sprintRequirements;
        if (title.includes('sprint plan review')) return PROMPTS.phase8_sprintPlanReview;
        if (title.includes('critical review')) return PROMPTS.phase8_criticalReview;
        return PROMPTS.phase8_generic;
    }
    return PROMPTS.genericDocumentPrompt;
}

const getRelevantContext = (docToGenerate, allDocuments, allPhasesData) => {
    const sortedDocuments = [...allDocuments].sort((a, b) => a.phase - b.phase || (a.sequence || 1) - (b.sequence || 1));
    const currentIndex = sortedDocuments.findIndex(d => d.id === docToGenerate.id);
    const firstDoc = sortedDocuments[0];
    const firstDocPhaseData = firstDoc ? allPhasesData[firstDoc.id] : null;
    const firstDocContext = (firstDoc && firstDoc.status === 'Approved' && firstDocPhaseData?.compactedContent) ? firstDocPhaseData.compactedContent : '';
    const prevDoc = currentIndex > 0 ? sortedDocuments[currentIndex - 1] : null;
    const prevDocPhaseData = prevDoc ? allPhasesData[prevDoc.id] : null;
    const prevDocContext = (prevDoc && prevDoc.status === 'Approved' && prevDocPhaseData?.compactedContent) ? prevDocPhaseData.compactedContent : '';
    return { firstDocContext, prevDocContext };
};

const MAX_PAYLOAD_CHARS = 20000;
const truncatePrompt = (prompt: string): string => {
    if (prompt.length <= MAX_PAYLOAD_CHARS) return prompt;
    return prompt.substring(0, MAX_PAYLOAD_CHARS) + "\n...[PROMPT TRUNCATED]...";
};

export const ProjectDashboard: React.FC<{ project: Project; onBack: () => void; ai: GoogleGenAI; saveProject: (project: Project) => void; currentUser: User; key: number; }> = ({ project, onBack, ai, saveProject, currentUser }) => {
    const [projectData, setProjectData] = useState<Project>({ ...project });
    const [loadingPhase, setLoadingPhase] = useState<{ docId: string | null; step: string | null }>({ docId: null, step: null });
    const [error, setError] = useState('');
    const [activeTab, setActiveTab] = useState('Project Phases');
    const [isAutoGenerating, setIsAutoGenerating] = useState(false);
    const [isParsingPlan, setIsParsingPlan] = useState(false);
    const [selectedTask, setSelectedTask] = useState<Task | null>(null);
    const [aiReport, setAiReport] = useState({ title: '', content: '', isOpen: false });
    const [isGeneratingReport, setIsGeneratingReport] = useState<'risk' | 'summary' | null>(null);

    const projectDataRef = useRef(projectData);
    useEffect(() => { projectDataRef.current = projectData; }, [projectData]);

    const handleSave = useCallback((update: Partial<Project> | ((prev: Project) => Partial<Project>)) => {
        setProjectData(prevData => {
            const dataToMerge = typeof update === 'function' ? update(prevData) : update;
            const newState = { ...prevData, ...dataToMerge };
            saveProject(newState);
            return newState;
        });
    }, [saveProject]);

    const handleTabChange = useCallback((tabName) => {
        setActiveTab(tabName);
        localStorage.setItem(`hmap-active-tab-${project.id}`, tabName);
    }, [project.id]);

    useEffect(() => {
        const savedTab = localStorage.getItem(`hmap-active-tab-${project.id}`);
        setActiveTab(savedTab || 'Project Phases');
    }, [project.id]);

    const handleGenerateContent = useCallback(async (docId: string, userInput: string, projectStateOverride?: Project) => {
        const currentProjectData = projectStateOverride || projectDataRef.current;
        const docToGenerate = currentProjectData.documents.find(d => d.id === docId);
        if (!docToGenerate) return { success: false, newContent: null, newCompactedContent: null };

        setLoadingPhase({ docId, step: 'generating' });
        try {
            const { firstDocContext, prevDocContext } = getRelevantContext(docToGenerate, currentProjectData.documents, currentProjectData.phasesData);
            const contextString = `${firstDocContext}\n\n${prevDocContext}`.trim();
            const promptFn = getPromptFunction(docToGenerate.title, docToGenerate.phase);
            const prompt = truncatePrompt(promptFn(currentProjectData.name, currentProjectData.discipline, contextString, currentProjectData.mode, currentProjectData.scope, currentProjectData.teamSize, currentProjectData.complexity));

            // FIX: Explicitly type withRetry calls to avoid 'unknown' type errors and use correct model name.
            const result = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt }));
            const newContent = result.text;

            setLoadingPhase({ docId, step: 'compacting' });
            const compactPrompt = PROMPTS.compactContent(newContent);
            // FIX: Explicitly type withRetry calls to avoid 'unknown' type errors and use correct model name.
            const compactResult = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: compactPrompt }));
            const newCompactedContent = compactResult.text;

            handleSave(prev => ({
                phasesData: { ...prev.phasesData, [docId]: { ...(prev.phasesData[docId] || {}), content: newContent, compactedContent: newCompactedContent } },
                documents: prev.documents.map(d => d.id === docId ? { ...d, status: 'Approved' } : d)
            }));

            return { success: true, newContent, newCompactedContent };
        } catch (err: any) {
            setError(err.toString());
            return { success: false, newContent: null, newCompactedContent: null };
        } finally {
            setLoadingPhase({ docId: null, step: null });
        }
    }, [ai, handleSave]);

    // 3-Agent Project Plan Generation (Phase 7)
    const generateAgentPlan = useCallback(async () => {
        setIsParsingPlan(true);
        setError('');
        try {
            const contextDoc = projectData.documents.find(d => d.title.includes('Statement of Work'));
            const context = contextDoc ? projectData.phasesData[contextDoc.id]?.compactedContent : '';

            // 1. Planner Agent
            setLoadingPhase({ docId: 'agent', step: 'Planning Strategy...' });
            const plannerPrompt = PROMPTS.plannerAgent(context);
            const plannerRes = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: plannerPrompt });
            const plannerOutput = plannerRes.text;

            // 2. Doer Agent
            setLoadingPhase({ docId: 'agent', step: 'Generating Tasks...' });
            const doerPrompt = PROMPTS.doerAgent(plannerOutput, context);
            const doerRes = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: doerPrompt });
            const doerOutput = doerRes.text;

            // 3. QA Agent
            setLoadingPhase({ docId: 'agent', step: 'Validating Plan...' });
            const qaPrompt = PROMPTS.qaAgent(doerOutput);
            const qaRes = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: qaPrompt });
            const finalPlan = qaRes.text;

            const sections = finalPlan.split('## ');
            const tasksText = sections.find(s => s.toLowerCase().startsWith('tasks')) || '';
            const parsedTasks = parseMarkdownTable(tasksText);

            const taskMap = new Map();
            const newTasks = parsedTasks.map((t, i) => {
                const id = `task-${Date.now()}-${i}`;
                taskMap.set(t.task_name.toLowerCase().trim(), id);
                return {
                    id, name: t.task_name, role: t.role, startDate: t.start_date_yyyy_mm_dd, endDate: t.end_date_yyyy_mm_dd,
                    status: 'todo', sprintId: 'sprint1', dependsOn: t.dependencies ? t.dependencies.split(',').map(d => d.trim()) : [],
                    isSubcontracted: t.subcontractor?.toLowerCase() === 'yes', comments: [], attachments: []
                };
            });

            newTasks.forEach(t => {
                t.dependsOn = (t.dependsOn as any[]).map(d => taskMap.get(d.toLowerCase())).filter(Boolean);
            });

            handleSave({ tasks: newTasks, isStarted: true });
            handleTabChange('Project Tracking');
        } catch (e: any) {
            setError("Agentic planning failed: " + e.message);
        } finally {
            setIsParsingPlan(false);
            setLoadingPhase({ docId: null, step: null });
        }
    }, [ai, projectData, handleSave, handleTabChange]);

    const handleExportCsv = () => {
        const headers = ["ID", "Task Name", "Duration", "Start", "Finish", "Predecessors", "Resources"];
        const rows = projectData.tasks.map((t, i) => {
            const duration = Math.round((new Date(t.endDate).getTime() - new Date(t.startDate).getTime()) / (1000 * 3600 * 24)) + 1;
            return [i + 1, t.name, `${duration} days`, t.startDate, t.endDate, t.dependsOn.join(';'), t.role];
        });
        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = `${projectData.name}_MS_Project.csv`;
        link.click();
    };

    return (
        <section>
            <div className="dashboard-header">
                <button onClick={onBack} className="button back-button">← Back</button>
                <h1>{projectData.name}</h1>
                <p>{projectData.discipline} | Status: {projectData.isStarted ? 'Executing' : 'Planning'}</p>
            </div>
            <nav className="dashboard-nav">
                <button onClick={() => handleTabChange('Dashboard')} className={activeTab === 'Dashboard' ? 'active' : ''}>Dashboard</button>
                <button onClick={() => handleTabChange('Project Phases')} className={activeTab === 'Project Phases' ? 'active' : ''}>Phases</button>
                <button onClick={() => handleTabChange('Documents')} className={activeTab === 'Documents' ? 'active' : ''}>Docs</button>
                <button onClick={() => handleTabChange('Project Tracking')} className={activeTab === 'Project Tracking' ? 'active' : ''}>Tracking</button>
                <button onClick={() => handleTabChange('Revision Control')} className={activeTab === 'Revision Control' ? 'active' : ''}>Control</button>
                <button onClick={handleExportCsv} className="button button-small" style={{marginLeft: 'auto'}}>Export CSV</button>
            </nav>

            {loadingPhase.step && (
                <div className="status-message loading">
                    <div className="spinner"></div>
                    <p>{loadingPhase.step}</p>
                </div>
            )}

            {activeTab === 'Dashboard' && <DashboardView project={projectData} phasesData={projectData.phasesData} isPlanningComplete={projectData.documents.every(d => d.status === 'Approved')} projectPhases={[]} onAnalyzeRisks={() => {}} onGenerateSummary={() => {}} isGeneratingReport={null} />}
            {activeTab === 'Project Phases' && (
                <div>
                    <ProjectPhasesView project={projectData} projectPhases={[]} phasesData={projectData.phasesData} documents={projectData.documents} error={error} loadingPhase={loadingPhase} handleUpdatePhaseData={() => {}} handleCompletePhase={() => {}} handleGenerateContent={handleGenerateContent} handleAttachFile={() => {}} handleRemoveAttachment={() => {}} generationMode={projectData.generationMode} onSetGenerationMode={() => {}} isAutoGenerating={isAutoGenerating} />
                    {!projectData.isStarted && projectData.documents.every(d => d.status === 'Approved') && (
                        <div style={{textAlign: 'center', marginTop: '2rem'}}>
                            <button className="button button-primary" onClick={generateAgentPlan}>Run 3-Agent Planning Workflow</button>
                        </div>
                    )}
                </div>
            )}
            {activeTab === 'Documents' && <DocumentsView project={projectData} documents={projectData.documents} onUpdateDocument={() => {}} phasesData={projectData.phasesData} ai={ai} />}
            {activeTab === 'Project Tracking' && <ProjectTrackingView project={projectData} onUpdateTask={() => {}} onUpdateMilestone={() => {}} onUpdateTeam={() => {}} onUpdateProject={handleSave} onTaskClick={setSelectedTask} currentUser={currentUser} />}
            {activeTab === 'Revision Control' && <RevisionControlView project={projectData} onUpdateProject={handleSave} ai={ai} />}

            {selectedTask && <TaskDetailModal isOpen={!!selectedTask} onClose={() => setSelectedTask(null)} onSave={(t) => handleSave(p => ({ tasks: p.tasks.map(x => x.id === t.id ? t : x) }))} task={selectedTask} project={projectData} currentUser={currentUser} />}
        </section>
    );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Type } from "@google/genai";
import { TEMPLATES, PROMPTS } from '../constants/projectData';
import { Project } from '../types';

export const NewProjectModal = ({ isOpen, onClose, onCreateProject, projects, onSelectProject, onRequestDelete, ai, currentUser }) => {
  const [name, setName] = useState('');
  const [selectedTemplateId, setSelectedTemplateId] = useState(null);
  const [projectMode, setProjectMode] = useState(null); // 'fullscale' or 'minimal'
  const [projectScope, setProjectScope] = useState(null); // 'internal' or 'subcontracted'
  const [teamSize, setTeamSize] = useState(null); // 'small', 'medium', or 'large'
  const [projectComplexity, setProjectComplexity] = useState('typical'); // 'easy', 'typical', 'complex'
  const [activeTab, setActiveTab] = useState('create');
  const [creationMode, setCreationMode] = useState(null); // 'template' or 'custom'
  const [customDiscipline, setCustomDiscipline] = useState('');
  const [isGeneratingDocs, setIsGeneratingDocs] = useState(false);
  const [error, setError] = useState('');
  const modalRef = useRef(null);

  const selectedTemplate = useMemo(() => TEMPLATES.find(t => t.id === selectedTemplateId), [selectedTemplateId]);

  const userProjects: Project[] = projects;

  useEffect(() => {
    if (isOpen) {
        modalRef.current?.focus();
        setActiveTab(userProjects && userProjects.length > 0 ? 'select' : 'create');
    }
  }, [isOpen, userProjects]);

  useEffect(() => {
    if (!isOpen) return;

    const handleEsc = (event) => {
        if (event.key === 'Escape') {
            onClose();
        }
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [isOpen, onClose]);

  const resetAndClose = () => {
      onClose();
      setName('');
      setSelectedTemplateId(null);
      setProjectMode(null);
      setProjectScope(null);
      setTeamSize(null);
      setProjectComplexity('typical');
      setCreationMode(null);
      setCustomDiscipline('');
      setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!projectMode) { setError("Please select a project mode (Full Scale or Minimal Viable)."); return; }
    if (!projectScope) { setError("Please select a project scope (Internal or Subcontracted)."); return; }
    if (!teamSize) { setError("Please select a team size."); return; }
     if (!projectComplexity) { setError("Please select a project complexity."); return; }
    if (!name.trim()) { setError("Please enter a project name."); return; }
    if (!creationMode) { setError("Please choose a template option ('Use a Template' or 'Create My Own')."); return; }
    if (creationMode === 'template' && !selectedTemplateId) { setError("Please select a project template from the list."); return; }
    if (creationMode === 'custom' && !customDiscipline.trim()) { setError("Please enter a custom project type."); return; }

    let template;
    if (creationMode === 'template') {
        template = TEMPLATES.find(t => t.id === selectedTemplateId);
        if (!template) return;
        onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
    } else {
        setIsGeneratingDocs(true);
        try {
            const prompt = PROMPTS.generateDocumentList(customDiscipline.trim(), projectScope, teamSize, projectComplexity);
            const schema = {
                type: Type.OBJECT, properties: { documents: {
                        type: Type.ARRAY, description: "A list of project documents.", items: { type: Type.OBJECT, properties: {
                                title: { type: Type.STRING, description: "The name of the document." },
                                phase: { type: Type.NUMBER, description: "The HMAP phase number (1-9) the document belongs to." },
                                sequence: { type: Type.NUMBER, description: "The logical order for generation within a phase, starting from 1." }
                            }, required: ['title', 'phase', 'sequence']
                        }
                    }
                }, required: ['documents']
            };
            // FIX: Use 'gemini-3-flash-preview' for basic text tasks according to guidelines.
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview', contents: prompt, config: { responseMimeType: "application/json", responseSchema: schema },
            });
            const rawDocs = JSON.parse(response.text).documents;
            const generatedDocs = rawDocs.map((doc, i) => ({
                id: `doc-custom-${i}-${Date.now()}`, title: doc.title, version: 'v1.0', status: 'Working', owner: 'A. User', phase: doc.phase, sequence: doc.sequence,
            }));
            template = { id: 'custom', name: 'Custom Project', discipline: customDiscipline.trim(), documents: generatedDocs };
            onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
        } catch (error) {
            console.error("Failed to generate custom document list:", error);
            alert("Could not generate the document list for your custom project type. Please check the console and try again.");
        } finally {
            setIsGeneratingDocs(false);
        }
    }
  };

  const handleSelect = (project) => {
    onSelectProject(project);
    onClose();
  };

