import React, { useState, useMemo, useEffect } from 'react';
import { Type, GoogleGenAI } from "@google/genai";
import { logAction } from '../utils/logging';
import { PROMPTS } from '../constants/projectData';
import { ChangeDeploymentModal } from '../components/ChangeDeploymentModal';
import { parseImpact, applyImpact } from '../utils/be-logic';

// Safety limits for API payload
const MAX_PAYLOAD_CHARS = 20000; // Drastically reduced to prevent potential 500 errors from large requests.

const truncatePrompt = (prompt: string): string => {
    if (prompt.length <= MAX_PAYLOAD_CHARS) {
        return prompt;
    }

    console.warn('Prompt is too large, truncating from the end to fit payload limits.');
    logAction('Truncate Prompt', 'Payload Management', { originalLength: prompt.length, newLength: MAX_PAYLOAD_CHARS });

    return prompt.substring(0, MAX_PAYLOAD_CHARS) + "\n...[PROMPT TRUNCATED DUE TO PAYLOAD SIZE]...";
};

export const RevisionControlView = ({ project, onUpdateProject, ai }: {project: any, onUpdateProject: (update: any) => void, ai: GoogleGenAI}) => {
    const { changeRequest: cr, scenarios, name, discipline, tasks, documents, budget, endDate } = project;
    const [newScenario, setNewScenario] = useState({ name: '', impactStr: '' });
    const [deploymentPlan, setDeploymentPlan] = useState('');
    const [isGeneratingPlan, setIsGeneratingPlan] = useState(false);
    const [isDeploying, setIsDeploying] = useState(false);
    const [isEstimating, setIsEstimating] = useState(false);
    const [error, setError] = useState('');

    const handleCrChange = (newCrData) => {
        onUpdateProject({ changeRequest: newCrData });
        logAction('Update Change Request', name, newCrData);
    };

    const handleScenariosChange = (newScenarios) => {
        onUpdateProject({ scenarios: newScenarios });
        logAction('Update Scenarios', name, newScenarios);
    };

    const handleAddScenario = (e) => {
        e.preventDefault();
        if (newScenario.name && newScenario.impactStr) {
            const updatedScenarios = [...scenarios, { id: Date.now(), ...newScenario }];
            handleScenariosChange(updatedScenarios);
            setNewScenario({ name: '', impactStr: '' });
        }
    };

    const handleEstimateImpact = async () => {
        if (!cr.title || !cr.reason) {
            alert("Please provide a title and reason for the change request before estimating impact.");
            return;
        }
        setIsEstimating(true);
        setError('');
        try {
            const prompt = PROMPTS.estimateChangeImpact(name, discipline, budget, cr);
            const schema = {
                type: Type.OBJECT,
                properties: {
                    days: { type: Type.NUMBER, description: 'Estimated schedule impact in days (positive for delay, negative for acceleration).' },
                    cost: { type: Type.NUMBER, description: 'Estimated budget impact in currency (positive for cost increase, negative for savings).' }
                },
                required: ['days', 'cost']
            };
            // FIX: Use 'gemini-3-flash-preview' for basic text tasks according to guidelines.
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview', contents: prompt, config: { responseMimeType: "application/json", responseSchema: schema },
            });
            const impact = JSON.parse(response.text);
            const newImpactStr = `${impact.days >= 0 ? '+' : ''}${impact.days}d ${impact.cost >= 0 ? '+' : ''}${impact.cost}c`;
            handleCrChange({ ...cr, impactStr: newImpactStr });
        } catch (err) {
            console.error("API Error estimating impact:", err);
            setError("Failed to estimate impact. Please check the console and try again.");
        } finally {
            setIsEstimating(false);
        }
    };

    const handleGeneratePlan = async () => {
        if (!cr.title || !cr.reason) {
            alert("Please provide a title and reason for the change request before generating a plan.");
            return;
        }
        setIsGeneratingPlan(true);
        setError('');
        try {
            const promptFn = PROMPTS.changeDeploymentPlan;
            const promptText = promptFn(name, discipline, cr, tasks, documents);
            const prompt = truncatePrompt(promptText);
            logAction('Generate Change Plan', name, { promptLength: prompt.length });

            // FIX: Use 'gemini-3-flash-preview' for basic text tasks according to guidelines.
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: prompt,
            });

            setDeploymentPlan(response.text);
            logAction('Generate Change Plan Success', name, { plan: response.text });
        } catch (err) {
            console.error("API Error generating deployment plan:", err);
            setError("Failed to generate the deployment plan. Please check the console and try again.");
            logAction('Generate Change Plan Failure', name, { error: err.message });
        } finally {
            setIsGeneratingPlan(false);
        }
    };

    const baseline = useMemo(() => ({
        budget: budget,
        endDate: endDate,
    }), [budget, endDate]);

    const crImpact = useMemo(() => parseImpact(cr.impactStr), [cr.impactStr]);
    const crResult = useMemo(() => applyImpact(baseline, crImpact), [baseline, crImpact]);

    const scenarioResults = useMemo(() => scenarios.map(s => ({
        ...s,
        impact: parseImpact(s.impactStr),
        result: applyImpact(baseline, parseImpact(s.impactStr))
    })), [scenarios, baseline]);

    const currencyFormat = (num) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(num);

    const ImpactCell = ({ value, base }) => {
        const diff = value - base;
        const className = diff > 0 ? 'impact-positive' : diff < 0 ? 'impact-negative' : '';
        const sign = diff > 0 ? '+' : '';
        return <>{currencyFormat(value)} {diff !== 0 && <span className={className}>({sign}{currencyFormat(diff)})</span>}</>
    };

    const handleSaveChange = () => {
        if (!cr.title) {
            alert("Please provide a title for the change request before saving.");
            return;
        }

        const changeDocContent = `
# Change Request: ${cr.title}

## Reason for Change
${cr.reason}

## Estimated Impact
- **Time:** ${crImpact.days > 0 ? '+' : ''}${crImpact.days} days
- **Cost:** ${crImpact.cost > 0 ? '+' : ''}${currencyFormat(crImpact.cost)}

## What-If Scenarios Analysis

| Metric   | Baseline              | CR Impact             | ${scenarios.map(s => s.name).join(' | ')} |
|----------|-----------------------|-----------------------|${scenarios.map(() => '-----------------------').join('|')}
| End Date | ${baseline.endDate}   | ${crResult.endDate}   | ${scenarioResults.map(s => s.result.endDate).join(' | ')} |
| Budget   | ${currencyFormat(baseline.budget)} | ${currencyFormat(crResult.budget)} | ${scenarioResults.map(s => currencyFormat(s.result.budget)).join(' | ')} |
`;

        const newDoc = {
            id: `doc-cr-${Date.now()}`,
            title: `Change Request: ${cr.title}`,
            version: 'v1.0',
            status: 'Working',
            owner: 'A. User',
            phase: 8, // Associate with Sprint/Critical Design Planning
            content: changeDocContent.trim(),
        };

        const updatedDocuments = [...documents, newDoc];
        onUpdateProject({ documents: updatedDocuments });

        logAction('Save Change Request as Document', name, { document: newDoc });
        alert(`Document "${newDoc.title}" has been created and added to the Documents Center for approval.`);
    };

    return (
        <div className="tool-card">
            <h2 className="subsection-title">Revision & Change Control</h2>
            <div className="tool-grid" style={{ gridTemplateColumns: '1fr 2fr', gap: '2rem', alignItems: 'start' }}>
                <div>
                    <h4>Submit Change Request</h4>
                    <form>
                        <div className="form-group"><label>Title</label><input type="text" value={cr.title} onChange={e => handleCrChange({...cr, title: e.target.value})} /></div>
                        <div className="form-group"><label>Reason for Change</label><textarea rows={3} value={cr.reason} onChange={e => handleCrChange({...cr, reason: e.target.value})}></textarea></div>
                        <div className="form-group">
                            <label>Impact (e.g. +15d +5000c)</label>
                            <div style={{display: 'flex', gap: '0.5rem', alignItems: 'center'}}>
                                <input type="text" value={cr.impactStr} onChange={e => handleCrChange({...cr, impactStr: e.target.value})} style={{flexGrow: 1}}/>
                                <button type="button" className="button button-small" onClick={handleEstimateImpact} disabled={isEstimating || !ai}>
                                    {isEstimating ? '...' : 'Estimate'}
                                </button>
                            </div>
                        </div>
                    </form>

                    <h4 style={{marginTop: '2rem'}}>What-If Scenarios</h4>
                    <form onSubmit={handleAddScenario} style={{display: 'flex', gap: '1rem'}}>
                         <input type="text" placeholder="Scenario Name" value={newScenario.name} onChange={e => setNewScenario({...newScenario, name: e.target.value})} style={{flex: 1}}/>
                         <input type="text" placeholder="+10d -2000c" value={newScenario.impactStr} onChange={e => setNewScenario({...newScenario, impactStr: e.target.value})} style={{flex: 1}}/>
                         <button type="submit" className="button button-small">Add</button>
                    </form>
                </div>
                <div>
                    <h4>Auto Impact Analysis for "{cr.title}"</h4>
                    <table className="impact-table">
                        <thead>
                            <tr>
                                <th>Metric</th>
                                <th>Baseline</th>
                                <th>CR Impact</th>
                                {scenarioResults.map(s => <th key={s.id}>{s.name}</th>)}
                            </tr>
                        </thead>
                        <tbody>
                            <tr>
                                <td>End Date</td>
                                <td>{baseline.endDate}</td>
                                <td>{crResult.endDate} <span className={crImpact.days > 0 ? 'impact-positive' : ''}>{crImpact.days !== 0 && `(${crImpact.days > 0 ? '+':''}${crImpact.days}d)`}</span></td>
                                {scenarioResults.map(s => <td key={s.id}>{s.result.endDate} <span className={s.impact.days > 0 ? 'impact-positive' : ''}>{s.impact.days !== 0 && `(${s.impact.days > 0 ? '+':''}${s.impact.days}d)`}</span></td>)}
                            </tr>
                             <tr>
                                <td>Budget</td>
                                <td>{currencyFormat(baseline.budget)}</td>
                                <td><ImpactCell value={crResult.budget} base={baseline.budget} /></td>
                                {scenarioResults.map(s => <td key={s.id}><ImpactCell value={s.result.budget} base={baseline.budget} /></td>)}
                            </tr>
                        </tbody>
                    </table>
                     <div style={{marginTop: '1.5rem', display: 'flex', justifyContent: 'flex-end', gap: '1rem'}}>
                        <button className="button" onClick={handleSaveChange}>Save Change</button>
                        <button className="button button-primary">Submit for Approval</button>
                    </div>
                </div>
            </div>

            <div style={{borderTop: '1px solid var(--border-color)', marginTop: '2rem', paddingTop: '2rem'}}>
                <h3 className="subsection-title">Change Deployment</h3>
                <div className="form-group">
                    <label htmlFor="deploymentPlan">AI-Generated Deployment Plan</label>
                    <textarea 
                        id="deploymentPlan"
                        rows={12}
                        value={isGeneratingPlan ? 'Generating plan...' : deploymentPlan}
                        onChange={(e) => setDeploymentPlan(e.target.value)}
                        placeholder="Click 'Generate Deployment Plan' to create a step-by-step plan to implement this change."
                        readOnly={isGeneratingPlan}
                    />
                </div>
                {error && <p className="status-message error">{error}</p>}
                <div style={{display: 'flex', gap: '1rem'}}>
                    <button className="button" onClick={handleGeneratePlan} disabled={isGeneratingPlan || !ai}>
                        {isGeneratingPlan ? 'Generating...' : (deploymentPlan ? 'Regenerate Plan' : 'Generate Deployment Plan')}
                    </button>
                    <button className="button button-primary" onClick={() => setIsDeploying(true)} disabled={!deploymentPlan || isGeneratingPlan}>
                        Deploy Change...
                    </button>
                </div>
            </div>

            <ChangeDeploymentModal
                isOpen={isDeploying}
                onClose={() => setIsDeploying(false)}
                deploymentPlan={deploymentPlan}
                project={project}
                onUpdateProject={onUpdateProject}
            />
        </div>
    );
};

import { User } from '../types';

const USERS_KEY = 'hmap-users';
const SESSION_KEY = 'hmap-session';

const getUsers = (): User[] => {
    try {
        const users = localStorage.getItem(USERS_KEY);
        return users ? JSON.parse(users) : [];
    } catch (error) {
        console.error("Error parsing users from localStorage", error);
        return [];
    }
};

const saveUsers = (users: User[]) => {
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
};

export const register = (username, email, password): User | null => {
    const users = getUsers();
    if (users.some(u => u.username === username || u.email === email)) {
        return null; // User already exists
    }
    const newUser: User = { 
        id: `user-${Date.now()}`, 
        username, 
        email, 
        password,
        notificationPrefs: {
            teams: false,
            slack: false,
            outlook: false,
            gmail: false
        }
    };
    saveUsers([...users, newUser]);
    return newUser;
};

export const login = (email, password): User | null => {
    const users = getUsers();
    const user = users.find(u => u.email === email && u.password === password);
    if (user) {
        // Persist the full user object to the session
        localStorage.setItem(SESSION_KEY, JSON.stringify(user));
        return user;
    }
    return null;
};

export const updateUser = (updatedUser: User) => {
    const users = getUsers();
    const updatedUsers = users.map(u => u.id === updatedUser.id ? updatedUser : u);
    saveUsers(updatedUsers);

    // Also update active session if it's the same user
    const session = getCurrentUser();
    if (session && session.id === updatedUser.id) {
        localStorage.setItem(SESSION_KEY, JSON.stringify(updatedUser));
    }
};

export const logout = () => {
    localStorage.removeItem(SESSION_KEY);
};

export const getCurrentUser = (): User | null => {
    try {
        const session = localStorage.getItem(SESSION_KEY);
        if (session) {
            return JSON.parse(session);
        }
        // For first-time run, create a default user
        if (getUsers().length === 0) {
            const defaultUser = register('A. User', 'user@example.com', 'password123');
            if(defaultUser) {
                 return login(defaultUser.email, 'password123');
            }
        }
        return null;
    } catch (error) {
        console.error("Error parsing current user from localStorage", error);
        return null;
    }
};

import { GoogleGenAI } from "@google/genai";
import React, { useState, useEffect, useMemo } from 'react';
import { Header } from './components/Header';
import { LandingPage } from './views/LandingPage';
import { ProjectDashboard } from './views/ProjectDashboard';
import { NewProjectModal } from './components/NewProjectModal';
import { DeleteProjectConfirmationModal } from './components/DeleteProjectConfirmationModal';
import { HelpModal } from './components/HelpModal';
import { GlobalStyles } from './styles/GlobalStyles';
import { DEFAULT_SPRINTS, TEMPLATES, DEFAULT_DOCUMENTS } from './constants/projectData';
import { logAction } from './utils/logging';
import { AuthView } from './views/AuthView';
import * as authService from './utils/authService';
import { subscribeToUpdates, notifyUpdate } from './utils/syncService';
import { Project, Task, Notification, User } from './types';

const App = () => {
  const [ai, setAi] = useState<GoogleGenAI | null>(null);
  const [projects, setProjects] = useState<Project[]>([]);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteConfirmationOpen, setIsDeleteConfirmationOpen] = useState(false);
  const [projectToDelete, setProjectToDelete] = useState<Project | null>(null);
  const [isHelpModalOpen, setIsHelpModalOpen] = useState(false);
  const [apiKeyStatus, setApiKeyStatus] = useState('pending');
  const [currentUser, setCurrentUser] = useState<User | null>(authService.getCurrentUser());
  const [appKey, setAppKey] = useState(0); 
  const [recentlyViewedIds, setRecentlyViewedIds] = useState<string[]>([]);

  const userProjects = useMemo(() => {
    if (!projects || !currentUser) return [];
    return projects.filter(p => p.ownerId === currentUser.id || p.team?.some(member => member.userId === currentUser.id));
  }, [projects, currentUser]);

  const recentlyViewedProjects = useMemo(() => {
    if (!projects || recentlyViewedIds.length === 0) return [];
    const userProjectIds = new Set(userProjects.map(p => p.id));
    return recentlyViewedIds
        .map(id => projects.find(p => p.id === id))
        .filter((p): p is Project => !!p && userProjectIds.has(p.id));
  }, [projects, userProjects, recentlyViewedIds]);

  const reloadStateFromStorage = () => {
    logAction('Sync Update', 'BroadcastChannel', { message: 'Forcing state reload from localStorage' });
    const storedProjects = localStorage.getItem('hmap-projects');
    const storedUser = authService.getCurrentUser();

    if (storedUser) {
        setCurrentUser(storedUser);
    }

    if (storedProjects) {
        const parsed = JSON.parse(storedProjects);
        setProjects(parsed);

        const selectedProjectId = localStorage.getItem('hmap-selected-project-id');
        if (selectedProjectId) {
            const updatedSelectedProject = parsed.find(p => p.id === selectedProjectId);
            if (updatedSelectedProject) {
                setSelectedProject(updatedSelectedProject);
            }
        }
    }
    setAppKey(prev => prev + 1); 
  };

  useEffect(() => {
    const unsubscribe = subscribeToUpdates(reloadStateFromStorage);
    return () => unsubscribe();
  }, [selectedProject]);


  const initializeAi = (key: string, source: string) => {
    try {
      const genAI = new GoogleGenAI({ apiKey: key });
      setAi(genAI);
      setApiKeyStatus(source);
      if (source === 'user') {
        localStorage.setItem('hmap-gemini-key', key);
      }
      return true;
    } catch (error: any) {
      console.error(`Failed to initialize GoogleGenAI from ${source}:`, error);
      return false;
    }
  };

  const handleSetUserKey = (key: string | null) => {
    if (key === null) { 
        setAi(null);
        localStorage.removeItem('hmap-gemini-key');
        setApiKeyStatus('none');
        logAction('Clear API Key', 'User Action', { apiKeyStatus: 'none' });
        return;
    }
    if (initializeAi(key, 'user')) {
        logAction('Set API Key', 'User Action', { apiKeyStatus: 'user' });
    } else {
        alert('The provided API Key appears to be invalid. Please check it and try again.');
    }
  };

  useEffect(() => {
    try {
      const storedProjects = localStorage.getItem('hmap-projects');
      if (storedProjects) {
        setProjects(JSON.parse(storedProjects));
      } else {
        localStorage.setItem('hmap-projects', JSON.stringify([]));
      }
      const storedRecentIds = localStorage.getItem('hmap-recently-viewed');
      if (storedRecentIds) {
          setRecentlyViewedIds(JSON.parse(storedRecentIds));
      }
    } catch (error: any) {
        console.error("Failed to load data from localStorage:", error);
        setProjects([]);
    }

    const userKey = localStorage.getItem('hmap-gemini-key');
    if (userKey) {
      if (initializeAi(userKey, 'user')) return;
      else localStorage.removeItem('hmap-gemini-key');
    }

    if (process.env.API_KEY) {
      if (initializeAi(process.env.API_KEY, 'promo')) return;
    }

    setApiKeyStatus('none');
  }, []);

  useEffect(() => {
    const selectedProjectId = localStorage.getItem('hmap-selected-project-id');

    if (currentUser && selectedProjectId && projects.length > 0) {
        const projectToSelect = projects.find(p => p.id === selectedProjectId);

        if (projectToSelect) {
            const isOwnerOrMember = projectToSelect.ownerId === currentUser.id || 
                                  projectToSelect.team?.some(member => member.userId === currentUser.id);
            if (isOwnerOrMember) {
                setSelectedProject(projectToSelect);
            } else {
                setSelectedProject(null);
                localStorage.removeItem('hmap-selected-project-id');
            }
        } else {
            localStorage.removeItem('hmap-selected-project-id');
        }
    } else if (!currentUser) {
        setSelectedProject(null);
    }
  }, [currentUser, projects]);

  const saveProjectsToStorage = (updatedProjects: Project[]) => {
    try {
      localStorage.setItem('hmap-projects', JSON.stringify(updatedProjects));
      notifyUpdate();
    } catch (e: any) {
      console.error("Failed to save projects to localStorage:", e);
    }
  };

  const handleCreateProject = ({ name, template, mode, scope, teamSize, complexity }) => {
    if (!currentUser) return;
    const today = new Date();
    const endDate = new Date(today);
    endDate.setDate(today.getDate() + 44);

    const projectDocuments = JSON.parse(JSON.stringify(template.documents || DEFAULT_DOCUMENTS));

    const mandatoryDocs = [
        { title: 'Statement of Work (SOW)', phase: 5, sequence: 1 },
        { title: 'Resources & Skills List', phase: 2, sequence: 1 },
        { title: 'Detailed Plans (WBS/WRS)', phase: 7, sequence: 1 }
    ];

    mandatoryDocs.forEach(mandatoryDoc => {
        const simpleTitle = mandatoryDoc.title.replace(/\s\(.*\)/, '');
        const hasDoc = projectDocuments.some(doc => doc.title.includes(simpleTitle));

        if (!hasDoc) {
            projectDocuments.push({
                id: `doc-mandatory-${Date.now()}-${mandatoryDoc.title.toLowerCase().replace(/[^a-z0-9]/g, '-')}`,
                title: mandatoryDoc.title, version: 'v1.0', status: 'Working', owner: 'A. User', phase: mandatoryDoc.phase,
                sequence: mandatoryDoc.sequence,
            });
        }
    });

    if (scope === 'subcontracted') {
        const hasRFP = projectDocuments.some(doc => doc.title.toLowerCase().includes('request for proposal') || doc.title.toLowerCase().includes('rfp'));
        if (!hasRFP) {
            projectDocuments.push({
                id: `doc-subco-${Date.now()}-rfp`, title: 'Request for Proposal (RFP)', version: 'v1.0', status: 'Working', owner: 'A. User', phase: 2, sequence: 50,
            });
        }

        const hasContract = projectDocuments.some(doc => doc.title.toLowerCase().includes('contract') || doc.title.toLowerCase().includes('agreement'));
        if (!hasContract) {
             projectDocuments.push({
                id: `doc-subco-${Date.now()}-contract`, title: "Draft Contract with T's & C's", version: 'v1.0', status: 'Working', owner: 'A. User', phase: 5, sequence: 50,
            });
        }
    }

    const newProject: Project = { 
        id: Date.now().toString(), name, mode, scope, generationMode: 'manual', teamSize, complexity: complexity || 'typical', discipline: template.discipline,
        ownerId: currentUser.id,
        phasesData: {},
        team: [{ userId: currentUser.id, role: 'Project Owner', name: currentUser.username, email: currentUser.email }],
        documents: projectDocuments, tasks: [], sprints: JSON.parse(JSON.stringify(DEFAULT_SPRINTS)), milestones: [], resources: [],
        avgBurdenedLaborRate: 125, budget: 100000,
        startDate: today.toISOString().split('T')[0],
        endDate: endDate.toISOString().split('T')[0],
        changeRequest: { title: 'Add new login provider', reason: 'User request for SSO', impactStr: '+15d +5000c' },
        scenarios: [
            { id: 1, name: 'A: Use contractors', impactStr: '+10d +8000c' },
            { id: 2, name: 'B: Defer feature', impactStr: '+0d +0c' },
        ],
        notifications: [],
    };
    const updatedProjects = [...projects, newProject];
    setProjects(updatedProjects);
    saveProjectsToStorage(updatedProjects);

    // Persistent project creation context
    localStorage.setItem('hmap-new-project-id', newProject.id);
    handleSelectProject(newProject);
    handleModalOpen(false);
    logAction('Create Project', newProject.name, { newProject, allProjects: updatedProjects });
  };

  const handleSaveProject = (updatedProject: Project) => {
    const updatedProjects = projects.map(p => p.id === updatedProject.id ? updatedProject : p);
    setProjects(updatedProjects);
    saveProjectsToStorage(updatedProjects);
    if(selectedProject && selectedProject.id === updatedProject.id) {
        setSelectedProject(updatedProject);
    }
    logAction('Save Project', updatedProject.name, { updatedProject });
  };

  const handleSelectProject = (project: Project | null) => {
    logAction('Select Project', project ? project.name : 'Home', { projectId: project ? project.id : null });
    setSelectedProject(project);
    if (project) {
        localStorage.setItem('hmap-selected-project-id', project.id);
        const MAX_RECENT = 4;
        const updatedRecentIds = [
            project.id,
            ...recentlyViewedIds.filter(id => id !== project.id)
        ].slice(0, MAX_RECENT);

        setRecentlyViewedIds(updatedRecentIds);
        localStorage.setItem('hmap-recently-viewed', JSON.stringify(updatedRecentIds));
    } else {
        localStorage.removeItem('hmap-selected-project-id');
    }
  };

  const handleSelectTask = (project: Project, task: Task) => {
    logAction('Select Task from My Work', task.name, { projectId: project.id, taskId: task.id });
    handleSelectProject(project);
    // Use localStorage for cross-tab and crash survival
    localStorage.setItem('hmap-open-task-on-load', task.id);
    setAppKey(prev => prev + 1);
  };

  const handleModalOpen = (isOpen: boolean) => {
    logAction('Toggle New Project Modal', 'Modal', { isOpen });
    setIsModalOpen(isOpen);
  };

  const cleanupProjectData = (projectId: string) => {
    localStorage.removeItem('hmap-selected-project-id');
    localStorage.removeItem(`hmap-active-tab-${projectId}`);
    localStorage.removeItem(`hmap-open-phases-${projectId}`);
    localStorage.removeItem(`hmap-tracking-view-${projectId}`);
    logAction('Cleanup Project Data', 'localStorage', { projectId });
  };

  const handleNewProjectRequest = () => {
    logAction('Open Project Manager', 'User Action', {});
    handleModalOpen(true);
  };

  const handleRequestDeleteProject = (project: Project) => {
    logAction('Request Project Deletion', project.name, { projectId: project.id });
    setProjectToDelete(project);
    setIsDeleteConfirmationOpen(true);
    handleModalOpen(false);
  };

  const handleConfirmDeletion = () => {
    if (!projectToDelete) return;
    logAction('Confirm Delete Project', projectToDelete.name, { projectId: projectToDelete.id });
    const updatedProjects = projects.filter(p => p.id !== projectToDelete.id);
    setProjects(updatedProjects);
    saveProjectsToStorage(updatedProjects);
    cleanupProjectData(projectToDelete.id);
    const updatedRecentIds = recentlyViewedIds.filter(id => id !== projectToDelete.id);
    setRecentlyViewedIds(updatedRecentIds);
    localStorage.setItem('hmap-recently-viewed', JSON.stringify(updatedRecentIds));
    if (selectedProject && selectedProject.id === projectToDelete.id) {
        setSelectedProject(null);
    }
    setProjectToDelete(null);
    setIsDeleteConfirmationOpen(false);
  };

  const handleToggleHelpModal = (isOpen: boolean) => {
      logAction('Toggle Help Modal', 'UI Action', { isOpen });
      setIsHelpModalOpen(isOpen);
  };

  const handleNotificationClick = (notification: Notification) => {
    if (!selectedProject) return;

    logAction('Click Notification', notification.text, { notificationId: notification.id });

    const updatedNotifications = selectedProject.notifications.map(n => 
        n.id === notification.id ? { ...n, read: true } : n
    );

    const updatedProject = { ...selectedProject, notifications: updatedNotifications };
    handleSaveProject(updatedProject); 

    const task = selectedProject.tasks.find(t => t.id === notification.taskId);
    if (task) {
        localStorage.setItem('hmap-open-task-on-load', notification.taskId);
        setAppKey(prev => prev + 1);
    }
  };

  const handleMarkAllRead = () => {
    if (!selectedProject) return;

    logAction('Mark All Notifications Read', 'User Action', { projectId: selectedProject.id });

    const updatedNotifications = selectedProject.notifications.map(n => ({ ...n, read: true }));
    const updatedProject = { ...selectedProject, notifications: updatedNotifications };
    handleSaveProject(updatedProject);
  };

  const handleLogout = () => {
    authService.logout();
    setCurrentUser(null);
    setSelectedProject(null);
    localStorage.removeItem('hmap-selected-project-id');
  };

  return (
    <>
        <style>{GlobalStyles}</style>

        {!currentUser ? (
            <AuthView onLogin={(user) => setCurrentUser(user)} />
        ) : (
            <>
                <Header 
                    onNewProject={handleNewProjectRequest} 
                    onHomeClick={() => handleSelectProject(null)}
                    disabled={!ai}
                    isLandingPage={!selectedProject}
                    currentUser={currentUser}
                    onLogout={handleLogout}
                    notifications={selectedProject?.notifications || []}
                    onNotificationClick={handleNotificationClick}
                    onMarkAllRead={handleMarkAllRead}
                />
                <main>
                    {selectedProject ? (
                        <ProjectDashboard 
                            project={selectedProject} 
                            onBack={() => handleSelectProject(null)} 
                            ai={ai}
                            saveProject={handleSaveProject}
                            currentUser={currentUser}
                            key={appKey}
                        />
                    ) : (
                        <LandingPage
                            projects={userProjects}
                            onSelectProject={handleSelectProject}
                            onNewProject={handleNewProjectRequest}
                            apiKeyStatus={apiKeyStatus}
                            onSetUserKey={handleSetUserKey}
                            disabled={!ai}
                            onRequestDelete={handleRequestDeleteProject}
                            currentUser={currentUser}
                            onSelectTask={handleSelectTask}
                            recentlyViewedProjects={recentlyViewedProjects}
                        />
                    )}
                </main>
                <NewProjectModal 
                    isOpen={isModalOpen} 
                    onClose={() => handleModalOpen(false)} 
                    onCreateProject={handleCreateProject}
                    projects={userProjects}
                    onSelectProject={handleSelectProject}
                    onRequestDelete={handleRequestDeleteProject}
                    ai={ai}
                    currentUser={currentUser}
                />
                {projectToDelete && (
                  <DeleteProjectConfirmationModal
                      isOpen={isDeleteConfirmationOpen}
                      onClose={() => {
                          logAction('Cancel Project Deletion', projectToDelete.name, { projectId: projectToDelete.id });
                          setIsDeleteConfirmationOpen(false);
                          setProjectToDelete(null);
                      }}
                      onConfirm={handleConfirmDeletion}
                      projectName={projectToDelete.name}
                  />
                )}
            </>
        )}

        <button className="help-fab" onClick={() => handleToggleHelpModal(true)} aria-label="Open Help">?</button>
        <HelpModal isOpen={isHelpModalOpen} onClose={() => handleToggleHelpModal(false)} />
    </>
  );
};

