            </div>

            {/* Main Content Area */}
            <div style={{ gridColumn: 'span 8', display: 'flex', flexDirection: 'column', gap: '2.5rem' }}>
                <div className="tool-card">
                    <h3 className="subsection-title">Phase Roadmap</h3>
