  }

  /* BUTTONS */
  .button {
    padding: 1rem 2rem;
    border: 1px solid var(--card-border);
    background: var(--glass-bg);
    color: var(--primary-text);
    border-radius: var(--radius-sm);
    cursor: pointer;
    text-transform: uppercase;
    font-weight: 700;
    letter-spacing: 1px;
