import React, { useState, useEffect, useRef } from 'react';
import { parseMarkdown } from '../utils/markdownParser';
import { GRAPHICAL_ARTIFACTS } from '../constants/projectData';

interface PhaseCardProps {
    phase: { id: string; title: string; description: string; originalPhaseId: string; };
    project: any;
    phaseData: string | undefined;
    images?: string[];
    selectedArtifacts?: string[];
    attachments: Array<{ name: string, data: string }>;
    updatePhaseData: (phaseId: string, content: string) => void;
    isLocked: boolean;
    lockReason: string | null;
    onGenerate: (phaseId: string, currentContent: string) => void;
    onGenerateImages: (phaseId: string, artifacts: string[], content: string) => void;
    onChatToChange: (phaseId: string, instruction: string) => void;
    onComplete: (phaseId: string) => void;
    onAttachFile: (phaseId: string, fileData: { name: string, data: string }) => void;
    onRemoveAttachment: (phaseId: string, fileName: string) => void;
    status: 'locked' | 'completed' | 'todo' | 'failed';
    isLoading: boolean;
    loadingStep: 'generating' | 'compacting' | 'imaging' | null;
    isOpen: boolean;
    onToggleOpen: () => void;
}

export const PhaseCard: React.FC<PhaseCardProps> = ({ phase, project, phaseData, images = [], selectedArtifacts = [], attachments, updatePhaseData, isLocked, lockReason, onGenerate, onGenerateImages, onChatToChange, onComplete, onAttachFile, onRemoveAttachment, status, isLoading, loadingStep, isOpen, onToggleOpen }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [editedContent, setEditedContent] = useState(phaseData || '');
    const [chatInput, setChatInput] = useState('');
    const [localSelectedArtifacts, setLocalSelectedArtifacts] = useState<string[]>(selectedArtifacts);
    const descriptionFileInputRef = useRef<HTMLInputElement>(null);
    const attachmentFileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        setEditedContent(phaseData || '');
        if (isLoading) {
            setIsEditing(false);
        }
    }, [phaseData, isLoading]);

    useEffect(() => {
        setLocalSelectedArtifacts(selectedArtifacts);
    }, [selectedArtifacts]);

    const handleToggle = () => {
        if (!isLocked) {
            onToggleOpen();
        }
    };

    const handleSave = () => {
        updatePhaseData(phase.id, editedContent);
        setIsEditing(false);
    };

    const handleChatSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (chatInput.trim()) {
            onChatToChange(phase.id, chatInput);
            setChatInput('');
        }
    };

    const toggleArtifact = (artifact: string) => {
        setLocalSelectedArtifacts(prev => {
            if (prev.includes(artifact)) {
                return prev.filter(a => a !== artifact);
            }
            if (prev.length < 3) {
                return [...prev, artifact];
            }
            return prev;
        });
    };

    const handleGenerateGraphics = () => {
        if (localSelectedArtifacts.length > 0) {
            onGenerateImages(phase.id, localSelectedArtifacts, phaseData || editedContent);
        }
    };

    const handleDescriptionFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file && file.type === 'text/plain') {
            const reader = new FileReader();
            reader.onload = (e) => {
                const text = e.target?.result as string;
                updatePhaseData(phase.id, text);
            };
            reader.readAsText(file);
        }
        if (event.target) event.target.value = '';
    };

    const handleAttachmentFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (e) => {
                const data = e.target?.result as string;
                onAttachFile(phase.id, { name: file.name, data });
            };
            reader.readAsDataURL(file);
        }
        if (event.target) event.target.value = '';
    };

    const statusMap = {
        locked: { label: 'Locked', color: 'var(--secondary-text)', bg: 'rgba(255,255,255,0.02)' },
        completed: { label: 'Approved', color: 'var(--success-color)', bg: 'rgba(0,255,170,0.05)' },
        todo: { label: 'In Progress', color: 'var(--accent-color)', bg: 'rgba(0,242,255,0.05)' },
        failed: { label: 'Failed', color: 'var(--error-color)', bg: 'rgba(255,51,102,0.05)' }
    };

    const currentStatus = statusMap[status];

    return (
        <div className={`phase-card ${isLocked ? 'locked' : ''}`} style={{ 
            marginBottom: '2rem', 
            opacity: isLocked ? 0.6 : 1,
            filter: isLocked ? 'grayscale(0.5)' : 'none'
        }}>
            <div className="glass-card" style={{ 
                padding: 0, 
                borderLeft: `4px solid ${currentStatus.color}`,
                background: isOpen ? 'rgba(15, 15, 31, 0.8)' : 'rgba(15, 15, 31, 0.4)'
            }}>
                <div 
                    className="phase-header" 
                    onClick={handleToggle} 
                    style={{ 
                        padding: '2.5rem', 
                        cursor: isLocked ? 'not-allowed' : 'pointer',
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center'
                    }}
                >
                    <div style={{ flex: 1 }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem', marginBottom: '0.5rem' }}>
                            <span style={{ fontSize: '1rem', fontWeight: 800, color: currentStatus.color, letterSpacing: '2px', textTransform: 'uppercase' }}>
                                Phase {phase.id.replace('phase', '')}
                            </span>
                            <span className={`chip-${status === 'completed' ? 'green' : status === 'todo' ? 'blue' : 'purple'}`} style={{ fontSize: '0.7rem' }}>
                                {currentStatus.label}
                            </span>
                        </div>
                        <h3 style={{ fontSize: '2rem', fontWeight: 700, marginBottom: '0.5rem' }}>{phase.title}</h3>
                        <p style={{ color: 'var(--secondary-text)', fontSize: '1.1rem' }}>{phase.description}</p>
                        {isLocked && lockReason && (
                            <p style={{ color: 'var(--error-color)', fontSize: '0.9rem', marginTop: '1rem', fontWeight: 600 }}>
                                🔒 {lockReason}
                            </p>
                        )}
                    </div>
                    {!isLocked && (
                        <div style={{ transform: isOpen ? 'rotate(180deg)' : 'none', transition: 'transform 0.3s', opacity: 0.5 }}>
                            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg>
                        </div>
                    )}
                </div>

                {isOpen && !isLocked && (
                    <div style={{ padding: '0 2.5rem 2.5rem', borderTop: '1px solid var(--glass-border)', paddingTop: '2.5rem' }}>
                        {isLoading ? (
                            <div style={{ padding: '4rem', textAlign: 'center' }}>
                                <div className="spinner" style={{ margin: '0 auto 2rem' }}></div>
                                <p style={{ fontSize: '1.2rem', color: 'var(--accent-color)', fontWeight: 600 }}>
                                    {loadingStep === 'compacting' ? 'Synthesizing knowledge...' : 
                                     loadingStep === 'imaging' ? 'Visualizing architecture...' :
                                     'Consulting Gemini...'}
                                </p>
                            </div>
                        ) : (
                            <>
                                {isEditing ? (
                                    <textarea 
                                        value={editedContent}
                                        onChange={(e) => setEditedContent(e.target.value)}
                                        style={{ minHeight: '400px', background: 'rgba(0,0,0,0.3)', border: '1px solid var(--accent-color)' }}
                                        placeholder="Documentation editor..."
                                    />
                                ) : phaseData ? (
                                    <div style={{ background: 'rgba(255,255,255,0.01)', padding: '2.5rem', borderRadius: '16px', border: '1px solid var(--glass-border)' }}>
                                        {parseMarkdown(phaseData)}
                                    </div>
                                ) : (
                                    <div style={{ textAlign: 'center', padding: '4rem', background: 'rgba(255,255,255,0.01)', border: '2px dashed var(--glass-border)', borderRadius: '16px' }}>
                                        <p style={{ color: 'var(--secondary-text)', marginBottom: '2rem' }}>No data generated for this phase yet.</p>
                                        <button className="button button-primary" onClick={() => onGenerate(phase.id, '')}>Generate Initial Draft</button>
                                    </div>
                                )}

                                {images.length > 0 && (
                                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '2rem', marginTop: '3rem' }}>
                                        {images.map((img, i) => (
                                            <div key={i} style={{ borderRadius: '16px', overflow: 'hidden', border: '1px solid var(--glass-border)', boxShadow: '0 10px 30px rgba(0,0,0,0.5)' }}>
                                                <img src={img} alt="Artifact" style={{ width: '100%', height: 'auto', display: 'block' }} />
                                            </div>
                                        ))}
                                    </div>
                                )}

                                {phaseData && !isEditing && (
                                    <div style={{ marginTop: '3rem', background: 'rgba(0,242,255,0.03)', padding: '2rem', borderRadius: '16px', border: '1px solid rgba(0,242,255,0.1)' }}>
