                                <div style={{ display: 'flex', gap: '1rem', marginTop: '3rem', flexWrap: 'wrap' }}>
                                    {phaseData && !isEditing && <button className="button" onClick={() => setIsEditing(true)}>Modify Manually</button>}
                                    {isEditing && <button className="button button-primary" onClick={handleSave}>Sync Changes</button>}
                                    {phaseData && <button className="button button-primary" onClick={() => onComplete(phase.id)} disabled={status === 'completed'}>Finalize & Approve</button>}
                                    <button className="button" onClick={() => descriptionFileInputRef.current?.click()}>Upload Assets</button>
                                </div>

                                {phaseData && !isEditing && (
                                    <form onSubmit={handleChatSubmit} style={{ marginTop: '3rem' }}>
