                                            <div key={file.name} style={{ background: 'rgba(255,255,255,0.03)', padding: '1rem 1.5rem', borderRadius: '12px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', border: '1px solid var(--glass-border)' }}>
