import React, { useState, useEffect, useRef } from 'react';
import { User, Notification } from '../types';

interface HeaderProps {
    onNewProject: () => void;
    onHomeClick: () => void;
    disabled: boolean;
    isLandingPage: boolean;
    currentUser: User;
    onLogout: () => void;
    notifications: Notification[];
    onNotificationClick: (notification: Notification) => void;
    onMarkAllRead: () => void;
}

export const Header: React.FC<HeaderProps> = ({ 
    onNewProject, onHomeClick, disabled, isLandingPage, currentUser, onLogout, 
    notifications = [], onNotificationClick, onMarkAllRead 
}) => {
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    const unreadCount = notifications.filter(n => !n.read).length;

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    return (
        <header style={{ height: '70px', padding: '0 5%', background: 'rgba(2, 2, 7, 0.7)', backdropFilter: 'blur(24px)', borderBottom: '1px solid var(--glass-border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', position: 'sticky', top: 0, zIndex: 1000 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', cursor: 'pointer' }} onClick={onHomeClick}>
                <div style={{ width: '32px', height: '32px', background: 'var(--accent-color)', borderRadius: '8px', boxShadow: '0 0 15px var(--accent-color)' }}></div>
                <h1 style={{ fontSize: '1.4rem', fontWeight: 800, letterSpacing: '0.5px' }}>
                    <span className="gradient-text">HMAP</span> Accelerator
                </h1>
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: '2rem' }}>
                {currentUser && (
                    <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem' }}>
                        <div style={{ position: 'relative' }}>
                            <div 
                                className="notification-bell" 
                                style={{ color: 'var(--secondary-text)', cursor: 'pointer', position: 'relative' }} 
                                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                            >
                                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"></path><path d="M13.73 21a2 2 0 0 1-3.46 0"></path></svg>
                                {unreadCount > 0 && <span className="notification-badge" style={{ position: 'absolute', top: '-5px', right: '-5px', background: 'var(--error-color)', color: 'white', borderRadius: '50%', width: '16px', height: '16px', fontSize: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{unreadCount}</span>}
                            </div>

                            {isDropdownOpen && (
                                <div className="glass-card" ref={dropdownRef} style={{ position: 'absolute', top: '40px', right: 0, width: '320px', padding: '1.5rem', zIndex: 1001, boxShadow: '0 10px 30px rgba(0,0,0,0.5)' }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                                        <h4 style={{ fontSize: '1.1rem' }}>Notifications</h4>
                                        {unreadCount > 0 && <button onClick={onMarkAllRead} style={{ background: 'none', border: 'none', color: 'var(--accent-color)', cursor: 'pointer', fontSize: '0.9rem' }}>Clear All</button>}
                                    </div>
                                    <div style={{ maxHeight: '300px', overflowY: 'auto' }}>
                                        {notifications.length > 0 ? (
                                            notifications.map(notif => (
                                                <div key={notif.id} style={{ padding: '1rem 0', borderBottom: '1px solid rgba(255,255,255,0.05)', cursor: 'pointer', opacity: notif.read ? 0.6 : 1 }} onClick={() => onNotificationClick(notif)}>
                                                    <p style={{ fontSize: '0.95rem', marginBottom: '0.3rem' }}>{notif.text}</p>
                                                    <small style={{ color: 'var(--secondary-text)' }}>{new Date(notif.timestamp).toLocaleTimeString()}</small>
                                                </div>
                                            ))
                                        ) : (
                                            <p style={{ textAlign: 'center', padding: '2rem', color: 'var(--secondary-text)' }}>No activity yet</p>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>

                        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', padding: '0.5rem 1rem', background: 'rgba(255,255,255,0.03)', borderRadius: '100px', border: '1px solid var(--glass-border)' }}>
                            <span style={{ fontWeight: 600, fontSize: '1rem' }}>{currentUser.username}</span>
                            <div style={{ width: '1px', height: '15px', background: 'rgba(255,255,255,0.1)' }}></div>
                            <button onClick={onLogout} style={{ background: 'none', border: 'none', color: 'var(--secondary-text)', cursor: 'pointer', fontWeight: 600 }}>Exit</button>
                        </div>
                    </div>
                )}

                <button onClick={onNewProject} className="button button-primary" style={{ height: '44px', borderRadius: '100px' }} disabled={disabled}>
                    {isLandingPage ? 'Launch Project' : '+ New Build'}
                </button>
            </div>
        </header>
    );
};

