import React, { useState } from 'react';
import * as authService from '../utils/authService';
import { User } from '../types';
import { RainbowText } from '../components/RainbowText';

interface AuthViewProps {
    onLogin: (user: User) => void;
}

export const AuthView: React.FC<AuthViewProps> = ({ onLogin }) => {
    const [isLoginView, setIsLoginView] = useState(true);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [username, setUsername] = useState('');
    const [isLdap, setIsLdap] = useState(false);
    const [error, setError] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        try {
            if (isLoginView) {
                const user = authService.login(email, password);
                if (user) {
                    onLogin({ ...user, isLdap });
                } else {
                    setError('Invalid credentials.');
                }
            } else {
                const newUser = authService.register(username, email, password);
                if (newUser) {
                    const user = authService.login(email, password);
                    if (user) onLogin(user);
                } else {
                    setError('Registration failed.');
                }
            }
        } catch (err: any) {
            setError(err.message);
        }
    };

    return (
        <div style={{ display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', minHeight: '100vh', padding: '2rem', position: 'relative' }}>
            <div style={{ marginBottom: '3rem', textAlign: 'center' }}>
                <h1 style={{ fontSize: '3rem', fontWeight: 800, marginBottom: '0.5rem' }}>
                    <span className="gradient-text">MIFECO</span> OS
                </h1>
                <p style={{ color: 'var(--secondary-text)', letterSpacing: '2px', textTransform: 'uppercase', fontSize: '0.9rem' }}>Project Acceleration Layer</p>
            </div>

            <div className="glass-card" style={{ maxWidth: '420px', width: '100%', padding: '4rem' }}>
                <h2 style={{ fontSize: '2.4rem', fontWeight: 700, marginBottom: '3rem', textAlign: 'center' }}>{isLoginView ? 'Authenticate' : 'Initialize Account'}</h2>

                <form onSubmit={handleSubmit}>
                    {error && <p className="status-message error" style={{ marginBottom: '2rem' }}>{error}</p>}

                    {!isLoginView && (
                        <div className="form-group" style={{ marginBottom: '2rem' }}>
                            <label style={{ fontSize: '0.9rem', color: 'var(--secondary-text)', textTransform: 'uppercase', marginBottom: '1rem', display: 'block' }}>Codename</label>
                            <input type="text" value={username} onChange={e => setUsername(e.target.value)} required placeholder="A. Skywalker" />
                        </div>
                    )}

                    <div className="form-group" style={{ marginBottom: '2rem' }}>
                        <label style={{ fontSize: '0.9rem', color: 'var(--secondary-text)', textTransform: 'uppercase', marginBottom: '1rem', display: 'block' }}>Email Interface</label>
                        <input type="text" value={email} onChange={e => setEmail(e.target.value)} required placeholder="user@mars.institute" />
                    </div>

                    <div className="form-group" style={{ marginBottom: '2rem' }}>
                        <label style={{ fontSize: '0.9rem', color: 'var(--secondary-text)', textTransform: 'uppercase', marginBottom: '1rem', display: 'block' }}>Access Key</label>
                        <input type="password" value={password} onChange={e => setPassword(e.target.value)} required placeholder="••••••••" />
                    </div>

                    {isLoginView && (
                        <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '3rem' }}>
                            <input type="checkbox" id="ldap-toggle" checked={isLdap} onChange={e => setIsLdap(e.target.checked)} style={{ width: '18px', height: '18px' }} />
                            <label htmlFor="ldap-toggle" style={{ margin: 0, color: 'var(--secondary-text)', cursor: 'pointer' }}>Enterprise LDAP Sync</label>
                        </div>
                    )}

                    <button type="submit" className="button button-primary" style={{ width: '100%', padding: '1.6rem', fontSize: '1.2rem', borderRadius: '100px' }}>
                        {isLoginView ? 'Connect' : 'Generate Identity'}
                    </button>

                    <div style={{ marginTop: '3rem', textAlign: 'center' }}>
