            </div>

            <p style={{ marginTop: '4rem', color: 'rgba(255,255,255,0.2)', fontSize: '0.8rem', letterSpacing: '1px' }}>SECURE ENCRYPTION ENABLED // MARS TECHNOLOGY INSTITUTE</p>
        </div>
    );
};

import React, { useMemo } from 'react';
import { Project, User, Task } from '../types';

interface MyWorkViewProps {
    projects: Project[];
    currentUser: User;
    onSelectTask: (project: Project, task: Task) => void;
}

interface AssignedTask extends Task {
    projectName: string;
    projectId: string;
}

export const MyWorkView: React.FC<MyWorkViewProps> = ({ projects, currentUser, onSelectTask }) => {
    const myTasks = useMemo<AssignedTask[]>(() => {
        if (!projects || !currentUser) return [];

        const allAssignedTasks: AssignedTask[] = [];

        projects.forEach(project => {
            const userInProject = project.team?.find(member => member.userId === currentUser.id);
            if (userInProject) {
                const userRoles = project.team
                    .filter(member => member.userId === currentUser.id)
                    .map(member => member.role);

                if (userRoles.length > 0) {
                    const tasksForUser = project.tasks?.filter(task => 
                        task.status !== 'done' && task.role && userRoles.includes(task.role)
                    );

                    if (tasksForUser) {
                        tasksForUser.forEach(task => {
                            allAssignedTasks.push({
                                ...task,
                                projectName: project.name,
                                projectId: project.id,
                            });
                        });
                    }
                }
            }
        });

        return allAssignedTasks.sort((a, b) => new Date(a.endDate).getTime() - new Date(b.endDate).getTime());
    }, [projects, currentUser]);

    const handleTaskClick = (task: AssignedTask) => {
        const project = projects.find(p => p.id === task.projectId);
        if (project) {
            onSelectTask(project, task);
        }
    };

    if (myTasks.length === 0) {
        return (
            <div className="glass-card" style={{ textAlign: 'center', padding: '4rem' }}>
                <div style={{ fontSize: '3rem', marginBottom: '1.5rem', opacity: 0.3 }}>🛸</div>
                <h3>Your workspace is clear.</h3>
                <p style={{ color: 'var(--secondary-text)' }}>No pending tasks assigned to your roles across active projects.</p>
            </div>
        );
    }

    return (
        <section className="glass-card">
            <h2 className="subsection-title" style={{ display: 'flex', alignItems: 'center', gap: '1.5rem' }}>
                Operational Queue
                <span className="chip-blue" style={{ fontSize: '1rem', padding: '0.4rem 1rem' }}>{myTasks.length} Pending</span>
            </h2>
            <div style={{ marginTop: '2rem' }}>
                <table>
                    <thead>
                        <tr>
                            <th>Protocol / Task</th>
                            <th>Parent Mission</th>
                            <th>Status</th>
                            <th>Target Date</th>
                        </tr>
                    </thead>
                    <tbody>
                        {myTasks.map(task => {
                             const isOverdue = new Date(task.endDate) < new Date();
                             return (
                                <tr key={task.id} onClick={() => handleTaskClick(task)} style={{ cursor: 'pointer' }}>
                                    <td style={{ fontWeight: 700, color: isOverdue ? 'var(--error-color)' : 'var(--primary-text)' }}>
                                        {isOverdue && <span style={{ marginRight: '1rem' }}>⚠️</span>}
                                        {task.name}
                                    </td>
                                    <td><span style={{ color: 'var(--accent-color)', fontWeight: 600 }}>{task.projectName}</span></td>
                                    <td><span className={`chip-${task.status === 'inprogress' ? 'blue' : 'amber'}`}>{task.status}</span></td>
                                    <td style={{ fontFamily: 'monospace', color: isOverdue ? 'var(--error-color)' : 'var(--secondary-text)' }}>{task.endDate}</td>
                                </tr>
                             );
                        })}
                    </tbody>
                </table>
            </div>
        </section>
    );
};

