import React, { useState, useEffect, useRef } from 'react';
import { Type } from "@google/genai";
import { TEMPLATES, PROMPTS } from '../constants/projectData';
import { Project } from '../types';

export const NewProjectModal = ({ isOpen, onClose, onCreateProject, projects, onSelectProject, onRequestDelete, ai, currentUser }) => {
  const [name, setName] = useState('');
  const [selectedTemplateId, setSelectedTemplateId] = useState(null);
  const [projectMode, setProjectMode] = useState('fullscale');
  const [projectScope, setProjectScope] = useState('internal');
  const [teamSize, setTeamSize] = useState('medium');
  const [projectComplexity, setProjectComplexity] = useState('typical');
  const [activeTab, setActiveTab] = useState('create');
  const [creationMode, setCreationMode] = useState('template');
  const [customDiscipline, setCustomDiscipline] = useState('');
  const [isGeneratingDocs, setIsGeneratingDocs] = useState(false);
  const [error, setError] = useState('');
  const modalRef = useRef(null);

  const userProjects: Project[] = projects;

  useEffect(() => {
    if (isOpen) {
        modalRef.current?.focus();
        setActiveTab(userProjects && userProjects.length > 0 ? 'select' : 'create');
    }
  }, [isOpen, userProjects]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!name.trim()) { setError("Please enter a project name."); return; }

    let template;
    if (creationMode === 'template') {
        template = TEMPLATES.find(t => t.id === selectedTemplateId);
        if (!template) { setError("Please select a template."); return; }
        onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
    } else {
        if (!customDiscipline.trim()) { setError("Please enter a custom project type."); return; }
        setIsGeneratingDocs(true);
        try {
            const prompt = PROMPTS.generateDocumentList(customDiscipline.trim(), projectScope, teamSize, projectComplexity);
            const schema = {
                type: Type.OBJECT, properties: { documents: {
                        type: Type.ARRAY, items: { type: Type.OBJECT, properties: {
                                title: { type: Type.STRING },
                                phase: { type: Type.NUMBER },
                                sequence: { type: Type.NUMBER }
                            }, required: ['title', 'phase', 'sequence']
                        }
                    }
                }, required: ['documents']
            };
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview', contents: prompt, config: { responseMimeType: "application/json", responseSchema: schema },
            });
            const rawDocs = JSON.parse(response.text).documents;
            const generatedDocs = rawDocs.map((doc, i) => ({
                id: `doc-custom-${i}-${Date.now()}`, title: doc.title, version: 'v1.0', status: 'Working', owner: currentUser.username, phase: doc.phase, sequence: doc.sequence,
            }));
            template = { id: 'custom', name: 'Custom Project', discipline: customDiscipline.trim(), documents: generatedDocs };
            onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
        } catch (error) {
            setError("Failed to generate project structure.");
        } finally {
            setIsGeneratingDocs(false);
        }
    }
  };

  if (!isOpen) return null;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" style={{maxWidth: '900px'}} onClick={(e) => e.stopPropagation()} ref={modalRef} tabIndex={-1}>
        <div className="dashboard-nav" style={{marginBottom: '3rem', width: '100%', justifyContent: 'center'}}>
            <button onClick={() => setActiveTab('select')} className={activeTab === 'select' ? 'active' : ''}>Active Missions</button>
            <button onClick={() => setActiveTab('create')} className={activeTab === 'create' ? 'active' : ''}>New Construction</button>
        </div>

        {activeTab === 'select' && (
            <div className="project-list-section">
                {userProjects.length > 0 ? (
                    <ul style={{listStyle: 'none'}}>
                        {userProjects.map(p => (
                            <li key={p.id} style={{display: 'flex', justifyContent: 'space-between', padding: '2.5rem', background: 'rgba(255,255,255,0.02)', border: '1px solid var(--glass-border)', borderRadius: '16px', marginBottom: '1.5rem', alignItems: 'center'}}>
                                <div>
                                    <h4 style={{fontSize: '1.8rem', fontWeight: 700, marginBottom: '0.4rem'}}>{p.name}</h4>
                                    <span style={{color: 'var(--secondary-text)', fontSize: '1.1rem'}}>{p.discipline}</span>
                                </div>
                                <div style={{display: 'flex', gap: '1rem'}}>
                                    <button onClick={() => onSelectProject(p)} className="button button-primary">Open</button>
                                    <button onClick={() => onRequestDelete(p)} className="button" style={{color: 'var(--error-color)', borderColor: 'rgba(255,51,102,0.3)'}}>Discard</button>
                                </div>
                            </li>
                        ))}
                    </ul>
                ) : <p style={{textAlign: 'center', padding: '4rem', color: 'var(--secondary-text)'}}>No active missions in your sector.</p>}
            </div>
        )}

        {activeTab === 'create' && (
          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '3rem' }}>
