    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Task, Project, User, Comment, Attachment } from '../types';

interface TaskDetailModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSave: (updatedTask: Task) => void;
    task: Task;
    project: Project;
    currentUser: User;
}

const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = error => reject(error);
    });
};

export const TaskDetailModal: React.FC<TaskDetailModalProps> = ({ isOpen, onClose, onSave, task, project, currentUser }) => {
    const [currentTask, setCurrentTask] = useState<Task>(task);
    const [newComment, setNewComment] = useState('');
    const attachmentInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        setCurrentTask(task);
    }, [task]);

    if (!isOpen) return null;

    const handleFieldChange = (field: keyof Task, value: any) => {
        setCurrentTask(prev => ({ ...prev, [field]: value }));
    };

    const handleAddComment = () => {
        if (newComment.trim()) {
            const comment: Comment = {
                id: `comment-${Date.now()}`,
                authorId: currentUser.id,
                authorName: currentUser.username,
                timestamp: new Date().toISOString(),
                text: newComment,
            };
            handleFieldChange('comments', [...(currentTask.comments || []), comment]);
            setNewComment('');
        }
    };

    const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file) {
            try {
                const fileData = await fileToBase64(file);
                const attachment: Attachment = {
                    id: `attachment-${Date.now()}`,
                    uploaderId: currentUser.id,
                    uploaderName: currentUser.username,
                    timestamp: new Date().toISOString(),
                    fileName: file.name,
                    fileData,
                    fileType: file.type,
                };
                handleFieldChange('attachments', [...(currentTask.attachments || []), attachment]);
            } catch (err) {
                alert("Failed to attach.");
            }
        }
    };

    return (
        <div className="modal-overlay" onClick={() => { onSave(currentTask); onClose(); }}>
            <div className="modal-content" style={{ maxWidth: '1000px', width: '90%', padding: 0, overflow: 'hidden' }} onClick={e => e.stopPropagation()}>
                <div style={{ padding: '3rem', borderBottom: '1px solid var(--glass-border)', background: 'rgba(0,242,255,0.03)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div>
                        <span style={{ color: 'var(--accent-color)', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '2px', fontSize: '0.9rem' }}>Protocol Assignment</span>
                        <h2 style={{ fontSize: '2.8rem', fontWeight: 800, marginTop: '0.5rem' }}>{currentTask.name}</h2>
                    </div>
                    <button onClick={() => { onSave(currentTask); onClose(); }} style={{ background: 'none', border: 'none', color: 'var(--primary-text)', fontSize: '3rem', cursor: 'pointer', opacity: 0.5 }}>&times;</button>
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: '1.8fr 1fr', height: '600px' }}>
                    <div style={{ padding: '3rem', overflowY: 'auto', borderRight: '1px solid var(--glass-border)' }}>
                        <div className="form-group" style={{ marginBottom: '3rem' }}>
                            <label style={{ color: 'var(--secondary-text)', textTransform: 'uppercase', fontSize: '0.9rem', fontWeight: 700, marginBottom: '1.5rem', display: 'block' }}>Operational Briefing</label>
                            <textarea 
                                value={currentTask.description || ''} 
                                onChange={e => handleFieldChange('description', e.target.value)} 
                                rows={6} 
                                placeholder="Define task boundaries and requirements..."
                                style={{ background: 'rgba(0,0,0,0.2)', fontSize: '1.3rem' }}
                            />
                        </div>

                        <div className="comments-section">
                            <h3 style={{ fontSize: '1.4rem', fontWeight: 700, marginBottom: '2rem' }}>Communication Log</h3>
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginBottom: '2.5rem' }}>
                                {(currentTask.comments || []).map(comment => (
                                    <div key={comment.id} style={{ background: 'rgba(255,255,255,0.03)', padding: '1.5rem', borderRadius: '16px', border: '1px solid var(--glass-border)' }}>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.8rem' }}>
                                            <span style={{ fontWeight: 700, color: 'var(--accent-color)' }}>{comment.authorName}</span>
                                            <span style={{ fontSize: '0.85rem', color: 'var(--secondary-text)' }}>{new Date(comment.timestamp).toLocaleTimeString()}</span>
