import React, { useState, useMemo, useEffect } from 'react';
import { Type, GoogleGenAI } from "@google/genai";
import { logAction } from '../utils/logging';
import { PROMPTS } from '../constants/projectData';
import { ChangeDeploymentModal } from '../components/ChangeDeploymentModal';
import { parseImpact, applyImpact } from '../utils/be-logic';

const MAX_PAYLOAD_CHARS = 20000;

const truncatePrompt = (prompt: string): string => {
    if (prompt.length <= MAX_PAYLOAD_CHARS) return prompt;
    return prompt.substring(0, MAX_PAYLOAD_CHARS) + "\n...[PROMPT TRUNCATED]...";
};

export const RevisionControlView = ({ project, onUpdateProject, ai }: {project: any, onUpdateProject: (update: any) => void, ai: GoogleGenAI}) => {
    const { changeRequest: cr, scenarios, name, discipline, tasks, documents, budget, endDate } = project;
    const [newScenario, setNewScenario] = useState({ name: '', impactStr: '' });
    const [deploymentPlan, setDeploymentPlan] = useState('');
    const [isGeneratingPlan, setIsGeneratingPlan] = useState(false);
    const [isDeploying, setIsDeploying] = useState(false);
    const [isEstimating, setIsEstimating] = useState(false);
    const [error, setError] = useState('');

    const handleCrChange = (newCrData) => {
        onUpdateProject({ changeRequest: newCrData });
    };

    const handleScenariosChange = (newScenarios) => {
        onUpdateProject({ scenarios: newScenarios });
    };

    const handleAddScenario = (e) => {
        e.preventDefault();
        if (newScenario.name && newScenario.impactStr) {
            const updatedScenarios = [...scenarios, { id: Date.now(), ...newScenario }];
            handleScenariosChange(updatedScenarios);
            setNewScenario({ name: '', impactStr: '' });
        }
    };

    const handleEstimateImpact = async () => {
        if (!cr.title || !cr.reason) return;
        setIsEstimating(true);
        setError('');
        try {
            const prompt = PROMPTS.estimateChangeImpact(name, discipline, budget, cr);
            const schema = {
                type: Type.OBJECT,
                properties: {
                    days: { type: Type.NUMBER },
                    cost: { type: Type.NUMBER }
                },
                required: ['days', 'cost']
            };
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview', contents: prompt, config: { responseMimeType: "application/json", responseSchema: schema },
            });
            const impact = JSON.parse(response.text);
            const newImpactStr = `${impact.days >= 0 ? '+' : ''}${impact.days}d ${impact.cost >= 0 ? '+' : ''}${impact.cost}c`;
            handleCrChange({ ...cr, impactStr: newImpactStr });
        } catch (err) {
            setError("Analysis failed.");
        } finally {
            setIsEstimating(false);
        }
    };

    const handleGeneratePlan = async () => {
        if (!cr.title || !cr.reason) return;
        setIsGeneratingPlan(true);
        setError('');
        try {
            const promptText = PROMPTS.changeDeploymentPlan(name, discipline, cr, tasks, documents);
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: truncatePrompt(promptText),
            });
            setDeploymentPlan(response.text);
        } catch (err) {
            setError("Deployment planning failed.");
        } finally {
            setIsGeneratingPlan(false);
        }
    };

    const baseline = useMemo(() => ({ budget, endDate }), [budget, endDate]);
    const crImpact = useMemo(() => parseImpact(cr.impactStr), [cr.impactStr]);
    const crResult = useMemo(() => applyImpact(baseline, crImpact), [baseline, crImpact]);
    const scenarioResults = useMemo(() => scenarios.map(s => ({
        ...s,
        impact: parseImpact(s.impactStr),
        result: applyImpact(baseline, parseImpact(s.impactStr))
    })), [scenarios, baseline]);

    const currencyFormat = (num) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(num);

    const ImpactCell = ({ value, base }) => {
        const diff = value - base;
        const color = diff > 0 ? 'var(--error-color)' : diff < 0 ? 'var(--success-color)' : 'inherit';
        return <span style={{ color, fontWeight: 700 }}>{currencyFormat(value)} {diff !== 0 && `(${diff > 0 ? '+' : ''}${currencyFormat(diff)})`}</span>
    };

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '3rem' }}>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '3rem' }}>
                <div className="tool-card">
                    <h3 className="subsection-title" style={{ fontSize: '1.6rem' }}>Mission Variation Request</h3>
                    <form style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
                        <div className="form-group">
                            <label style={{ fontSize: '0.9rem', color: 'var(--secondary-text)' }}>DESIGNATION</label>
                            <input type="text" value={cr.title} onChange={e => handleCrChange({...cr, title: e.target.value})} placeholder="Variation Name" />
                        </div>
                        <div className="form-group">
                            <label style={{ fontSize: '0.9rem', color: 'var(--secondary-text)' }}>RATIONALE</label>
                            <textarea rows={3} value={cr.reason} onChange={e => handleCrChange({...cr, reason: e.target.value})} placeholder="Detailed reason for shift..." />
                        </div>
                        <div className="form-group">
                            <label style={{ fontSize: '0.9rem', color: 'var(--secondary-text)' }}>PROJECTED IMPACT (+15d +5000c)</label>
                            <div style={{display: 'flex', gap: '1rem'}}>
                                <input type="text" value={cr.impactStr} onChange={e => handleCrChange({...cr, impactStr: e.target.value})} style={{flexGrow: 1}} />
                                <button type="button" className="button" onClick={handleEstimateImpact} disabled={isEstimating || !ai}>
                                    {isEstimating ? <div className="spinner" style={{width: '16px', height: '16px'}}></div> : 'Analyze'}
                                </button>
                            </div>
                        </div>
                    </form>

                    <h3 className="subsection-title" style={{ fontSize: '1.6rem', marginTop: '4rem' }}>Predictive Scenarios</h3>
                    <form onSubmit={handleAddScenario} style={{display: 'flex', gap: '1rem'}}>
                         <input type="text" placeholder="Alias" value={newScenario.name} onChange={e => setNewScenario({...newScenario, name: e.target.value})} style={{flex: 1}}/>
                         <input type="text" placeholder="+5d -1k" value={newScenario.impactStr} onChange={e => setNewScenario({...newScenario, impactStr: e.target.value})} style={{flex: 1}}/>
                         <button type="submit" className="button button-primary">Inject</button>
                    </form>
                </div>

                <div className="tool-card">
                    <h3 className="subsection-title" style={{ fontSize: '1.6rem' }}>Strategic Impact Projection</h3>
                    <table style={{ background: 'rgba(0,0,0,0.2)', borderRadius: '16px', border: '1px solid var(--glass-border)' }}>
                        <thead>
                            <tr>
                                <th>METRIC</th>
                                <th>BASELINE</th>
                                <th style={{ color: 'var(--accent-color)' }}>CURRENT CR</th>
                                {scenarioResults.map(s => <th key={s.id}>{s.name}</th>)}
                            </tr>
                        </thead>
                        <tbody>
                            <tr>
                                <td style={{ fontWeight: 700 }}>TIMELINE END</td>
                                <td>{baseline.endDate}</td>
                                <td><span style={{ color: crImpact.days > 0 ? 'var(--error-color)' : 'var(--success-color)', fontWeight: 700 }}>{crResult.endDate} {crImpact.days !== 0 && `(${crImpact.days > 0 ? '+':''}${crImpact.days}d)`}</span></td>
                                {scenarioResults.map(s => <td key={s.id}>{s.result.endDate}</td>)}
                            </tr>
                             <tr>
                                <td style={{ fontWeight: 700 }}>CREDIT BURDEN</td>
                                <td>{currencyFormat(baseline.budget)}</td>
                                <td><ImpactCell value={crResult.budget} base={baseline.budget} /></td>
                                {scenarioResults.map(s => <td key={s.id}><ImpactCell value={s.result.budget} base={baseline.budget} /></td>)}
                            </tr>
                        </tbody>
                    </table>
                     <div style={{marginTop: '3rem', display: 'flex', justifyContent: 'flex-end', gap: '1.5rem'}}>
                        <button className="button" style={{ borderRadius: '100px' }}>Save to Vault</button>
                        <button className="button button-primary" style={{ borderRadius: '100px', padding: '1.2rem 3rem' }}>Submit for Authorization</button>
                    </div>
                </div>
            </div>

            <div className="tool-card" style={{ background: 'rgba(0, 242, 255, 0.02)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2.5rem' }}>
                    <h3 className="subsection-title" style={{ margin: 0 }}>Deployment Synthesis</h3>
                    <button className="button button-primary" onClick={handleGeneratePlan} disabled={isGeneratingPlan || !ai} style={{ borderRadius: '100px' }}>
                        {isGeneratingPlan ? <div className="spinner" style={{width: '20px', height: '20px'}}></div> : (deploymentPlan ? 'Re-Synthesize Protocol' : 'Generate Deployment Plan')}
                    </button>
                </div>

                <textarea 
                    rows={10}
                    value={deploymentPlan}
                    onChange={(e) => setDeploymentPlan(e.target.value)}
                    placeholder="AI-orchestrated deployment strategy will appear here..."
                    style={{ background: 'rgba(0,0,0,0.4)', borderRadius: '16px', padding: '2rem', fontSize: '1.2rem', fontFamily: 'monospace' }}
                />

                {deploymentPlan && (
                    <div style={{ marginTop: '2.5rem', textAlign: 'right' }}>
                        <button className="button button-primary" onClick={() => setIsDeploying(true)} style={{ padding: '1.5rem 4rem', borderRadius: '100px' }}>Execute Deployment Sequence</button>
                    </div>
                )}
            </div>

            <ChangeDeploymentModal
                isOpen={isDeploying}
                onClose={() => setIsDeploying(false)}
                deploymentPlan={deploymentPlan}
                project={project}
                onUpdateProject={onUpdateProject}
            />
        </div>
    );
};

