export const logAction = (action: string, element: string, details: any = {}) => {
  try {
    const logEntry = {
      timestamp: new Date().toISOString(),
      action,
      element,
      // Deep copy state to log its value at this point in time
      state: JSON.parse(JSON.stringify(details)),
    };
    console.log('HMAP_LOG:', logEntry);
  } catch (error) {
    console.error('Error during logging:', error, { action, element, details });
  }
};

import React, { useState } from 'react';
import * as authService from '../utils/authService.ts';
import { User } from '../types.ts';

interface AuthViewProps {
    onLogin: (user: User) => void;
}

export const AuthView: React.FC<AuthViewProps> = ({ onLogin }) => {
    const [isLoginView, setIsLoginView] = useState(true);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [username, setUsername] = useState('');
    const [isLdap, setIsLdap] = useState(false);
    const [error, setError] = useState('');

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        try {
            if (isLoginView) {
                const user = authService.login(email, password);
                if (user) {
                    onLogin({ ...user, isLdap });
                } else {
                    setError('ACCESS DENIED: Credentials unrecognized.');
                }
            } else {
                const newUser = authService.register(username, email, password);
                if (newUser) {
                    const user = authService.login(email, password);
                    if (user) onLogin(user);
                } else {
                    setError('INIT_FAILED: Registration protocol rejected.');
                }
            }
        } catch (err: any) {
            setError(`SYSTEM_ERR: ${err.message}`);
        }
    };

    return (
        <div style={{ display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', minHeight: '100vh', padding: '2rem', position: 'relative' }}>
            <div style={{ marginBottom: '4rem', textAlign: 'center' }}>
                <h1 style={{ fontSize: '4rem', fontWeight: 800, letterSpacing: '-2px', marginBottom: '0.5rem' }}>
                    <span className="gradient-text">MIFECO</span> OS
                </h1>
                <p style={{ color: 'var(--secondary-text)', letterSpacing: '3px', textTransform: 'uppercase', fontSize: '1rem', opacity: 0.7 }}>Secure Project Acceleration Hub</p>
            </div>

            <div className="glass-card" style={{ maxWidth: '450px', width: '100%', padding: '4rem', borderLeft: 'none' }}>
                <h2 style={{ fontSize: '2.4rem', fontWeight: 700, marginBottom: '4rem', textAlign: 'center' }}>{isLoginView ? 'System Authentication' : 'Neural Identity Setup'}</h2>

                <form onSubmit={handleSubmit}>
                    {error && <p className="status-message error" style={{ marginBottom: '3rem', padding: '1.5rem', fontSize: '1.1rem' }}>{error}</p>}

                    {!isLoginView && (
                        <div style={{ marginBottom: '2.5rem' }}>
                            <label style={{ fontSize: '0.9rem', color: 'var(--secondary-text)', textTransform: 'uppercase', marginBottom: '1rem', display: 'block', fontWeight: 700 }}>Codename</label>
                            <input type="text" value={username} onChange={e => setUsername(e.target.value)} required placeholder="A. Skywalker" />
                        </div>
                    )}

                    <div style={{ marginBottom: '2.5rem' }}>
                        <label style={{ fontSize: '0.9rem', color: 'var(--secondary-text)', textTransform: 'uppercase', marginBottom: '1rem', display: 'block', fontWeight: 700 }}>Interface ID (Email)</label>
                        <input type="text" value={email} onChange={e => setEmail(e.target.value)} required placeholder="user@mars.institute" />
                    </div>

                    <div style={{ marginBottom: '2.5rem' }}>
                        <label style={{ fontSize: '0.9rem', color: 'var(--secondary-text)', textTransform: 'uppercase', marginBottom: '1rem', display: 'block', fontWeight: 700 }}>Access Key</label>
                        <input type="password" value={password} onChange={e => setPassword(e.target.value)} required placeholder="••••••••" />
                    </div>

                    {isLoginView && (
                        <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem', marginBottom: '4rem' }}>
                            <input type="checkbox" id="ldap-toggle" checked={isLdap} onChange={e => setIsLdap(e.target.checked)} style={{ width: '20px', height: '20px', cursor: 'pointer' }} />
                            <label htmlFor="ldap-toggle" style={{ margin: 0, color: 'var(--secondary-text)', cursor: 'pointer', fontSize: '1.1rem' }}>Enterprise LDAP Uplink</label>
                        </div>
                    )}

                    <button type="submit" className="button button-primary" style={{ width: '100%', padding: '1.8rem', fontSize: '1.3rem' }}>
                        {isLoginView ? 'Initialize Access' : 'Confirm Identity'}
                    </button>

                    <div style={{ marginTop: '3.5rem', textAlign: 'center' }}>
                        <button type="button" onClick={() => setIsLoginView(!isLoginView)} style={{ background: 'none', border: 'none', color: 'var(--accent-color)', cursor: 'pointer', fontWeight: 600, fontSize: '1.1rem' }}>
                            {isLoginView ? 'Request access credentials?' : 'Return to authentication interface'}
                        </button>
                    </div>
                </form>
            </div>

            <p style={{ marginTop: '5rem', color: 'rgba(255,255,255,0.2)', fontSize: '0.9rem', letterSpacing: '2px', fontWeight: 500 }}>V.2.5.0-STABLE // ENCRYPTED CONNECTION</p>
        </div>
    );
};

