                    <div>
                        <div style={{ fontSize: '1.8rem', fontWeight: 700 }}>{metrics.totalTasks}</div>
                        <div style={{ fontSize: '0.8rem', color: 'var(--secondary-text)', textTransform: 'uppercase' }}>Total Tasks</div>
