import React, { useState } from 'react';
import { PhaseCard } from '../components/PhaseCard.tsx';

export const ProjectPhasesView = ({ project, projectPhases, phasesData, documents, error, loadingPhase, handleUpdatePhaseData, handleCompletePhase, handleGenerateContent, handleGenerateImages, handleChatToChange, handleAttachFile, handleRemoveAttachment, generationMode, onSetGenerationMode, isAutoGenerating }) => {
    const [openPhases, setOpenPhases] = useState(() => {
        try {
            const firstTodoDoc = documents.find(d => d.status !== 'Approved');
            const defaultOpen = firstTodoDoc ? [firstTodoDoc.id] : (projectPhases.length > 0 ? [projectPhases[0].id] : []);
            const saved = localStorage.getItem(`hmap-open-phases-${project.id}`);
            return saved ? JSON.parse(saved) : defaultOpen;
        } catch (e) {
            return [];
        }
    });

    const togglePhaseOpen = (docId) => {
        const newOpenPhases = openPhases.includes(docId)
            ? openPhases.filter(id => id !== docId)
            : [...openPhases, docId];
        setOpenPhases(newOpenPhases);
        localStorage.setItem(`hmap-open-phases-${project.id}`, JSON.stringify(newOpenPhases));
    };

    const getLockStatus = (docId) => {
        const docIndex = projectPhases.findIndex(p => p.id === docId);
        if (docIndex <= 0) return { isLocked: false, lockReason: null };

        const prevDocInSequence = projectPhases[docIndex - 1];
        const prevDocData = documents.find(d => d.id === prevDocInSequence.id);
        const prevDocContent = phasesData[prevDocInSequence.id]?.content;

        // Unlocks if the previous document HAS content, even if not yet approved
        const isPrevDocSubstantiallyReady = prevDocData?.status === 'Approved' || (prevDocContent && prevDocContent.trim().length > 100);

        if (!isPrevDocSubstantiallyReady) {
            return { isLocked: true, lockReason: `Requires content generation for "${prevDocData.title}".` };
        }
        return { isLocked: false, lockReason: null };
    };

    const isPhase1Complete = documents.filter(d => d.phase === 1).every(d => d.status === 'Approved');

    return (
        <div>
            {error && <div className="status-message error" style={{marginBottom: '2rem'}}>{error}</div>}

            <p style={{ color: 'var(--neon-yellow)', fontSize: '0.9rem', marginBottom: '2rem', opacity: 0.9, lineHeight: '1.4' }}>
                Each document needs to be generated (written by Ai) and then as the planner you need to review and edit. 
                you can do this by manual edits or by telling the chat what you want to change. 
                When satisfied mark the document as complete to unlock the next document
            </p>

            {isPhase1Complete && (
                <div className="tool-card" style={{ marginBottom: '3rem' }}>
                    <h3 className="subsection-title">Generation Strategy</h3>
                    <div className="selection-group">
                        <button 
                            type="button" 
                            onClick={() => onSetGenerationMode('manual')} 
                            className={`selection-button ${generationMode === 'manual' ? 'active' : ''}`}
                            disabled={isAutoGenerating}
                        >
                            <strong>HMAP Process</strong>
                            <span>Manual control & review</span>
                        </button>
                        <button 
                            type="button" 
                            onClick={() => onSetGenerationMode('automatic')} 
                            className={`selection-button ${generationMode === 'automatic' ? 'active' : ''}`}
                            disabled={isAutoGenerating}
                        >
                            <strong>Auto Pilot</strong>
                            <span>Sequence all documents</span>
                        </button>
                    </div>
                    {isAutoGenerating && <p style={{color: 'var(--accent-color)', textAlign: 'center', marginTop: '1.5rem'}}>AI is processing documents...</p>}
                </div>
            )}

            {projectPhases.map((phase) => {
                const doc = documents.find(d => d.id === phase.id);
                if (!doc) return null;
                const { isLocked, lockReason } = getLockStatus(phase.id);
                const status = isLocked ? 'locked' : doc?.status === 'Approved' ? 'completed' : 'todo';
                const pData = phasesData[phase.id];
                return (
                    <div key={phase.id}>
                        <PhaseCard
                            phase={phase}
                            project={project}
                            phaseData={pData?.content}
                            images={pData?.images || []}
                            selectedArtifacts={pData?.selectedArtifacts || []}
                            attachments={pData?.attachments || []}
                            updatePhaseData={handleUpdatePhaseData}
                            isLocked={isLocked}
                            lockReason={lockReason}
                            onGenerate={handleGenerateContent}
                            onGenerateImages={handleGenerateImages}
                            onChatToChange={handleChatToChange}
                            onComplete={handleCompletePhase}
                            onAttachFile={handleAttachFile}
                            onRemoveAttachment={handleRemoveAttachment}
                            status={status}
                            isLoading={loadingPhase?.docId === phase.id}
                            loadingStep={loadingPhase?.docId === phase.id ? loadingPhase.step : null}
                            isOpen={openPhases.includes(phase.id)}
                            onToggleOpen={() => togglePhaseOpen(phase.id)}
                        />
                    </div>
                );
            })}
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { parseMarkdown } from '../utils/markdownParser.ts';
import { GRAPHICAL_ARTIFACTS } from '../constants/projectData.ts';

interface PhaseCardProps {
    phase: { id: string; title: string; description: string; originalPhaseId: string; };
    project: any;
    phaseData: string | undefined;
    images?: string[];
    selectedArtifacts?: string[];
    attachments: Array<{ name: string, data: string }>;
    updatePhaseData: (phaseId: string, content: string) => void;
    isLocked: boolean;
    lockReason: string | null;
    onGenerate: (phaseId: string, currentContent: string) => void;
    onGenerateImages: (phaseId: string, artifacts: string[], content: string) => void;
    onChatToChange: (phaseId: string, instruction: string) => void;
    onComplete: (phaseId: string) => void;
    onAttachFile: (phaseId: string, fileData: { name: string, data: string }) => void;
    onRemoveAttachment: (phaseId: string, fileName: string) => void;
    status: 'locked' | 'completed' | 'todo' | 'failed';
    isLoading: boolean;
    loadingStep: 'generating' | 'compacting' | 'imaging' | null;
    isOpen: boolean;
    onToggleOpen: () => void;
}

export const PhaseCard: React.FC<PhaseCardProps> = ({ phase, project, phaseData, images = [], selectedArtifacts = [], attachments, updatePhaseData, isLocked, lockReason, onGenerate, onGenerateImages, onChatToChange, onComplete, onAttachFile, onRemoveAttachment, status, isLoading, loadingStep, isOpen, onToggleOpen }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [editedContent, setEditedContent] = useState(phaseData || '');
    const [chatInput, setChatInput] = useState('');
    const [localSelectedArtifacts, setLocalSelectedArtifacts] = useState<string[]>(selectedArtifacts);
    const descriptionFileInputRef = useRef<HTMLInputElement>(null);
    const attachmentFileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        setEditedContent(phaseData || '');
        if (isLoading) {
            setIsEditing(false);
        }
    }, [phaseData, isLoading]);

    useEffect(() => {
        setLocalSelectedArtifacts(selectedArtifacts);
    }, [selectedArtifacts]);

    const handleToggle = () => {
        if (!isLocked) {
            onToggleOpen();
        }
    };

    const handleSave = () => {
        updatePhaseData(phase.id, editedContent);
        setIsEditing(false);
    };

    const handleChatSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (chatInput.trim()) {
            onChatToChange(phase.id, chatInput);
            setChatInput('');
        }
    };

    const toggleArtifact = (artifact: string) => {
        setLocalSelectedArtifacts(prev => {
            if (prev.includes(artifact)) {
                return prev.filter(a => a !== artifact);
            }
            if (prev.length < 3) {
                return [...prev, artifact];
            }
            return prev;
        });
    };

    const handleGenerateGraphics = () => {
        if (localSelectedArtifacts.length > 0) {
            onGenerateImages(phase.id, localSelectedArtifacts, phaseData || editedContent);
        }
    };

    const handleDescriptionFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file && file.type === 'text/plain') {
            const reader = new FileReader();
            reader.onload = (e) => {
                const text = e.target?.result as string;
                updatePhaseData(phase.id, text);
            };
            reader.readAsText(file);
