async function withRetry<T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> {
    let lastError: Error | any = new Error("Unknown error");
    for (let i = 0; i < retries; i++) {
        try {
            return await fn();
        } catch (error: any) {
            lastError = error;
            console.warn(`Attempt ${i + 1} failed. Retrying...`, error);
            if (error?.message?.includes("API_KEY_INVALID") || error?.message?.includes("safety")) {
                throw error;
            }
            if (i < retries - 1) {
                await new Promise(res => setTimeout(res, delay * Math.pow(2, i)));
            }
        }
    }
    throw lastError;
};

const getPromptFunction = (docTitle: string, phase: number) => {
    const title = docTitle.toLowerCase();
    if (phase === 1 && title.includes('concept proposal')) return PROMPTS.phase1;
    if (title.includes('resources & skills')) return PROMPTS.phase2;
    if (title.includes('swot') || title.includes('risk analysis')) return PROMPTS.phase3;
    if (title.includes('kickoff briefing')) return PROMPTS.phase4;
    if (title.includes('statement of work') || title.includes('sow')) return PROMPTS.phase5;
    if (title.includes('preliminary review')) return PROMPTS.phase6;
    if (title.includes('detailed plans')) return PROMPTS.phase7;

    if (phase === 8) {
        if (title.includes('sprint requirements') || title.includes('user story backlog')) return PROMPTS.phase8_sprintRequirements;
        if (title.includes('sprint plan review')) return PROMPTS.phase8_sprintPlanReview;
        if (title.includes('critical review')) return PROMPTS.phase8_criticalReview;
        return (name: string, disc: string, ctx: string, mode: any, scope: any, team: any, comp: any) => PROMPTS.phase8_generic(docTitle, name, disc, ctx, mode, scope, team, comp);
    }

    if (phase === 9) return PROMPTS.phase9;

    return (name: string, disc: string, ctx: string, mode: any, scope: any, team: any, comp: any) => PROMPTS.genericDocumentPrompt(docTitle, phase, name, disc, ctx, mode, scope, team, comp);
}

const getRelevantContext = (docToGenerate: any, allDocuments: any[], allPhasesData: any) => {
    const sortedDocuments = [...allDocuments]
        .filter(d => d.type !== 'image')
        .sort((a, b) => a.phase - b.phase || (a.sequence || 1) - (b.sequence || 1));
    const currentIndex = sortedDocuments.findIndex(d => d.id === docToGenerate.id);
    const firstDoc = sortedDocuments[0];
    const firstDocPhaseData = firstDoc ? allPhasesData[firstDoc.id] : null;
    const firstDocContext = (firstDoc && (firstDoc.status === 'Approved' || firstDoc.phase === 1) && firstDocPhaseData?.compactedContent) ? firstDocPhaseData.compactedContent : '';
    const prevDoc = currentIndex > 0 ? sortedDocuments[currentIndex - 1] : null;
    const prevDocPhaseData = prevDoc ? allPhasesData[prevDoc.id] : null;
    const prevDocContext = (prevDoc && (prevDoc.status === 'Approved' || (prevDocPhaseData?.content && prevDocPhaseData.content.length > 50)) && prevDocPhaseData?.compactedContent) ? prevDocPhaseData.compactedContent : '';
    return { firstDocContext, prevDocContext };
};

const MAX_PAYLOAD_CHARS = 25000;
const truncatePrompt = (prompt: string): string => {
    if (prompt.length <= MAX_PAYLOAD_CHARS) return prompt;
    return prompt.substring(0, MAX_PAYLOAD_CHARS) + "\n...[PROMPT TRUNCATED]...";
};

export const ProjectDashboard: React.FC<{ project: Project; onBack: () => void; ai: GoogleGenAI | null; saveProject: (project: Project) => void; currentUser: User; key?: number; }> = ({ project, onBack, ai, saveProject, currentUser }) => {
    const [projectData, setProjectData] = useState<Project>({ ...project });
    const [loadingPhase, setLoadingPhase] = useState<{ docId: string | null; step: 'generating' | 'compacting' | 'imaging' | null }>({ docId: null, step: null });
    const [error, setError] = useState('');
    const [activeTab, setActiveTab] = useState('Project Phases');
    const [isAutoGenerating, setIsAutoGenerating] = useState(false);
    const [selectedTask, setSelectedTask] = useState<Task | null>(null);
    const [aiReport, setAiReport] = useState({ title: '', content: '', isOpen: false });
    const [isGeneratingReport, setIsGeneratingReport] = useState<'risk' | 'summary' | null>(null);

    const projectDataRef = useRef(projectData);
    useEffect(() => { projectDataRef.current = projectData; }, [projectData]);

    useEffect(() => {
        setProjectData(project);
    }, [project]);

    const projectPhases = useMemo(() => {
        return [...projectData.documents]
            .filter(d => d.type !== 'image')
            .sort((a, b) => (a.phase - b.phase) || (a.sequence - b.sequence))
            .map(doc => ({
                id: doc.id,
                title: doc.title,
                description: PHASES.find(p => parseInt(p.id.replace('phase', '')) === doc.phase)?.description || '',
                originalPhaseId: `phase${doc.phase}`
            }));
    }, [projectData.documents]);

    const handleSave = useCallback((update: Partial<Project> | ((prev: Project) => Partial<Project>)) => {
        setProjectData(prevData => {
            const dataToMerge = typeof update === 'function' ? update(prevData) : update;
            const newState = { ...prevData, ...dataToMerge };
            saveProject(newState);
            return newState;
        });
    }, [saveProject]);

    const handleTabChange = useCallback((tabName: string) => {
        setActiveTab(tabName);
        localStorage.setItem(`hmap-active-tab-${project.id}`, tabName);
    }, [project.id]);

    useEffect(() => {
        const savedTab = localStorage.getItem(`hmap-active-tab-${project.id}`);
        setActiveTab(savedTab || 'Project Phases');
    }, [project.id]);

    const handleGenerateImages = useCallback(async (docId: string, artifacts: string[], textContent: string) => {
        if (!ai || artifacts.length === 0) return;

        const parentDoc = projectDataRef.current.documents.find(d => d.id === docId);
        if (!parentDoc) return;

        setLoadingPhase({ docId, step: 'imaging' });
        try {
            const generatedImages: string[] = [];
            const artifactDocs: Document[] = [];

            for (const artifact of artifacts) {
                const prompt = `Professional, ultra-clean technical ${artifact} for project "${projectDataRef.current.name}" (${projectDataRef.current.discipline}). Visual representation of: ${textContent.substring(0, 800)}. Aspect Ratio: 16:9. Technical schematic style.`;

                const result = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
                    model: 'gemini-2.5-flash-image',
                    contents: { parts: [{ text: prompt }] },
                    config: { imageConfig: { aspectRatio: "16:9" } }
                }));

                const firstCandidate = result.candidates?.[0];
                if (!firstCandidate) continue;

                for (const part of firstCandidate.content.parts) {
                    if (part.inlineData) {
                        const base64EncodeString: string = part.inlineData.data;
                        const dataUrl = `data:image/png;base64,${base64EncodeString}`;
                        generatedImages.push(dataUrl);

                        artifactDocs.push({
                            id: `artifact-${docId}-${artifact.toLowerCase().replace(/\s/g, '-')}-${Date.now()}`,
                            title: `${parentDoc.title} - ${artifact}`,
                            version: 'v1.0',
                            status: 'Working',
                            owner: currentUser.username,
                            phase: parentDoc.phase,
                            sequence: parentDoc.sequence + 1,
                            type: 'image',
                            parentDocId: docId
                        });
                    }
                }
            }

            handleSave(prev => {
                const otherDocs = prev.documents.filter(d => d.parentDocId !== docId || d.type !== 'image');
                const newPhasesData = { ...prev.phasesData };
                newPhasesData[docId] = {
                    ...newPhasesData[docId],
                    images: generatedImages,
                    selectedArtifacts: artifacts
                };

                artifactDocs.forEach((aDoc, idx) => {
                    newPhasesData[aDoc.id] = { content: generatedImages[idx] };
                });

                return {
                    documents: [...otherDocs, ...artifactDocs],
                    phasesData: newPhasesData
                };
            });
        } catch (err) {
            console.error("Image generation failed:", err);
            setError("Image generation failed. Please check your API key/billing.");
        } finally {
            setLoadingPhase({ docId: null, step: null });
        }
    }, [ai, handleSave, currentUser.username]);

    const handleGenerateContent = useCallback(async (docId: string, userInput: string, projectStateOverride?: Project) => {
        if (!ai) {
            setError("AI Client not initialized.");
            return { success: false, newContent: null, newCompactedContent: null };
        }

        const currentProjectData = projectStateOverride || projectDataRef.current;
        const docToGenerate = currentProjectData.documents.find(d => d.id === docId);
        if (!docToGenerate) return { success: false, newContent: null, newCompactedContent: null };

        setLoadingPhase({ docId, step: 'generating' });
        setError('');

        try {
            const { firstDocContext, prevDocContext } = getRelevantContext(docToGenerate, currentProjectData.documents, currentProjectData.phasesData);
            const contextString = `${firstDocContext}\n\n${prevDocContext}`.trim();
            const promptFn = getPromptFunction(docToGenerate.title, docToGenerate.phase);
            const primaryInput = docToGenerate.phase === 1 ? (userInput || "Starting project documentation") : (contextString || userInput || "Continuing project documentation based on existing scope.");

            const promptText = promptFn(
                currentProjectData.name, 
                currentProjectData.discipline, 
                primaryInput, 
                currentProjectData.mode, 
                currentProjectData.scope, 
                currentProjectData.teamSize, 
                currentProjectData.complexity
            );

            const result = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({ 
                model: 'gemini-3-flash-preview', 
                contents: truncatePrompt(promptText),
                config: { 
                    temperature: 0.7,
                    thinkingConfig: { thinkingBudget: 0 }
                }
            }));

            const newContent = result.text || '';
            if (!newContent) {
                throw new Error("The AI returned an empty response. Please try again.");
            }

            setLoadingPhase({ docId, step: 'compacting' });
            const compactResult = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({ 
                model: 'gemini-3-flash-preview', 
                contents: PROMPTS.compactContent(newContent),
                config: { thinkingConfig: { thinkingBudget: 0 } }
            }));
            const newCompactedContent = compactResult.text || newContent.substring(0, 500);

            handleSave(prev => ({
                phasesData: { 
                    ...prev.phasesData, 
                    [docId]: { ...(prev.phasesData[docId] || {}), content: newContent, compactedContent: newCompactedContent } 
                }
            }));

            return { success: true, newContent, newCompactedContent };
        } catch (err: any) {
            console.error("AI Generation Error:", err);
            setError(`AI Error: ${err.message || "Unknown error during generation"}`);
            return { success: false, newContent: null, newCompactedContent: null };
        } finally {
            setLoadingPhase({ docId: null, step: null });
        }
    }, [ai, handleSave]);

    const handleUpdatePhaseData = useCallback(async (docId: string, content: string) => {
        handleSave(prev => ({
            phasesData: {
                ...prev.phasesData,
                [docId]: { ...(prev.phasesData[docId] || {}), content }
            }
        }));

        const currentData = projectDataRef.current.phasesData[docId];
        if (currentData?.selectedArtifacts && currentData.selectedArtifacts.length > 0) {
            await handleGenerateImages(docId, currentData.selectedArtifacts, content);
        }
    }, [handleSave, handleGenerateImages]);

    const handleChatToChange = useCallback(async (docId: string, userInstruction: string) => {
        if (!ai) return;
        const currentData = projectDataRef.current.phasesData[docId];
        const currentContent = currentData?.content || '';

        setLoadingPhase({ docId, step: 'generating' });
        setError('');
        try {
            const prompt = `You are a project management assistant. Modify the following project document based on this instruction: "${userInstruction}".\n\nOriginal Document:\n${currentContent}\n\nProvide the updated full document content.`;
            const result = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({ 
                model: 'gemini-3-flash-preview', 
                contents: prompt,
                config: { thinkingConfig: { thinkingBudget: 0 } }
            }));
            const newContent = result.text || '';

            const compactResult = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({ 
                model: 'gemini-3-flash-preview', 
                contents: PROMPTS.compactContent(newContent),
                config: { thinkingConfig: { thinkingBudget: 0 } }
            }));

            handleSave(prev => ({
                phasesData: {
                    ...prev.phasesData,
                    [docId]: { ...(prev.phasesData[docId] || {}), content: newContent, compactedContent: compactResult.text }
                }
            }));

            if (currentData?.selectedArtifacts && currentData.selectedArtifacts.length > 0) {
                await handleGenerateImages(docId, currentData.selectedArtifacts, newContent);
            }
        } catch (e: any) {
            console.error("Chat to change failed:", e);
            setError(`Instruction failed: ${e.message}`);
        } finally {
            setLoadingPhase({ docId: null, step: null });
        }
    }, [ai, handleSave, handleGenerateImages]);

    const handleCompletePhase = useCallback((docId: string) => {
        handleSave(prev => ({
            documents: prev.documents.map(d => d.id === docId ? { ...d, status: 'Approved' } : d)
        }));
    }, [handleSave]);

    const handleAttachFile = useCallback((docId: string, file: { name: string, data: string }) => {
        handleSave(prev => ({
            phasesData: {
                ...prev.phasesData,
                [docId]: {
                    content: prev.phasesData[docId]?.content || '',
                    ...(prev.phasesData[docId] || {}),
                    attachments: [...(prev.phasesData[docId]?.attachments || []), file]
                }
            }
        }));
    }, [handleSave]);

    const handleRemoveAttachment = useCallback((docId: string, fileName: string) => {
        handleSave(prev => ({
            phasesData: {
                ...prev.phasesData,
                [docId]: {
                    content: prev.phasesData[docId]?.content || '',
                    ...(prev.phasesData[docId] || {}),
                    attachments: (prev.phasesData[docId]?.attachments || []).filter(a => a.name !== fileName)
                }
            }
        }));
    }, [handleSave]);

    const handleSetGenerationMode = useCallback((mode: 'manual' | 'automatic') => {
        handleSave({ generationMode: mode });
    }, [handleSave]);

    const runAutomaticGeneration = useCallback(async () => {
        if (isAutoGenerating || !ai) return;
        setIsAutoGenerating(true);
        setError('');

        try {
            let currentProjectState = { ...projectDataRef.current };
            const sortedDocs = [...currentProjectState.documents]
                .filter(d => d.type !== 'image')
                .sort((a, b) => (a.phase - b.phase) || (a.sequence || 1) - (b.sequence || 1));

            for (const doc of sortedDocs) {
                if (doc.status === 'Approved') continue;

                const res = await handleGenerateContent(doc.id, '', currentProjectState);
                if (!res.success) throw new Error(`Generation failed at "${doc.title}". Switched to Manual mode.`);

                handleCompletePhase(doc.id);

                currentProjectState = {
                    ...currentProjectState,
                    documents: currentProjectState.documents.map(d => d.id === doc.id ? { ...d, status: 'Approved' } : d),
                    phasesData: {
                        ...currentProjectState.phasesData,
                        [doc.id]: { ...currentProjectState.phasesData[doc.id], content: res.newContent, compactedContent: res.newCompactedContent }
                    }
                };

                await new Promise(resolve => setTimeout(resolve, 2000));
            }
        } catch (e: any) {
            setError(e.message);
            handleSetGenerationMode('manual');
        } finally {
            setIsAutoGenerating(false);
        }
    }, [ai, handleGenerateContent, handleCompletePhase, handleSetGenerationMode, isAutoGenerating]);

    useEffect(() => {
        if (projectData.generationMode === 'automatic' && !isAutoGenerating) {
            runAutomaticGeneration();
        }
    }, [projectData.generationMode, isAutoGenerating, runAutomaticGeneration]);

    const generateAgentPlan = useCallback(async () => {
        if (!ai) return;
        setLoadingPhase({ docId: 'agent', step: 'generating' });
        setError('');
        try {
            const contextDoc = projectData.documents.find(d => d.title.includes('Statement of Work'));
            const context = contextDoc ? projectData.phasesData[contextDoc.id]?.compactedContent : '';

            const config = { thinkingConfig: { thinkingBudget: 0 } };
            const plannerPrompt = PROMPTS.plannerAgent(context);
            const plannerRes = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: plannerPrompt, config }));

            const doerPrompt = PROMPTS.doerAgent(plannerRes.text || '', context);
            const doerRes = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: doerPrompt, config }));

            const qaPrompt = PROMPTS.qaAgent(doerRes.text || '');
            const qaRes = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: qaPrompt, config }));

            const finalPlan = qaRes.text || '';
            const sections = finalPlan.split('## ');
            const tasksText = sections.find(s => s.toLowerCase().startsWith('tasks')) || '';
            const parsedTasks = parseMarkdownTable(tasksText);

            const taskMap = new Map();
            const newTasks: Task[] = parsedTasks.map((t, i) => {
                const id = `task-${Date.now()}-${i}`;
                taskMap.set(t.task_name?.toLowerCase().trim(), id);
                return {
                    id, name: t.task_name, role: t.role, startDate: t.start_date_yyyy_mm_dd, endDate: t.end_date_yyyy_mm_dd,
                    status: 'todo' as const, sprintId: 'sprint1', dependsOn: t.dependencies ? t.dependencies.split(',').map(d => d.trim()) : [],
                    isSubcontracted: t.subcontractor?.toLowerCase() === 'yes', comments: [], attachments: [], useAgent: false,
                    actualTime: null, actualCost: null, actualEndDate: null
                };
            });

            newTasks.forEach(t => {
                t.dependsOn = (t.dependsOn as string[]).map(d => taskMap.get(d.toLowerCase())).filter(Boolean);
            });

            handleSave({ tasks: newTasks, isStarted: true });
            handleTabChange('Project Tracking');
        } catch (e: any) {
            setError("Agentic planning failed: " + e.message);
        } finally {
            setLoadingPhase({ docId: null, step: null });
        }
    }, [ai, projectData, handleSave, handleTabChange]);

    const handleUpdateTask = (taskId: string, update: Partial<Task>) => {
        handleSave(prev => ({
            tasks: prev.tasks.map(t => t.id === taskId ? { ...t, ...update } : t)
        }));
    };

    const handleUpdateMilestone = (mId: string, update: Partial<Milestone>) => {
        handleSave(prev => ({
            milestones: prev.milestones.map(m => m.id === mId ? { ...m, ...update } : m)
        }));
    };

    const handleUpdateTeam = (newTeam: any, newOwnerId?: string) => {
        handleSave(prev => ({
            team: newTeam,
            ownerId: newOwnerId || prev.ownerId
        }));
    };

    const handleAnalyzeRisks = async () => {
        if (!ai) return;
        setIsGeneratingReport('risk');
        try {
            const context = projectPhases.slice(0, 5).map(p => projectData.phasesData[p.id]?.compactedContent).filter(Boolean).join('\n\n');
            const summary = { name: projectData.name, tasks: projectData.tasks.length, complexity: projectData.complexity };
            const prompt = PROMPTS.analyzeRisks(summary, context);
            const res = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt, config: { thinkingConfig: { thinkingBudget: 0 } } });
            setAiReport({ title: 'AI Risk Analysis', content: res.text || '', isOpen: true });
        } catch (e) { setError('Failed to analyze risks.'); } finally { setIsGeneratingReport(null); }
    };

    const handleGenerateSummary = async () => {
        if (!ai) return;
        setIsGeneratingReport('summary');
        try {
            const context = projectPhases.slice(0, 5).map(p => projectData.phasesData[p.id]?.compactedContent).filter(Boolean).join('\n\n');
            const summary = { name: projectData.name, tasks: projectData.tasks.length };
            const prompt = PROMPTS.generateStatusSummary(summary, context);
            const res = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt, config: { thinkingConfig: { thinkingBudget: 0 } } });
            setAiReport({ title: 'Project Status Summary', content: res.text || '', isOpen: true });
        } catch (e) { setError('Failed to generate summary.'); } finally { setIsGeneratingReport(null); }
    };

    const handleAddToDocuments = (title: string, content: string) => {
        const newDoc: Document = {
            id: `doc-ai-${Date.now()}`, title, version: 'v1.0', status: 'Working', owner: currentUser.username, phase: 8, sequence: 10
        };
        handleSave(prev => ({
            documents: [...prev.documents, newDoc],
            phasesData: { ...prev.phasesData, [newDoc.id]: { content } }
        }));
        alert(`"${title}" added to Documents.`);
    };

    const handleExportCsv = () => {
        const headers = ["ID", "Task Name", "Duration", "Start", "Finish", "Predecessors", "Resources"];
        const rows = projectData.tasks.map((t, i) => {
            const duration = Math.round((new Date(t.endDate).getTime() - new Date(t.startDate).getTime()) / (1000 * 3600 * 24)) + 1;
            return [i + 1, t.name, `${duration} days`, t.startDate, t.endDate, t.dependsOn.join(';'), t.role];
        });
        const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement("a");
        link.href = URL.createObjectURL(blob);
        link.download = `${projectData.name}_MS_Project.csv`;
        link.click();
    };

    return (
        <section>
            <div className="dashboard-header" style={{ marginBottom: '2rem' }}>
                <button onClick={onBack} className="button">← Back</button>
                <div style={{ marginLeft: '1.5rem' }}>
                    <h1 style={{ fontSize: '2.4rem', marginBottom: '0.2rem' }}>{projectData.name}</h1>
                    <p style={{ color: 'var(--secondary-text)', fontSize: '1.1rem' }}>{projectData.discipline} | Status: {projectData.isStarted ? 'Executing' : 'Planning'}</p>
                </div>
            </div>
            <nav className="dashboard-nav">
                <button onClick={() => handleTabChange('Dashboard')} className={activeTab === 'Dashboard' ? 'active' : ''}>Dashboard</button>
                <button onClick={() => handleTabChange('Project Phases')} className={activeTab === 'Project Phases' ? 'active' : ''}>Phases</button>
                <button onClick={() => handleTabChange('Documents')} className={activeTab === 'Documents' ? 'active' : ''}>Docs</button>
                <button onClick={() => handleTabChange('Project Tracking')} className={activeTab === 'Project Tracking' ? 'active' : ''}>Tracking</button>
                <button onClick={() => handleTabChange('Revision Control')} className={activeTab === 'Revision Control' ? 'active' : ''}>Control</button>
                <button onClick={handleExportCsv} className="button" style={{marginLeft: 'auto', border: 'none', background: 'transparent', color: 'var(--secondary-text)'}}>Export CSV</button>
            </nav>

            {loadingPhase.step && (
                <div className="status-message loading" style={{marginBottom: '2rem'}}>
                    <div className="spinner"></div>
                    <p>
                        {loadingPhase.step === 'generating' ? 'AI is generating plan content...' : 
                         loadingPhase.step === 'compacting' ? 'Compacting for context...' :
                         'AI is generating graphical artifacts...'}
                    </p>
                </div>
            )}

            {activeTab === 'Dashboard' && (
                <DashboardView 
                    project={projectData} 
                    phasesData={projectData.phasesData} 
                    isPlanningComplete={projectData.documents.filter(d => d.type !== 'image').every(d => d.status === 'Approved')} 
                    projectPhases={projectPhases} 
                    onAnalyzeRisks={handleAnalyzeRisks} 
                    onGenerateSummary={handleGenerateSummary} 
                    isGeneratingReport={isGeneratingReport} 
                />
            )}

            {activeTab === 'Project Phases' && (
                <div>
                    <ProjectPhasesView 
                        project={projectData} 
                        projectPhases={projectPhases} 
                        phasesData={projectData.phasesData} 
                        documents={projectData.documents} 
                        error={error} 
                        loadingPhase={loadingPhase} 
                        handleUpdatePhaseData={handleUpdatePhaseData} 
                        handleCompletePhase={handleCompletePhase} 
                        handleGenerateContent={handleGenerateContent} 
                        handleGenerateImages={handleGenerateImages}
                        handleChatToChange={handleChatToChange}
                        handleAttachFile={handleAttachFile} 
                        handleRemoveAttachment={handleRemoveAttachment} 
                        generationMode={projectData.generationMode} 
                        onSetGenerationMode={handleSetGenerationMode} 
                        isAutoGenerating={isAutoGenerating} 
                    />
                    {!projectData.isStarted && projectData.documents.filter(d => d.type !== 'image').every(d => d.status === 'Approved') && (
                        <div style={{textAlign: 'center', marginTop: '4rem', padding: '4rem', background: 'rgba(0,255,170,0.05)', borderRadius: '12px', border: '1px dashed var(--success-color)'}}>
                            <h2 style={{color: 'var(--success-color)', marginBottom: '1rem'}}>Planning Complete!</h2>
                            <p style={{marginBottom: '2rem', color: 'var(--secondary-text)'}}>The AI has structured your planning documents. Run the final agentic workflow to generate your timeline and tasks.</p>
                            <button className="button button-primary" onClick={generateAgentPlan} style={{fontSize: '1.2rem', padding: '1.5rem 3rem'}}>Run 3-Agent Planning Workflow</button>
                        </div>
                    )}
                </div>
            )}

            {activeTab === 'Documents' && <DocumentsView project={projectData} documents={projectData.documents} onUpdateDocument={(id, status) => handleSave(p => ({ documents: p.documents.map(d => d.id === id ? { ...d, status } : d) }))} phasesData={projectData.phasesData} ai={ai} />}

            {activeTab === 'Project Tracking' && (
                <ProjectTrackingView 
                    project={projectData} 
                    onUpdateTask={handleUpdateTask} 
                    onUpdateMilestone={handleUpdateMilestone} 
                    onUpdateTeam={handleUpdateTeam} 
                    onUpdateProject={handleSave} 
                    onTaskClick={setSelectedTask} 
                    currentUser={currentUser} 
                />
            )}

            {activeTab === 'Revision Control' && <RevisionControlView project={projectData} onUpdateProject={handleSave} ai={ai} />}

            {selectedTask && (
                <TaskDetailModal 
                    isOpen={!!selectedTask} 
                    onClose={() => setSelectedTask(null)} 
                    onSave={(t) => handleUpdateTask(t.id, t)} 
                    task={selectedTask} 
                    project={projectData} 
                    currentUser={currentUser} 
                />
            )}

            <AiReportModal 
                isOpen={aiReport.isOpen} 
                onClose={() => setAiReport(prev => ({ ...prev, isOpen: false }))} 
                title={aiReport.title} 
                content={aiReport.content} 
                onAddToDocuments={handleAddToDocuments} 
            />
        </section>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { TeamAssignmentsView } from './TeamView.tsx';
import { Project, Task, User } from '../types.ts';
import { WorkloadView } from './WorkloadView.tsx';
import { parseResourcesFromMarkdown } from '../utils/be-logic.ts';

const ResourcesView = ({ project, onUpdateProject }) => {
    const [resources, setResources] = useState(project.resources || []);
    const extractedResources = useMemo(() => {
        const resourceDoc = project.documents.find(d => d.title === 'Resources & Skills List');
        if (!resourceDoc || !project.phasesData || !project.phasesData[resourceDoc.id]?.content) return [];
        return parseResourcesFromMarkdown(project.phasesData[resourceDoc.id].content);
    }, [project.documents, project.phasesData]);

    useEffect(() => {
        const projectResources = project.resources || [];
        const currentResourceNames = new Set(projectResources.map(r => r.name));
        const newResourcesToAdd = extractedResources
            .filter(name => !currentResourceNames.has(name))
            .map(name => ({ name, estimate: 0, actual: 0 }));
        if (newResourcesToAdd.length > 0) {
            onUpdateProject({ resources: [...projectResources, ...newResourcesToAdd] });
        }
    }, [extractedResources, project.resources, onUpdateProject]);

    const handleUpdate = (index, field, value) => {
        const newResources = [...resources];
        newResources[index] = { ...newResources[index], [field]: field === 'name' ? value : parseFloat(value) || 0 };
        setResources(newResources);
    };

    const handleBlur = () => onUpdateProject({ resources });

    return (
        <div className="glass-card" style={{ padding: '0', borderLeft: 'none' }}>
            <table>
                <thead><tr><th>Resource Vector</th><th>Budgeted Allocation</th><th>Actual Consumption</th></tr></thead>
                <tbody>
                    {resources.map((r, i) => (
                        <tr key={i}>
                            <td><input type="text" value={r.name} onChange={e => handleUpdate(i, 'name', e.target.value)} onBlur={handleBlur} style={{ background: 'transparent', border: 'none', padding: '0.5rem' }} /></td>
                            <td><input type="number" value={r.estimate} onChange={e => handleUpdate(i, 'estimate', e.target.value)} onBlur={handleBlur} style={{ background: 'transparent', border: 'none', padding: '0.5rem' }} /></td>
                            <td><input type="number" value={r.actual} onChange={e => handleUpdate(i, 'actual', e.target.value)} onBlur={handleBlur} style={{ background: 'transparent', border: 'none', padding: '0.5rem' }} /></td>
                        </tr>
                    ))}
                    {resources.length === 0 && <tr><td colSpan={3} style={{ textAlign: 'center', padding: '4rem', opacity: 0.5 }}>No resources defined in planning phase.</td></tr>}
                </tbody>
            </table>
        </div>
    );
};

const TaskListView = ({ tasks, team, onTaskClick }) => (
    <div className="glass-card" style={{ padding: '0', borderLeft: 'none' }}>
        <table>
            <thead><tr><th>Task Identifier</th><th>Assigned Intelligence</th><th>Status</th><th>Target Date</th></tr></thead>
            <tbody>
                {tasks.map(t => (
                    <tr key={t.id} onClick={() => onTaskClick(t)} style={{cursor: 'pointer'}}>
                        <td style={{ fontWeight: 700 }}>{t.name}</td>
                        <td>{team.find(m => m.role === t.role)?.name || 'Unassigned'}</td>
                        <td><span className={`chip-${t.status === 'done' ? 'green' : t.status === 'inprogress' ? 'blue' : 'amber'}`}>{t.status}</span></td>
                        <td style={{ fontFamily: 'monospace' }}>{t.endDate}</td>
                    </tr>
                ))}
                {tasks.length === 0 && <tr><td colSpan={4} style={{ textAlign: 'center', padding: '4rem', opacity: 0.5 }}>Mission queue empty.</td></tr>}
            </tbody>
        </table>
    </div>
);

export const ProjectTrackingView: React.FC<{ project: Project; onUpdateTask: any; onUpdateMilestone: any; onUpdateTeam: any; onUpdateProject: any; onTaskClick: any; currentUser: User; }> = ({ project, onUpdateTask, onUpdateMilestone, onUpdateTeam, onUpdateProject, onTaskClick, currentUser }) => {
    const [trackingView, setTrackingView] = useState('Timeline');
    useEffect(() => {
        const saved = localStorage.getItem(`hmap-tracking-view-${project.id}`);
        if (saved) setTrackingView(saved);
    }, [project.id]);

    const handleViewChange = (view) => {
        setTrackingView(view);
        localStorage.setItem(`hmap-tracking-view-${project.id}`, view);
    };

    const viewOrder = ['Timeline', 'Task List', 'Kanban Board', 'Workload', 'Milestones', 'Team', 'Resources'];

    return (
        <div>
            <div className="dashboard-nav">
                {viewOrder.map(v => (
                    <button key={v} onClick={() => handleViewChange(v)} className={trackingView === v ? 'active' : ''}>{v}</button>
                ))}
            </div>

            <div style={{ animation: 'slideUp 0.6s cubic-bezier(0.16, 1, 0.3, 1)' }}>
                {trackingView === 'Timeline' && (
                    <div className="tool-card" style={{ padding: '8rem 2rem', textAlign: 'center' }}>
                        <div style={{ fontSize: '4rem', marginBottom: '2rem', opacity: 0.2 }}>⏱️</div>
                        <h3 className="subsection-title">Timeline Interface Loading</h3>
                        <p style={{ color: 'var(--secondary-text)', maxWidth: '500px', margin: '0 auto' }}>Synchronizing chronological tasks with Gantt engine...</p>
                    </div>
                )}
                {trackingView === 'Task List' && <TaskListView tasks={project.tasks} team={project.team} onTaskClick={onTaskClick} />}
                {trackingView === 'Resources' && <ResourcesView project={project} onUpdateProject={onUpdateProject} />}
                {trackingView === 'Team' && <div className="glass-card" style={{ padding: '3rem', borderLeft: 'none' }}><TeamAssignmentsView project={project} onUpdateTeam={onUpdateTeam} currentUser={currentUser} /></div>}
                {trackingView === 'Workload' && <div className="glass-card" style={{ borderLeft: 'none' }}><WorkloadView project={project} /></div>}
                {trackingView === 'Kanban Board' && (
                    <div className="tool-card" style={{ padding: '8rem 2rem', textAlign: 'center' }}>
                         <div style={{ fontSize: '4rem', marginBottom: '2rem', opacity: 0.2 }}>📋</div>
                        <h3 className="subsection-title">Kanban Interface Offline</h3>
                        <p style={{ color: 'var(--secondary-text)', maxWidth: '500px', margin: '0 auto' }}>Task visualization pipeline currently under maintenance.</p>
                    </div>
                )}
                {trackingView === 'Milestones' && (
                    <div className="glass-card" style={{ padding: '0', borderLeft: 'none' }}>
                        <table>
                            <thead><tr><th>Milestone Title</th><th>Target Date</th><th>Status</th></tr></thead>
                            <tbody>
                                {project.milestones.map(m => (
