import React, { useState, useMemo, useEffect } from 'react';
import { Type, GoogleGenAI } from "@google/genai";
import { logAction } from '../utils/logging.ts';
import { PROMPTS } from '../constants/projectData.ts';
import { ChangeDeploymentModal } from '../components/ChangeDeploymentModal.tsx';
import { parseImpact, applyImpact } from '../utils/be-logic.ts';

// Safety limits for API payload
const MAX_PAYLOAD_CHARS = 20000; // Drastically reduced to prevent potential 500 errors from large requests.

const truncatePrompt = (prompt: string): string => {
    if (prompt.length <= MAX_PAYLOAD_CHARS) {
        return prompt;
    }

    console.warn('Prompt is too large, truncating from the end to fit payload limits.');
    logAction('Truncate Prompt', 'Payload Management', { originalLength: prompt.length, newLength: MAX_PAYLOAD_CHARS });

    return prompt.substring(0, MAX_PAYLOAD_CHARS) + "\n...[PROMPT TRUNCATED DUE TO PAYLOAD SIZE]...";
};

// Updated RevisionControlView props to accept GoogleGenAI | null and added safety checks for AI initialization.
export const RevisionControlView = ({ project, onUpdateProject, ai }: {project: any, onUpdateProject: (update: any) => void, ai: GoogleGenAI | null}) => {
    const { changeRequest: cr, scenarios, name, discipline, tasks, documents, budget, endDate } = project;
    const [newScenario, setNewScenario] = useState({ name: '', impactStr: '' });
    const [deploymentPlan, setDeploymentPlan] = useState('');
    const [isGeneratingPlan, setIsGeneratingPlan] = useState(false);
    const [isDeploying, setIsDeploying] = useState(false);
    const [isEstimating, setIsEstimating] = useState(false);
    const [error, setError] = useState('');

    const handleCrChange = (newCrData) => {
        onUpdateProject({ changeRequest: newCrData });
        logAction('Update Change Request', name, newCrData);
    };

    const handleScenariosChange = (newScenarios) => {
        onUpdateProject({ scenarios: newScenarios });
        logAction('Update Scenarios', name, newScenarios);
    };

    const handleAddScenario = (e) => {
        e.preventDefault();
        if (newScenario.name && newScenario.impactStr) {
            const updatedScenarios = [...scenarios, { id: Date.now(), ...newScenario }];
            handleScenariosChange(updatedScenarios);
            setNewScenario({ name: '', impactStr: '' });
        }
    };

    const handleEstimateImpact = async () => {
        if (!cr.title || !cr.reason) {
            alert("Please provide a title and reason for the change request before estimating impact.");
            return;
        }
        // Added check for AI initialization before calling generateContent
        if (!ai) {
            setError("AI client is not initialized. Please ensure your API key is valid.");
            return;
        }
        setIsEstimating(true);
        setError('');
        try {
            const prompt = PROMPTS.estimateChangeImpact(name, discipline, budget, cr);
            const schema = {
                type: Type.OBJECT,
                properties: {
                    days: { type: Type.NUMBER, description: 'Estimated schedule impact in days (positive for delay, negative for acceleration).' },
                    cost: { type: Type.NUMBER, description: 'Estimated budget impact in currency (positive for cost increase, negative for savings).' }
                },
                required: ['days', 'cost']
            };
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview', contents: prompt, config: { responseMimeType: "application/json", responseSchema: schema },
            });
            const impact = JSON.parse(response.text);
            const newImpactStr = `${impact.days >= 0 ? '+' : ''}${impact.days}d ${impact.cost >= 0 ? '+' : ''}${impact.cost}c`;
            handleCrChange({ ...cr, impactStr: newImpactStr });
        } catch (err) {
            console.error("API Error estimating impact:", err);
            setError("Failed to estimate impact. Please check the console and try again.");
        } finally {
            setIsEstimating(false);
        }
    };

    const handleGeneratePlan = async () => {
        if (!cr.title || !cr.reason) {
            alert("Please provide a title and reason for the change request before generating a plan.");
            return;
        }
        // Added check for AI initialization before calling generateContent
        if (!ai) {
            setError("AI client is not initialized. Please ensure your API key is valid.");
            return;
        }
        setIsGeneratingPlan(true);
        setError('');
        try {
            const promptFn = PROMPTS.changeDeploymentPlan;
            const promptText = promptFn(name, discipline, cr, tasks, documents);
            const prompt = truncatePrompt(promptText);
            logAction('Generate Change Plan', name, { promptLength: prompt.length });

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: prompt,
            });

            setDeploymentPlan(response.text);
            logAction('Generate Change Plan Success', name, { plan: response.text });
        } catch (err) {
            console.error("API Error generating deployment plan:", err);
            setError("Failed to generate the deployment plan. Please check the console and try again.");
            logAction('Generate Change Plan Failure', name, { error: err.message });
        } finally {
            setIsGeneratingPlan(false);
        }
    };

    const baseline = useMemo(() => ({
        budget: budget,
        endDate: endDate,
    }), [budget, endDate]);

    const crImpact = useMemo(() => parseImpact(cr.impactStr), [cr.impactStr]);
    const crResult = useMemo(() => applyImpact(baseline, crImpact), [baseline, crImpact]);

    const scenarioResults = useMemo(() => scenarios.map(s => ({
        ...s,
        impact: parseImpact(s.impactStr),
        result: applyImpact(baseline, parseImpact(s.impactStr))
    })), [scenarios, baseline]);

    const currencyFormat = (num) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(num);

    const ImpactCell = ({ value, base }) => {
        const diff = value - base;
        const className = diff > 0 ? 'impact-positive' : diff < 0 ? 'impact-negative' : '';
        const sign = diff > 0 ? '+' : '';
        return <>{currencyFormat(value)} {diff !== 0 && <span className={className}>({sign}{currencyFormat(diff)})</span>}</>
    };

    const handleSaveChange = () => {
        if (!cr.title) {
            alert("Please provide a title for the change request before saving.");
            return;
        }

        const changeDocContent = `
# Change Request: ${cr.title}

## Reason for Change
${cr.reason}

## Estimated Impact
- **Time:** ${crImpact.days > 0 ? '+' : ''}${crImpact.days} days
- **Cost:** ${crImpact.cost > 0 ? '+' : ''}${currencyFormat(crImpact.cost)}

## What-If Scenarios Analysis

| Metric   | Baseline              | CR Impact             | ${scenarios.map(s => s.name).join(' | ')} |
|----------|-----------------------|-----------------------|${scenarios.map(() => '-----------------------').join('|')}
| End Date | ${baseline.endDate}   | ${crResult.endDate}   | ${scenarioResults.map(s => s.result.endDate).join(' | ')} |
| Budget   | ${currencyFormat(baseline.budget)} | ${currencyFormat(crResult.budget)} | ${scenarioResults.map(s => currencyFormat(s.result.budget)).join(' | ')} |
`;

        const newDoc = {
            id: `doc-cr-${Date.now()}`,
            title: `Change Request: ${cr.title}`,
            version: 'v1.0',
            status: 'Working',
            owner: 'A. User',
            phase: 8, // Associate with Sprint/Critical Design Planning
            content: changeDocContent.trim(),
        };

        const updatedDocuments = [...documents, newDoc];
        onUpdateProject({ documents: updatedDocuments });

        logAction('Save Change Request as Document', name, { document: newDoc });
        alert(`Document "${newDoc.title}" has been created and added to the Documents Center for approval.`);
    };

    return (
        <div className="tool-card">
            <h2 className="subsection-title">Revision & Change Control</h2>
            <div className="tool-grid" style={{ gridTemplateColumns: '1fr 2fr', gap: '2rem', alignItems: 'start' }}>
                <div>
                    <h4>Submit Change Request</h4>
                    <form>
                        <div className="form-group"><label>Title</label><input type="text" value={cr.title} onChange={e => handleCrChange({...cr, title: e.target.value})} /></div>
                        <div className="form-group"><label>Reason for Change</label><textarea rows={3} value={cr.reason} onChange={e => handleCrChange({...cr, reason: e.target.value})}></textarea></div>
                        <div className="form-group">
                            <label>Impact (e.g. +15d +5000c)</label>
                            <div style={{display: 'flex', gap: '0.5rem', alignItems: 'center'}}>
                                <input type="text" value={cr.impactStr} onChange={e => handleCrChange({...cr, impactStr: e.target.value})} style={{flexGrow: 1}}/>
                                <button type="button" className="button button-small" onClick={handleEstimateImpact} disabled={isEstimating || !ai}>
                                    {isEstimating ? '...' : 'Estimate'}
                                </button>
                            </div>
                        </div>
                    </form>

                    <h4 style={{marginTop: '2rem'}}>What-If Scenarios</h4>
                    <form onSubmit={handleAddScenario} style={{display: 'flex', gap: '1rem'}}>
                         <input type="text" placeholder="Scenario Name" value={newScenario.name} onChange={e => setNewScenario({...newScenario, name: e.target.value})} style={{flex: 1}}/>
                         <input type="text" placeholder="+10d -2000c" value={newScenario.impactStr} onChange={e => setNewScenario({...newScenario, impactStr: e.target.value})} style={{flex: 1}}/>
                         <button type="submit" className="button button-small">Add</button>
                    </form>
                </div>
                <div>
                    <h4>Auto Impact Analysis for "{cr.title}"</h4>
                    <table className="impact-table">
                        <thead>
                            <tr>
                                <th>Metric</th>
                                <th>Baseline</th>
                                <th>CR Impact</th>
                                {scenarioResults.map(s => <th key={s.id}>{s.name}</th>)}
                            </tr>
                        </thead>
                        <tbody>
                            <tr>
                                <td>End Date</td>
                                <td>{baseline.endDate}</td>
                                <td>{crResult.endDate} <span className={crImpact.days > 0 ? 'impact-positive' : ''}>{crImpact.days !== 0 && `(${crImpact.days > 0 ? '+':''}${crImpact.days}d)`}</span></td>
                                {scenarioResults.map(s => <td key={s.id}>{s.result.endDate} <span className={s.impact.days > 0 ? 'impact-positive' : ''}>{s.impact.days !== 0 && `(${s.impact.days > 0 ? '+':''}${s.impact.days}d)`}</span></td>)}
                            </tr>
                             <tr>
                                <td>Budget</td>
                                <td>{currencyFormat(baseline.budget)}</td>
                                <td><ImpactCell value={crResult.budget} base={baseline.budget} /></td>
                                {scenarioResults.map(s => <td key={s.id}><ImpactCell value={s.result.budget} base={baseline.budget} /></td>)}
                            </tr>
                        </tbody>
                    </table>
                     <div style={{marginTop: '1.5rem', display: 'flex', justifyContent: 'flex-end', gap: '1rem'}}>
                        <button className="button" onClick={handleSaveChange}>Save Change</button>
                        <button className="button button-primary">Submit for Approval</button>
                    </div>
                </div>
            </div>

            <div style={{borderTop: '1px solid var(--border-color)', marginTop: '2rem', paddingTop: '2rem'}}>
                <h3 className="subsection-title">Change Deployment</h3>
                <div className="form-group">
                    <label htmlFor="deploymentPlan">AI-Generated Deployment Plan</label>
                    <textarea 
                        id="deploymentPlan"
                        rows={12}
                        value={isGeneratingPlan ? 'Generating plan...' : deploymentPlan}
                        onChange={(e) => setDeploymentPlan(e.target.value)}
                        placeholder="Click 'Generate Deployment Plan' to create a step-by-step plan to implement this change."
                        readOnly={isGeneratingPlan}
                    />
                </div>
                {error && <p className="status-message error">{error}</p>}
                <div style={{display: 'flex', gap: '1rem'}}>
                    <button className="button" onClick={handleGeneratePlan} disabled={isGeneratingPlan || !ai}>
                        {isGeneratingPlan ? 'Generating...' : (deploymentPlan ? 'Regenerate Plan' : 'Generate Deployment Plan')}
                    </button>
                    <button className="button button-primary" onClick={() => setIsDeploying(true)} disabled={!deploymentPlan || isGeneratingPlan}>
                        Deploy Change...
                    </button>
                </div>
            </div>

            <ChangeDeploymentModal
                isOpen={isDeploying}
                onClose={() => setIsDeploying(false)}
                deploymentPlan={deploymentPlan}
                project={project}
                onUpdateProject={onUpdateProject}
            />
        </div>
    );
};

import React, { useMemo } from 'react';
import { Project } from '../types.ts';
import { parseRolesFromMarkdown } from '../utils/be-logic.ts';

// Helper to get the start of a week (Sunday)
const getStartOfWeek = (date: Date): Date => {
    const d = new Date(date);
    d.setHours(0, 0, 0, 0); // Normalize time
    const day = d.getDay();
    const diff = d.getDate() - day;
    return new Date(d.setDate(diff));
};

// Helper to get week ranges for the project duration
const getProjectWeeks = (startDateStr: string, endDateStr: string): Date[] => {
    const weeks: Date[] = [];
    if (!startDateStr || !endDateStr) return weeks;

    let current = getStartOfWeek(new Date(startDateStr));
    const end = new Date(endDateStr);

    while (current <= end) {
        weeks.push(new Date(current));
        current.setDate(current.getDate() + 7);
    }
    return weeks;
};

const getWorkloadColor = (days: number): string => {
    if (days > 4) return 'var(--error-color)'; // Heavy workload
    if (days >= 3) return 'var(--warning-color)'; // Medium workload
    if (days > 0) return 'var(--success-color)'; // Light workload
    return 'transparent'; // No work
};

interface WorkloadViewProps {
    project: Project;
}

export const WorkloadView: React.FC<WorkloadViewProps> = ({ project }) => {
    const { team, tasks, startDate, endDate, documents, phasesData } = project;

    const extractedRoles = useMemo(() => {
        const resourceDoc = documents.find(d => d.title === 'Resources & Skills List');
        if (!resourceDoc || !phasesData || !phasesData[resourceDoc.id]?.content) return [];
        return parseRolesFromMarkdown(phasesData[resourceDoc.id].content);
    }, [documents, phasesData]);

    if (!tasks || tasks.length === 0) {
        return <p>Workload view will be available once tasks are generated.</p>;
    }

    if (extractedRoles.length === 0) {
        return <p>Workload view requires roles to be defined in the 'Resources & Skills List' document.</p>;
    }

    const projectWeeks = getProjectWeeks(startDate, endDate);

    const workloadData = extractedRoles.map(role => {
        const member = team.find(m => m.role === role);
        const roleTasks = tasks.filter(task => task.role === role);

        const weeklyWorkload = projectWeeks.map(weekStart => {
            const weekEnd = new Date(weekStart);
            weekEnd.setDate(weekEnd.getDate() + 6);

            let totalDaysInWeek = 0;
            const tasksInWeek = [];

            roleTasks.forEach(task => {
                const taskStart = new Date(task.startDate);
                const taskEnd = new Date(task.endDate);
                taskStart.setHours(0, 0, 0, 0);
                taskEnd.setHours(0, 0, 0, 0);

                // Check for overlap between task and week
                if (taskStart <= weekEnd && taskEnd >= weekStart) {
                    tasksInWeek.push(task);

                    // Calculate workdays of this task within this week, excluding weekends
                    const overlapStart = new Date(Math.max(taskStart.getTime(), weekStart.getTime()));
                    const overlapEnd = new Date(Math.min(taskEnd.getTime(), weekEnd.getTime()));

                    let workDays = 0;
                    let currentDay = new Date(overlapStart);
                    while (currentDay <= overlapEnd) {
                        const dayOfWeek = currentDay.getDay(); // 0 = Sunday, 6 = Saturday
                        if (dayOfWeek >= 1 && dayOfWeek <= 5) { // Monday to Friday
                            workDays++;
                        }
                        currentDay.setDate(currentDay.getDate() + 1);
                    }
                    totalDaysInWeek += workDays;
                }
            });

            return { tasks: tasksInWeek, totalDays: totalDaysInWeek };
        });

        return {
            role,
            member,
            weeklyWorkload,
        };
    });

    return (
        <div style={{ overflowX: 'auto' }}>
            <p style={{color: 'var(--secondary-text)', marginBottom: '1.5rem'}}>
                View task distribution across project roles by week. Each cell shows the total days of work assigned. Colors indicate workload intensity (Green: light, Amber: medium, Red: heavy).
            </p>
            <table className="task-list-table workload-table">
                <thead>
                    <tr>
                        <th style={{ minWidth: '250px', position: 'sticky', left: 0, background: 'var(--card-background)', zIndex: 1 }}>Role (Team Member)</th>
                        {projectWeeks.map(week => (
                            <th key={week.toISOString()} style={{ minWidth: '120px', textAlign: 'center' }}>
                                Week of {week.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                            </th>
                        ))}
                    </tr>
                </thead>
                <tbody>
                    {workloadData.map(({ role, member, weeklyWorkload }) => (
                        <tr key={role} style={{cursor: 'initial'}}>
                            <td style={{ position: 'sticky', left: 0, background: 'var(--card-background)', zIndex: 1, fontWeight: 'bold' }}>
                                {role} ({member?.name || 'Unassigned'})
                            </td>
                            {weeklyWorkload.map((weekData, index) => {
                                const title = weekData.tasks.length > 0
                                    ? weekData.tasks.map(t => `- ${t.name} (${new Date(t.startDate).toLocaleDateString()} - ${new Date(t.endDate).toLocaleDateString()})`).join('\n')
                                    : 'No tasks assigned this week';
                                return (
                                    <td 
                                        key={index}
                                        title={title}
                                        style={{
                                            textAlign: 'center',
                                            backgroundColor: getWorkloadColor(weekData.totalDays),
                                            color: weekData.totalDays > 0 ? 'var(--background-color)' : 'inherit',
                                            fontWeight: 'bold',
                                            fontSize: '1.1rem'
                                        }}
                                    >
                                        {weekData.totalDays > 0 ? `${weekData.totalDays}d` : '-'}
                                    </td>
                                );
                            })}
                        </tr>
                    ))}
                </tbody>
            </table>
            <style>{`
                .workload-table th, .workload-table td {
                    border: 1px solid var(--border-color);
                }
                .workload-table td[title]:hover {
                    cursor: help;
                }
            `}</style>
        </div>
    );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Project, User } from '../types.ts';
import { parseRolesFromMarkdown } from '../utils/be-logic.ts';

interface TeamAssignmentsViewProps {
    project: Project;
    onUpdateTeam: (newTeam: any, newOwnerId?: string) => void;
    currentUser: User;
}

export const TeamAssignmentsView: React.FC<TeamAssignmentsViewProps> = ({ project, onUpdateTeam, currentUser }) => {
    const [teamAssignments, setTeamAssignments] = useState(project.team || []);

    const extractedRoles = useMemo(() => {
        const resourceDoc = project.documents.find(d => d.title === 'Resources & Skills List');
        if (!resourceDoc || !project.phasesData || !project.phasesData[resourceDoc.id]) return [];
        return parseRolesFromMarkdown(project.phasesData[resourceDoc.id].content);
    }, [project.documents, project.phasesData]);

    useEffect(() => {
        setTeamAssignments(project.team || []);
    }, [project.team]);

    const handleAssignmentChange = (role, field, value) => {
        const existingAssignmentIndex = teamAssignments.findIndex(a => a.role === role);
        let newAssignments = [...teamAssignments];
        if (existingAssignmentIndex > -1) {
            newAssignments[existingAssignmentIndex] = { ...newAssignments[existingAssignmentIndex], [field]: value };
        } else {
            newAssignments.push({ role, name: '', email: '', [field]: value, userId: `temp-${Date.now()}` });
        }
        const filteredAssignments = newAssignments.filter(a => (a.name && a.name.trim() !== '') || (a.email && a.email.trim() !== ''));
        setTeamAssignments(filteredAssignments);
        onUpdateTeam(filteredAssignments);
    };

    const handleTransferOwnership = (newOwnerId: string) => {
        if (!window.confirm("Are you sure you want to transfer ownership of this project? This action cannot be undone.")) return;

        const newTeam = project.team.map(member => {
            if (member.userId === newOwnerId) return { ...member, role: 'Project Owner' };
            if (member.userId === project.ownerId) return { ...member, role: 'Team Member' };
            return member;
        });

        onUpdateTeam(newTeam, newOwnerId);
    };

    if (extractedRoles.length === 0) {
        return (
             <div style={{ textAlign: 'center', padding: '2rem' }}>
                <p>Team roles will be populated here once the 'Resources & Skills List' document is generated and approved.</p>
             </div>
        )
    }

    return (
        <div>
             <p style={{color: 'var(--secondary-text)', marginBottom: '1.5rem'}}>Assign team members to roles. The project owner has full permissions.</p>
            <table className="task-list-table">
                <thead><tr><th>Role</th><th>Assigned To (Name)</th><th>Email</th><th>Actions</th></tr></thead>
                <tbody>
                    {extractedRoles.map(role => {
                        const assignment = teamAssignments.find(a => a.role === role) || { name: '', email: '' };
                        const member = project.team.find(m => m.role === role);
                        return (
                            <tr key={role} style={{cursor: 'initial'}}>
                                <td><strong>{role}</strong></td>
                                <td>
                                    <input type="text" value={assignment.name} onChange={(e) => handleAssignmentChange(role, 'name', e.target.value)} />
                                </td>
                                <td>
                                    <input type="email" value={assignment.email} onChange={(e) => handleAssignmentChange(role, 'email', e.target.value)} />
                                </td>
                                <td>
                                    {currentUser.id === project.ownerId && member && member.userId !== project.ownerId && (
                                        <button className="button button-small" onClick={() => handleTransferOwnership(member.userId)}>Make Owner</button>
                                    )}
                                    {member?.userId === project.ownerId && <span style={{color: 'var(--accent-color)'}}>Project Owner</span>}
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
        </div>
    );
};

