const ResourcesView = ({ project, onUpdateProject }) => {
    const [resources, setResources] = useState(project.resources || []);
    const extractedResources = useMemo(() => {
        const resourceDoc = project.documents.find(d => d.title === 'Resources & Skills List');
        if (!resourceDoc || !project.phasesData || !project.phasesData[resourceDoc.id]?.content) return [];
        return parseResourcesFromMarkdown(project.phasesData[resourceDoc.id].content);
    }, [project.documents, project.phasesData]);

    useEffect(() => {
        const projectResources = project.resources || [];
        const currentResourceNames = new Set(projectResources.map(r => r.name));
        const newResourcesToAdd = extractedResources
            .filter(name => !currentResourceNames.has(name))
            .map(name => ({ name, estimate: 0, actual: 0 }));
        if (newResourcesToAdd.length > 0) {
            onUpdateProject({ resources: [...projectResources, ...newResourcesToAdd] });
        }
    }, [extractedResources, project.resources, onUpdateProject]);

    const handleUpdate = (index, field, value) => {
        const newResources = [...resources];
        newResources[index] = { ...newResources[index], [field]: field === 'name' ? value : parseFloat(value) || 0 };
        setResources(newResources);
    };

    const handleBlur = () => onUpdateProject({ resources });

    return (
        <div className="glass-card" style={{ padding: '0', borderLeft: 'none' }}>
            <table>
                <thead><tr><th>Resource Vector</th><th>Budgeted Allocation</th><th>Actual Consumption</th></tr></thead>
                <tbody>
                    {resources.map((r, i) => (
                        <tr key={i}>
                            <td><input type="text" value={r.name} onChange={e => handleUpdate(i, 'name', e.target.value)} onBlur={handleBlur} style={{ background: 'transparent', border: 'none', padding: '0.5rem' }} /></td>
                            <td><input type="number" value={r.estimate} onChange={e => handleUpdate(i, 'estimate', e.target.value)} onBlur={handleBlur} style={{ background: 'transparent', border: 'none', padding: '0.5rem' }} /></td>
                            <td><input type="number" value={r.actual} onChange={e => handleUpdate(i, 'actual', e.target.value)} onBlur={handleBlur} style={{ background: 'transparent', border: 'none', padding: '0.5rem' }} /></td>
                        </tr>
                    ))}
                    {resources.length === 0 && <tr><td colSpan={3} style={{ textAlign: 'center', padding: '4rem', opacity: 0.5 }}>No resources defined in planning phase.</td></tr>}
                </tbody>
            </table>
        </div>
    );
};

