import React, { useState } from 'react';
import { PhaseCard } from '../components/PhaseCard.tsx';

export const ProjectPhasesView = ({ project, projectPhases, phasesData, documents, error, loadingPhase, handleUpdatePhaseData, handleCompletePhase, handleGenerateContent, handleGenerateImages, handleChatToChange, handleAttachFile, handleRemoveAttachment, generationMode, onSetGenerationMode, isAutoGenerating }) => {
    const [openPhases, setOpenPhases] = useState(() => {
        try {
            const firstTodoDoc = documents.find(d => d.status !== 'Approved');
            const defaultOpen = firstTodoDoc ? [firstTodoDoc.id] : (projectPhases.length > 0 ? [projectPhases[0].id] : []);
            const saved = localStorage.getItem(`hmap-open-phases-${project.id}`);
            return saved ? JSON.parse(saved) : defaultOpen;
        } catch (e) {
            return [];
        }
    });

    const togglePhaseOpen = (docId) => {
        const newOpenPhases = openPhases.includes(docId)
            ? openPhases.filter(id => id !== docId)
            : [...openPhases, docId];
        setOpenPhases(newOpenPhases);
        localStorage.setItem(`hmap-open-phases-${project.id}`, JSON.stringify(newOpenPhases));
    };

    const getLockStatus = (docId) => {
        const docIndex = projectPhases.findIndex(p => p.id === docId);
        if (docIndex <= 0) return { isLocked: false, lockReason: null };

        const prevDocInSequence = projectPhases[docIndex - 1];
        const prevDocData = documents.find(d => d.id === prevDocInSequence.id);
        const prevDocContent = phasesData[prevDocInSequence.id]?.content;

        // Unlocks if the previous document HAS content, even if not yet approved
        const isPrevDocSubstantiallyReady = prevDocData?.status === 'Approved' || (prevDocContent && prevDocContent.trim().length > 100);

        if (!isPrevDocSubstantiallyReady) {
            return { isLocked: true, lockReason: `Requires content generation for "${prevDocData.title}".` };
        }
        return { isLocked: false, lockReason: null };
    };

    const isPhase1Complete = documents.filter(d => d.phase === 1).every(d => d.status === 'Approved');

    return (
        <div>
            {error && <div className="status-message error" style={{marginBottom: '2rem'}}>{error}</div>}

            <p style={{ color: 'var(--neon-yellow)', fontSize: '0.9rem', marginBottom: '2rem', opacity: 0.9, lineHeight: '1.4' }}>
                Each document needs to be generated (written by Ai) and then as the planner you need to review and edit. 
                you can do this by manual edits or by telling the chat what you want to change. 
                When satisfied mark the document as complete to unlock the next document
            </p>

            {isPhase1Complete && (
                <div className="tool-card" style={{ marginBottom: '3rem' }}>
                    <h3 className="subsection-title">Generation Strategy</h3>
                    <div className="selection-group">
                        <button 
                            type="button" 
                            onClick={() => onSetGenerationMode('manual')} 
                            className={`selection-button ${generationMode === 'manual' ? 'active' : ''}`}
                            disabled={isAutoGenerating}
                        >
                            <strong>HMAP Process</strong>
                            <span>Manual control & review</span>
                        </button>
                        <button 
                            type="button" 
                            onClick={() => onSetGenerationMode('automatic')} 
                            className={`selection-button ${generationMode === 'automatic' ? 'active' : ''}`}
                            disabled={isAutoGenerating}
                        >
                            <strong>Auto Pilot</strong>
                            <span>Sequence all documents</span>
                        </button>
                    </div>
                    {isAutoGenerating && <p style={{color: 'var(--accent-color)', textAlign: 'center', marginTop: '1.5rem'}}>AI is processing documents...</p>}
                </div>
            )}

            {projectPhases.map((phase) => {
                const doc = documents.find(d => d.id === phase.id);
                if (!doc) return null;
                const { isLocked, lockReason } = getLockStatus(phase.id);
                const status = isLocked ? 'locked' : doc?.status === 'Approved' ? 'completed' : 'todo';
                const pData = phasesData[phase.id];
                return (
                    <div key={phase.id}>
                        <PhaseCard
                            phase={phase}
                            project={project}
                            phaseData={pData?.content}
                            images={pData?.images || []}
                            selectedArtifacts={pData?.selectedArtifacts || []}
                            attachments={pData?.attachments || []}
                            updatePhaseData={handleUpdatePhaseData}
                            isLocked={isLocked}
                            lockReason={lockReason}
                            onGenerate={handleGenerateContent}
                            onGenerateImages={handleGenerateImages}
                            onChatToChange={handleChatToChange}
                            onComplete={handleCompletePhase}
                            onAttachFile={handleAttachFile}
                            onRemoveAttachment={handleRemoveAttachment}
                            status={status}
                            isLoading={loadingPhase?.docId === phase.id}
                            loadingStep={loadingPhase?.docId === phase.id ? loadingPhase.step : null}
                            isOpen={openPhases.includes(phase.id)}
                            onToggleOpen={() => togglePhaseOpen(phase.id)}
                        />
                    </div>
                );
            })}
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { logAction } from '../utils/logging.ts';

const parseDeploymentPlan = (plan, allTasks, allSprints) => {
    if (!plan) return { affectedDocs: [], taskChanges: [] };

    const sections = plan.split('## ');
    const docsSection = sections.find(s => s.toLowerCase().startsWith('affected documents'));
    const tasksSection = sections.find(s => s.toLowerCase().startsWith('task modifications'));

    const affectedDocs = docsSection
        ? docsSection.split('\n').slice(1).map(line => line.replace(/[-*]\s*/, '').trim()).filter(Boolean)
        : [];

    const taskChanges = [];
    if (tasksSection) {
        const lines = tasksSection.split('\n').slice(1).filter(Boolean);
        lines.forEach(line => {
            const actionMatch = line.match(/^(ADD|DELETE|EDIT):/);
            if (!actionMatch) return;

            const action = actionMatch[1];
            const restOfLine = line.substring(actionMatch[0].length).trim();
            let target, details: any = {};

            if (action === 'DELETE') {
                target = restOfLine;
            } else { 
                const partsMatch = restOfLine.match(/(.*?)\s*\((.*)\)/);
                if (partsMatch) {
                    target = partsMatch[1].trim();
                    const detailsStr = partsMatch[2];
                    details = Object.fromEntries(
                        detailsStr.split(',').map(part => {
                            const [key, ...value] = part.split(':');
                            return [key.trim(), value.join(':').trim()];
                        })
                    );
                } else {
                    target = restOfLine;
                }
            }

            if (details['Depends On']) {
                const depTask = allTasks.find(t => t.name === details['Depends On']);
                if (depTask) details.dependsOnId = depTask.id;
            }

            if (details['Sprint']) {
                const sprint = allSprints.find(s => s.name === details['Sprint']);
                if (sprint) details.sprintId = sprint.id;
            }

            taskChanges.push({ action, target, details });
        });
    }

    return { affectedDocs, taskChanges };
};

export const ChangeDeploymentModal = ({ isOpen, onClose, deploymentPlan, project, onUpdateProject }) => {
    const [steps, setSteps] = useState([]);
    const [currentStepIndex, setCurrentStepIndex] = useState(0);

    useEffect(() => {
        if (isOpen) {
            const { affectedDocs, taskChanges } = parseDeploymentPlan(deploymentPlan, project.tasks, project.sprints);
            const docSteps = affectedDocs.map(doc => ({ type: 'document', target: doc }));
            const parsedSteps = taskChanges.map(change => ({ type: 'task', ...change }));

            const initialSteps = docSteps.length > 0
                ? [{ type: 'docs_summary', docs: docSteps.map(d => d.target) }, ...parsedSteps]
                : parsedSteps;

            setSteps(initialSteps);
            setCurrentStepIndex(0);
        }
    }, [isOpen, deploymentPlan, project.tasks]);

    const handleApply = () => {
        const step = steps[currentStepIndex];
        let updatedTasks = [...project.tasks];

        if (step.type === 'task') {
            switch (step.action) {
                case 'ADD':
                    updatedTasks.push({
                        id: `task-${Date.now()}`,
                        name: step.target,
                        startDate: step.details['Start'] || new Date().toISOString().split('T')[0],
                        endDate: step.details['End'] || new Date().toISOString().split('T')[0],
                        sprintId: step.details.sprintId || project.sprints[0]?.id,
                        status: 'todo',
                        dependsOn: step.details.dependsOnId ? [step.details.dependsOnId] : [],
                        actualTime: null,
                        actualCost: null,
                    });
                    break;
                case 'DELETE':
                    updatedTasks = updatedTasks.filter(t => t.name !== step.target);
                    break;
                case 'EDIT':
                    const taskIndex = updatedTasks.findIndex(t => t.name === step.target);
                    if (taskIndex > -1) {
                        if (step.details['End']) updatedTasks[taskIndex].endDate = step.details['End'];
                        if (step.details.sprintId) updatedTasks[taskIndex].sprintId = step.details.sprintId;
                        if (step.details.dependsOnId) {
                            if (!updatedTasks[taskIndex].dependsOn.includes(step.details.dependsOnId)) {
                                updatedTasks[taskIndex].dependsOn.push(step.details.dependsOnId);
                            }
                        }
                    }
                    break;
            }
             onUpdateProject({ tasks: updatedTasks });
        }

        logAction('Deploy Change Step', `Step ${currentStepIndex + 1}`, { step, project });

        if (currentStepIndex < steps.length - 1) {
            setCurrentStepIndex(currentStepIndex + 1);
        } else {
            onClose(); 
        }
    };

    const renderStep = () => {
        if (steps.length === 0) return <p>No actionable steps found in the deployment plan.</p>;
        const step = steps[currentStepIndex];

        if (step.type === 'docs_summary') {
            return (
                <div className="deployment-step">
                    <h4>Manual Action: Update Documents</h4>
                    <p>The following documents were identified for manual updates. Please review them after this deployment process is complete.</p>
                    <ul>{step.docs.map(d => <li key={d}>{d}</li>)}</ul>
                </div>
            );
        }

        if (step.type === 'task') {
            const actionClass = step.action.toLowerCase();
            return (
                <div className="deployment-step">
                    <h4><span className={`deployment-step-action ${actionClass}`}>{step.action}</span> Task</h4>
                    <p>You are about to <strong className={actionClass}>{step.action.toLowerCase()}</strong> the following task:</p>
                    <p className="deployment-step-target">{step.target}</p>
                    {Object.keys(step.details).length > 0 && (
                        <div className="deployment-step-details">
                            {Object.entries(step.details).map(([key, value]) => (
                                <p key={key}><strong>{key}:</strong> {value as string}</p>
                            ))}
                        </div>
                    )}
                </div>
            );
        }
        return null;
    };

    if (!isOpen) return null;

    const totalActionableSteps = steps.filter(s => s.type !== 'docs_summary').length;
    const currentActionableStep = steps.slice(0, currentStepIndex + 1).filter(s => s.type !== 'docs_summary').length;

    return (
        <div className="modal-overlay" onClick={onClose}>
            <div className="modal-content change-deployment-modal" onClick={e => e.stopPropagation()}>
                <h2>Deploying Change</h2>
                {totalActionableSteps > 0 && (
                    <p className="deployment-progress">
                        Applying Task Modifications: Step {currentActionableStep} of {totalActionableSteps}
                    </p>
                )}
                {renderStep()}
                <div className="modal-actions">
                    <button type="button" className="button" onClick={onClose}>Cancel</button>
                    <button type="button" className="button button-primary" onClick={handleApply}>
                        {currentStepIndex === steps.length - 1 ? 'Finish Deployment' : 'Apply & Next'}
                    </button>
                </div>
            </div>
        </div>
    );
};

