import React, { useRef, useState } from 'react';
import JSZip from 'jszip';
import { GoogleGenAI } from "@google/genai";
import { DocumentViewerModal } from '../components/DocumentViewerModal.tsx';
import { Document } from '../types.ts';

const getStatusChipClass = (status) => {
    switch (status) {
        case 'Approved': return 'chip-green';
        case 'Working': return 'chip-amber';
        case 'Rejected': return 'chip-red';
        case 'Failed': return 'chip-red';
        default: return '';
    }
};

// Fix: Removed ai prop as it is not utilized in this view and should be initialized locally if ever required.
export const DocumentsView = ({ project, documents, onUpdateDocument, phasesData }) => {
    const uploadInputRef = useRef<HTMLInputElement>(null);
    const [isGenerating, setIsGenerating] = useState<string | null>(null);
    const [viewingDocument, setViewingDocument] = useState<{title: string, content: string, type?: 'text' | 'image'} | null>(null);

    const handleViewDocument = (doc: Document) => {
        const content = phasesData[doc.id]?.content || 'This document has no content yet.';
        setViewingDocument({ title: doc.title, content, type: doc.type });
    };

    const handleUploadClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
        e.preventDefault();
        uploadInputRef.current?.click();
    };

    const handleDownloadAll = async () => {
        if (!documents || documents.length === 0) {
            alert("No documents to download.");
            return;
        }

        const zip = new JSZip();

        documents.forEach(doc => {
            const content = phasesData[doc.id]?.content;
            if (content) {
                const folderName = `Phase ${doc.phase}`;
                const sanitizedTitle = doc.title.replace(/[\\/:"*?<>|]/g, '');

                if (doc.type === 'image') {
                    // content is base64 data URL
                    const base64Data = content.split(',')[1];
                    zip.folder(folderName).file(`${sanitizedTitle}.png`, base64Data, { base64: true });
                } else {
                    zip.folder(folderName).file(`${sanitizedTitle}.md`, content);
                }
            }
        });

        try {
            const zipBlob = await zip.generateAsync({ type: "blob" });
            const link = document.createElement("a");
            link.href = URL.createObjectURL(zipBlob);
            link.download = `${project.name.replace(/[^a-z0-9]/gi, '_').toLowerCase()}-documents.zip`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            URL.revokeObjectURL(link.href);
        } catch (error) {
            console.error("Failed to create zip file:", error);
            alert("An error occurred while creating the zip file.");
        }
    };

    return (
        <>
            <div className="tool-card">
                <h2 className="subsection-title">Documents Center</h2>
                <div style={{display: 'flex', justifyContent: 'flex-end', gap: '1rem', marginBottom: '1.5rem', flexWrap: 'wrap'}}>
                    <button className="button" onClick={handleDownloadAll} disabled={!!isGenerating}>Download All as .zip</button>
                </div>
                <table className="document-table">
                    <thead><tr><th>Title</th><th>Type</th><th>Status</th><th>Owner</th><th>Phase</th><th>Actions</th></tr></thead>
                    <tbody>
                        {documents && documents.map(doc => (
                            <tr key={doc.id}>
                                <td>{doc.title}</td>
                                <td><span className={`chip-${doc.type === 'image' ? 'purple' : 'blue'}`}>{doc.type === 'image' ? 'Artifact' : 'Document'}</span></td>
                                <td>
                                    <select 
                                        value={doc.status} 
                                        onChange={(e) => onUpdateDocument(doc.id, e.target.value)}
                                        className={`document-status-select ${getStatusChipClass(doc.status)}`}
                                        aria-label={`Status for ${doc.title}`}
                                    >
                                        <option value="Working">Working</option>
                                        <option value="Approved">Approved</option>
                                        <option value="Rejected">Rejected</option>
                                        <option value="Failed">Failed</option>
                                    </select>
                                </td>
                                <td>{doc.owner}</td>
                                <td>{doc.phase}</td>
                                <td>
                                    <button className="button button-small" onClick={() => handleViewDocument(doc)}>View</button>
                                </td>
                            </tr>
                        ))}
                        {(!documents || documents.length === 0) && (
                            <tr><td colSpan={6} style={{textAlign: 'center'}}>No documents found for this project.</td></tr>
                        )}
                    </tbody>
                </table>
                <div className="upload-dropzone" onClick={() => uploadInputRef.current?.click()}>
                    <p>Drag & drop files to upload</p>
                    <a href="#" onClick={handleUploadClick} style={{textDecoration: 'underline', color: 'var(--accent-color)'}}>
                        Open Upload Dialogue
                    </a>
                </div>
                <input type="file" ref={uploadInputRef} style={{ display: 'none' }} multiple />
            </div>

            <DocumentViewerModal 
                isOpen={!!viewingDocument}
                onClose={() => setViewingDocument(null)}
                title={viewingDocument?.title || ''}
                content={viewingDocument?.content || ''}
                type={viewingDocument?.type}
            />
        </>
    );
};

import React, { useState } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { TEMPLATES, PROMPTS } from '../constants/projectData.ts';
import { User, Project } from '../types.ts';

// Fix: Removed manual API key management related prop types to align with local initialization strategy.
interface ProjectSetupViewProps {
    onBack: () => void;
    onCreateProject: (data: any) => void;
    currentUser: User;
}

export const ProjectSetupView: React.FC<ProjectSetupViewProps> = ({ onBack, onCreateProject, currentUser }) => {
    const [name, setName] = useState('');
    const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
    const [projectMode, setProjectMode] = useState('fullscale');
    const [projectScope, setProjectScope] = useState('internal');
    const [teamSize, setTeamSize] = useState('medium');
    const [projectComplexity, setProjectComplexity] = useState('typical');
    const [creationMode, setCreationMode] = useState('template');
    const [customDiscipline, setCustomDiscipline] = useState('');
    const [isGeneratingDocs, setIsGeneratingDocs] = useState(false);
    const [error, setError] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        if (!name.trim()) { setError("Please enter a project name."); return; }

        let template;
        if (creationMode === 'template') {
            template = TEMPLATES.find(t => t.id === selectedTemplateId);
            if (!template) { setError("Please select a template."); return; }
            onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
        } else {
            if (!customDiscipline.trim()) { setError("Please enter a custom project type."); return; }

            setIsGeneratingDocs(true);
            try {
                // Fix: Initialize AI locally right before usage as per guidelines.
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

                const prompt = PROMPTS.generateDocumentList(customDiscipline.trim(), projectScope, teamSize, projectComplexity);
                const schema = {
                    type: Type.OBJECT, 
                    properties: { 
                        documents: {
                            type: Type.ARRAY, 
                            items: { 
                                type: Type.OBJECT, 
                                properties: {
                                    title: { type: Type.STRING },
                                    phase: { type: Type.NUMBER },
                                    sequence: { type: Type.NUMBER }
                                }, 
                                required: ['title', 'phase', 'sequence']
                            }
                        }
                    }, 
                    required: ['documents']
                };

                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview', 
                    contents: prompt, 
                    config: { 
                        responseMimeType: "application/json", 
                        responseSchema: schema,
                        thinkingConfig: { thinkingBudget: 0 }
                    },
                });

                const text = response.text;
                if (!text) {
                    throw new Error("The AI returned an empty response.");
                }

                const parsedResponse = JSON.parse(text);
                if (!parsedResponse.documents || !Array.isArray(parsedResponse.documents)) {
                    throw new Error("Invalid document structure returned by AI.");
                }

                const rawDocs = parsedResponse.documents;
                const generatedDocs = rawDocs.map((doc: any, i: number) => ({
                    id: `doc-custom-${i}-${Date.now()}`, 
                    title: doc.title, 
                    version: 'v1.0', 
                    status: 'Working', 
                    owner: currentUser.username, 
                    phase: doc.phase, 
                    sequence: doc.sequence,
                }));

                template = { id: 'custom', name: 'Custom Project', discipline: customDiscipline.trim(), documents: generatedDocs };
                onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
            } catch (err: any) {
                console.error("Project Generation Error:", err);
                setError(`Failed to generate project structure: ${err.message || 'Unknown error'}`);
            } finally {
                setIsGeneratingDocs(false);
            }
        }
    };

    return (
        <div style={{ maxWidth: '1000px', margin: '0 auto', animation: 'slideUp 0.6s ease' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '2rem', marginBottom: '4rem' }}>
                <button onClick={onBack} className="button">← Back</button>
                <h1 style={{ fontSize: '3rem' }}>Set up project</h1>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '4rem', alignItems: 'start' }}>
                <form onSubmit={handleSubmit} className="glass-card" style={{ display: 'flex', flexDirection: 'column', gap: '3rem' }}>
                    <div className="form-group">
                        <label>Project Name</label>
                        <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g., Orbital Infrastructure Alpha" required />
                    </div>

                    <div className="form-group">
                        <label>Execution Mode</label>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem' }}>
                            <button type="button" className={`selection-button ${projectMode === 'fullscale' ? 'active' : ''}`} onClick={() => setProjectMode('fullscale')}>
                                <strong>Full Scale</strong>
                                <span>Complete HMAP cycle</span>
                            </button>
                            <button type="button" className={`selection-button ${projectMode === 'minimal' ? 'active' : ''}`} onClick={() => setProjectMode('minimal')}>
                                <strong>Minimal</strong>
                                <span>Rapid deployment</span>
                            </button>
                        </div>
                    </div>

                    <div className="form-group">
                        <label>Operational Scope</label>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem' }}>
                            <button type="button" className={`selection-button ${projectScope === 'internal' ? 'active' : ''}`} onClick={() => setProjectScope('internal')}>
                                <strong>Internal</strong>
