import { GoogleGenAI } from "@google/genai";
import { Project, Task, Document } from '../types.ts';

export async function runAgenticWorkflow(
    task: Task,
    project: Project,
    onProgress: (msg: string) => void
): Promise<{ success: boolean; output: string }> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = 'gemini-3-flash-preview';

    onProgress("Gathering context for task: " + task.name);

    // RAG: Collect relevant context from existing project docs
    const docContext = project.documents
        .map(d => `${d.title}:\n${project.phasesData[d.id]?.compactedContent || project.phasesData[d.id]?.content || ''}`)
        .join('\n\n');

    let currentDraft = task.description || "Initial request for task completion.";
    let iterations = 0;
    const maxIterations = 5; // Controlled iterations for responsiveness

    while (iterations < maxIterations) {
        iterations++;
        onProgress(`Iteration ${iterations}: Doer Agent is processing...`);

        // 1. Doer Agent
        const doerPrompt = `
            AGENT ROLE: DOER/CONTROLLER
            TASK: ${task.name}
            ROLE: ${task.role}
            CURRENT DRAFT: ${currentDraft}
            PROJECT CONTEXT: ${docContext}

            OBJECTIVE: Produce a high-quality, professional deliverable for this specific task. 
            If a draft exists, improve it based on feedback. If not, create it.
            Output ONLY the deliverable content.
        `;

        const doerRes = await ai.models.generateContent({
            model,
            contents: doerPrompt,
            config: { thinkingConfig: { thinkingBudget: 0 } }
        });
        currentDraft = doerRes.text || currentDraft;

        // 2. Tools/Context Agent (Simulated RAG refinement)
        onProgress(`Iteration ${iterations}: Tools Agent is verifying context...`);
        const toolsPrompt = `
            AGENT ROLE: TOOLS/RAG
            CONTENT: ${currentDraft}
            PROJECT DATA: ${docContext}

            OBJECTIVE: Identify any missing technical details or inconsistencies with the broader project plan.
            Provide specific suggestions to align this task with approved project goals.
        `;
        const toolsRes = await ai.models.generateContent({
            model,
            contents: toolsPrompt,
            config: { thinkingConfig: { thinkingBudget: 0 } }
        });

        // 3. Tester Agent
        onProgress(`Iteration ${iterations}: Tester Agent is validating quality...`);
        const testerPrompt = `
            AGENT ROLE: TESTER/QA
            CONTENT TO TEST: ${currentDraft}
            FEEDBACK FROM TOOLS: ${toolsRes.text}

            OBJECTIVE: Evaluate if the content is complete and professional.
            If perfect, respond EXACTLY with the word "COMPLETE".
            If not, provide specific improvement requirements.
        `;
        const testerRes = await ai.models.generateContent({
            model,
            contents: testerPrompt,
            config: { thinkingConfig: { thinkingBudget: 0 } }
        });

        if (testerRes.text?.trim().toUpperCase().includes("COMPLETE")) {
            onProgress("Task validated by QA Agent.");
            break;
        } else {
            // Re-feed feedback into next iteration
            currentDraft = `Feedback: ${testerRes.text}\n\nDraft: ${currentDraft}`;
        }
    }

    return { success: true, output: currentDraft };
}

import { GoogleGenAI } from "@google/genai";
import { Project, Document } from '../types.ts';

export async function runRevisionAgenticWorkflow(
    changeRequest: any,
    project: Project,
    onProgress: (msg: string) => void,
    onDocumentUpdate: (docId: string, newContent: string) => void
): Promise<boolean> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = 'gemini-3-flash-preview';

    onProgress("Change Agent is analyzing document impact...");

    // 1. Change Agent: Identify affected docs
    const analysisPrompt = `
        AGENT ROLE: CHANGE ANALYST
        CHANGE REQUEST: ${changeRequest.title} - ${changeRequest.reason}
        PROJECT DOCUMENTS: ${project.documents.map(d => d.title).join(', ')}

        OBJECTIVE: List the IDs of documents that MUST be updated to reflect this change.
        Return ONLY a comma-separated list of document titles.
    `;

    const analysisRes = await ai.models.generateContent({
        model,
        contents: analysisPrompt,
        config: { thinkingConfig: { thinkingBudget: 0 } }
    });

    const affectedTitles = (analysisRes.text || "").split(',').map(t => t.trim().toLowerCase());
    const affectedDocs = project.documents.filter(d => 
        affectedTitles.some(at => d.title.toLowerCase().includes(at))
    );

    for (const doc of affectedDocs) {
        onProgress(`Revision Agent is updating: ${doc.title}...`);

        // 2. Revision Agent
        const revisionPrompt = `
            AGENT ROLE: REVISION TOOL
            DOCUMENT: ${doc.title}
            CURRENT CONTENT: ${project.phasesData[doc.id]?.content || ''}
            CHANGE REQUEST: ${changeRequest.title} - ${changeRequest.reason}
            IMPACT: ${changeRequest.impactStr}

            OBJECTIVE: Update the document content to incorporate the change request while maintaining consistency.
            Provide the FULL updated document.
        `;

        const revisionRes = await ai.models.generateContent({
            model,
            contents: revisionPrompt,
            config: { thinkingConfig: { thinkingBudget: 0 } }
        });

        if (revisionRes.text) {
            // 3. QA Agent
            onProgress(`QA Agent is validating revision for: ${doc.title}...`);
            const qaPrompt = `
                AGENT ROLE: QA
                ORIGINAL: ${project.phasesData[doc.id]?.content || ''}
                REVISED: ${revisionRes.text}
                CHANGE REQ: ${changeRequest.reason}

                OBJECTIVE: Ensure the revision accurately reflects the change without introducing errors.
                Respond with "PASS" if okay, or provide corrections.
            `;
            const qaRes = await ai.models.generateContent({
                model,
                contents: qaPrompt,
                config: { thinkingConfig: { thinkingBudget: 0 } }
            });

            const finalContent = qaRes.text?.includes("PASS") ? revisionRes.text : (qaRes.text || revisionRes.text);
            onDocumentUpdate(doc.id, finalContent);
        }
    }

    onProgress("Global document revision sequence complete.");
    return true;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Project, Task, Milestone, Sprint } from '../types.ts';
import { parseMarkdownTable } from './be-logic.ts';

export class TrackingDataAgentWorkflow {
    static async execute(
        project: Project,
        onProgress: (msg: string) => void
    ): Promise<{ tasks: Task[]; milestones: Milestone[] }> {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const model = 'gemini-3-flash-preview';

        onProgress("Planner Agent: Analyzing project scope...");
        const wbsDoc = project.documents.find(d => d.title.includes("Detailed Plans") || d.title.includes("WBS"));
        const context = project.phasesData[wbsDoc?.id || '']?.content || "";

        // 1. Planner & Doer: Extraction
        onProgress("Doer Agent: Extracting structured tasks...");
        const doerPrompt = `
            AGENT ROLE: DOER
            CONTEXT: ${context}
            PROJECT: ${project.name}

            OBJECTIVE: Generate a Markdown task table.
            Columns: "Task Name", "Role", "Start Date (YYYY-MM-DD)", "End Date (YYYY-MM-DD)", "Dependencies", "Sprint".
            Ensure every WBS item is converted. Sprints should be 10-day increments.
        `;
        const doerRes = await ai.models.generateContent({ model, contents: doerPrompt });

        // 2. Scheduling & Costing
        onProgress("Scheduling Agent: Resolving dependencies and costs...");
        const schedulingPrompt = `
            AGENT ROLE: SCHEDULING & COSTING
            TABLE: ${doerRes.text}
            LABOR RATE: ${project.avgBurdenedLaborRate}

            OBJECTIVE: Validate dates. Ensure no task starts before dependencies. 
            Calculate an "Actual Cost" column based on duration (8h/day * rate).
            Identify physical assets needed (Software, Hardware) and estimate costs.
            Return ONLY the updated Markdown tables for Tasks and Milestones.
        `;
        const schedRes = await ai.models.generateContent({ model, contents: schedulingPrompt });

        // 3. QA & Recovery
        onProgress("QA Agent: Balancing workload and recovering data...");
        const qaPrompt = `
            AGENT ROLE: QUALITY ASSURANCE
            CONTENT: ${schedRes.text}

            OBJECTIVE: 
            1. Recover any missing dates using logic.
            2. Balance workload (max 40h/week/role).
            3. Ensure "Project Start" and "Project Completion" milestones exist.
            Return a final, perfect Markdown plan.
        `;
        const finalRes = await ai.models.generateContent({ model, contents: qaPrompt });

        const finalPlan = finalRes.text || "";
        const tasksSection = finalPlan.split('## Tasks')[1]?.split('## Milestones')[0] || "";
        const milestonesSection = finalPlan.split('## Milestones')[1] || "";

        const parsedTasks = parseMarkdownTable(tasksSection);
        const parsedMilestones = parseMarkdownTable(milestonesSection);

        const taskMap = new Map();
        const tasks: Task[] = parsedTasks.map((t, i) => {
            const id = `task-${Date.now()}-${i}`;
            taskMap.set(t.task_name?.toLowerCase().trim(), id);
            return {
                id,
                name: t.task_name || "Untitled Task",
                role: t.role || "General Resource",
                startDate: t.start_date_yyyy_mm_dd || project.startDate,
                endDate: t.end_date_yyyy_mm_dd || project.endDate,
                status: 'todo' as const,
                sprintId: 'sprint1',
                dependsOn: t.dependencies ? t.dependencies.split(',').map(d => d.trim()) : [],
                isSubcontracted: false,
                comments: [],
                attachments: [],
                actualTime: null,
                actualCost: t.actual_cost ? parseFloat(t.actual_cost.replace(/[^0-9.]/g, '')) : null,
                actualEndDate: null
            };
        });

        // Resolve string dependencies to IDs
        tasks.forEach(t => {
            t.dependsOn = (t.dependsOn as string[]).map(d => taskMap.get(d.toLowerCase())).filter(Boolean);
        });

        const milestones: Milestone[] = parsedMilestones.map((m, i) => ({
            id: `milestone-${Date.now()}-${i}`,
            name: m.milestone_name || m.name || "Untitled Milestone",
            plannedDate: m.date_yyyy_mm_dd || m.date || project.endDate,
            status: 'Planned' as const
        }));

        return { tasks, milestones };
    }
}

