import React, { useMemo } from 'react';
import { Project, User, Task } from '../types.ts';

interface MyWorkViewProps {
    projects: Project[];
    currentUser: User;
    onSelectTask: (project: Project, task: Task) => void;
}

interface AssignedTask extends Task {
    projectName: string;
    projectId: string;
}

export const MyWorkView: React.FC<MyWorkViewProps> = ({ projects, currentUser, onSelectTask }) => {
    const myTasks = useMemo<AssignedTask[]>(() => {
        if (!projects || !currentUser) return [];

        const allAssignedTasks: AssignedTask[] = [];

        projects.forEach(project => {
            const userInProject = project.team?.find(member => member.userId === currentUser.id);
            if (userInProject) {
                const userRoles = project.team
                    .filter(member => member.userId === currentUser.id)
                    .map(member => member.role);

                if (userRoles.length > 0) {
                    const tasksForUser = project.tasks?.filter(task => 
                        task.status !== 'done' && task.role && userRoles.includes(task.role)
                    );

                    if (tasksForUser) {
                        tasksForUser.forEach(task => {
                            allAssignedTasks.push({
                                ...task,
                                projectName: project.name,
                                projectId: project.id,
                            });
                        });
                    }
                }
            }
        });

        return allAssignedTasks.sort((a, b) => new Date(a.endDate).getTime() - new Date(b.endDate).getTime());
    }, [projects, currentUser]);

    const handleTaskClick = (task: AssignedTask) => {
        const project = projects.find(p => p.id === task.projectId);
        if (project) {
            onSelectTask(project, task);
        }
    };

    if (myTasks.length === 0) {
        return null;
    }

    return (
        <section className="tool-card">
            <h2 className="subsection-title">My Work</h2>
            <p style={{ color: 'var(--secondary-text)', marginTop: '-1rem', marginBottom: '1.5rem' }}>
                All tasks assigned to you across all projects, sorted by due date.
            </p>
            <table className="task-list-table">
                <thead>
                    <tr>
                        <th>Task Name</th>
                        <th>Project</th>
                        <th>Status</th>
                        <th>Due Date</th>
                    </tr>
                </thead>
                <tbody>
                    {myTasks.map(task => {
                         const isOverdue = new Date(task.endDate) < new Date();
                         return (
                            <tr key={task.id} onClick={() => handleTaskClick(task)} className={isOverdue ? 'task-row-overdue' : ''} style={{cursor: 'pointer'}}>
                                <td>{task.name}</td>
                                <td>{task.projectName}</td>
                                <td>{task.status}</td>
                                <td>{task.endDate}</td>
                            </tr>
                         );
                    })}
                </tbody>
            </table>
        </section>
    );
};

import React from 'react';
import { Project } from '../types.ts';

interface RecentlyViewedProps {
    projects: Project[];
    onSelectProject: (project: Project) => void;
    disabled: boolean;
    onRequestDelete: (project: Project) => void;
}

export const RecentlyViewed: React.FC<RecentlyViewedProps> = ({ projects, onSelectProject, disabled, onRequestDelete }) => {
    if (!projects || projects.length === 0) {
        return null;
    }

    const handleSelect = (project: Project) => {
        if (disabled) {
            alert('Please provide an API Key before opening a project.');
            return;
        }
        onSelectProject(project);
    };

    const handleDelete = (e, project) => {
        e.stopPropagation();
        if (disabled) return;
        onRequestDelete(project);
    };

    return (
        <section>
            <h2 className="subsection-title">Recently Viewed</h2>
            <div className="project-grid">
                {projects.map((p) => (
                    <div key={p.id} className="project-card-container">
                        <div
                            className="project-card"
                            onClick={() => handleSelect(p)}
                            role="button"
                            tabIndex={disabled ? -1 : 0}
                            onKeyDown={(e) => (e.key === 'Enter' || e.key === ' ') && handleSelect(p)}
                            aria-disabled={disabled}
                        >
                            <h3>{p.name}</h3>
                            <p>{p.discipline}</p>
                        </div>
                        <button 
                          className="button button-danger button-small delete-project-button"
                          onClick={(e) => handleDelete(e, p)}
                          disabled={disabled}
                          aria-label={`Delete project ${p.name}`}
                        >
                          Delete
                        </button>
                    </div>
                ))}
            </div>
        </section>
    );
};

import { User } from '../types.ts';

const USERS_KEY = 'hmap-users';
const SESSION_KEY = 'hmap-session';

const getUsers = (): User[] => {
    try {
        const users = localStorage.getItem(USERS_KEY);
        return users ? JSON.parse(users) : [];
    } catch (error) {
        console.error("Error parsing users from localStorage", error);
        return [];
    }
};

const saveUsers = (users: User[]) => {
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
};

export const register = (username, email, password): User | null => {
    const users = getUsers();
    if (users.some(u => u.username === username || u.email === email)) {
        return null; // User already exists
    }
    const newUser: User = { 
        id: `user-${Date.now()}`, 
        username, 
        email, 
        password,
        notificationPrefs: {
            teams: false,
            slack: false,
            outlook: false,
            gmail: false
        }
    };
    saveUsers([...users, newUser]);
    return newUser;
};

export const login = (email, password): User | null => {
    const users = getUsers();
    const user = users.find(u => u.email === email && u.password === password);
    if (user) {
        // Persist the full user object to the session
        localStorage.setItem(SESSION_KEY, JSON.stringify(user));
        return user;
    }
    return null;
};

export const updateUser = (updatedUser: User) => {
    const users = getUsers();
    const updatedUsers = users.map(u => u.id === updatedUser.id ? updatedUser : u);
    saveUsers(updatedUsers);

    // Also update active session if it's the same user
    const session = getCurrentUser();
    if (session && session.id === updatedUser.id) {
        localStorage.setItem(SESSION_KEY, JSON.stringify(updatedUser));
    }
};

export const logout = () => {
    localStorage.removeItem(SESSION_KEY);
};

export const getCurrentUser = (): User | null => {
    try {
        const session = localStorage.getItem(SESSION_KEY);
        if (session) {
            return JSON.parse(session);
        }
        // For first-time run, create a default user
        if (getUsers().length === 0) {
            const defaultUser = register('A. User', 'user@example.com', 'password123');
            if(defaultUser) {
                 return login(defaultUser.email, 'password123');
            }
        }
        return null;
    } catch (error) {
        console.error("Error parsing current user from localStorage", error);
        return null;
    }
};

