  :root {
    --bg-deep: #0f172a;
    --bg-surface: #1e293b;
    --primary-text: #f8fafc;
    --secondary-text: #94a3b8;

    --accent-primary: #3b82f6; /* Blue */
    --accent-secondary: #8b5cf6; /* Violet */
    --accent-tertiary: #10b981; /* Emerald */
    --accent-glow: rgba(59, 130, 246, 0.5);

    --card-bg: rgba(30, 41, 59, 0.7);
    --card-border: rgba(255, 255, 255, 0.1);

    --success-color: #10b981;
    --error-color: #ef4444;
    --warning-color: #f59e0b;
    --info-color: #0ea5e9;

    --header-height: 80px;
    --radius: 16px;
    --radius-sm: 8px;

    --glass-heavy: rgba(15, 23, 42, 0.85);
    --glass-light: rgba(255, 255, 255, 0.05);
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  html { font-size: 14px; }

  html, body {
    height: 100%;
    background-color: var(--bg-deep);
    color: var(--primary-text);
    font-family: 'Space Grotesk', system-ui, -apple-system, sans-serif;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
  }

  /* Animated Deep Space Background */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: 
      radial-gradient(circle at 15% 50%, rgba(59, 130, 246, 0.08) 0%, transparent 50%),
      radial-gradient(circle at 85% 30%, rgba(139, 92, 246, 0.08) 0%, transparent 50%),
      linear-gradient(to bottom, #0f172a 0%, #1e293b 100%);
    z-index: -1;
    pointer-events: none;
  }

  main {
    padding: 2rem 5%;
    flex: 1;
    display: flex;
    flex-direction: column;
    max-width: 1600px;
    margin: 0 auto;
    width: 100%;
    animation: fadeIn 0.6s ease-out;
  }

  @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

  header { 
    background: var(--glass-heavy);
    backdrop-filter: blur(16px);
    border-bottom: 1px solid var(--card-border);
    position: sticky;
    top: 0;
    z-index: 500;
    height: var(--header-height);
    display: flex;
    align-items: center;
    padding: 0 5%;
    box-shadow: 0 4px 20px rgba(0,0,0,0.2);
  }

  h1, h2, h3, h4, h5, h6 {
    color: #fff;
    font-weight: 700;
    letter-spacing: -0.02em;
    line-height: 1.2;
  }

  .gradient-text {
    background: linear-gradient(135deg, #60a5fa, #c084fc);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }

  /* Buttons */
  .button {
    padding: 0.8rem 1.6rem;
    border: 1px solid var(--card-border);
    background: var(--glass-light);
    color: var(--primary-text);
    border-radius: var(--radius-sm);
    cursor: pointer;
    font-weight: 600;
    font-size: 0.95rem;
    transition: all 0.2s ease;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.8rem;
    backdrop-filter: blur(4px);
  }

  .button:hover:not([disabled]) { 
    background: rgba(255, 255, 255, 0.1);
    border-color: var(--primary-text);
    transform: translateY(-1px);
  }

  .button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }

  .button-primary { 
    background: linear-gradient(135deg, var(--accent-primary), var(--accent-secondary));
    border: none;
    box-shadow: 0 4px 15px rgba(59, 130, 246, 0.3);
  }

  .button-primary:hover:not([disabled]) {
    box-shadow: 0 6px 20px rgba(139, 92, 246, 0.4);
  }

  .button-danger {
    background: rgba(239, 68, 68, 0.2);
    border-color: rgba(239, 68, 68, 0.5);
    color: #fca5a5;
  }
  .button-danger:hover { background: rgba(239, 68, 68, 0.3); }

  /* Inputs */
  input[type="text"], input[type="password"], input[type="email"], textarea, select {
    width: 100%;
    padding: 1rem 1.2rem;
    background: rgba(15, 23, 42, 0.6);
    border: 1px solid var(--card-border);
    border-radius: var(--radius-sm);
    color: var(--primary-text);
    font-family: inherit;
    font-size: 1rem;
    transition: border-color 0.2s;
  }

  input:focus, textarea:focus, select:focus {
    outline: none;
    border-color: var(--accent-primary);
    box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
  }

  /* Cards */
  .glass-card, .tool-card {
    background: var(--card-bg);
    backdrop-filter: blur(12px);
    border: 1px solid var(--card-border);
    border-radius: var(--radius);
    padding: 2rem;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
  }

  /* Info Banner */
  .info-banner {
    background: linear-gradient(to right, rgba(16, 185, 129, 0.1), transparent);
    border-left: 4px solid var(--accent-tertiary);
    padding: 1.5rem;
    border-radius: 4px;
    margin-bottom: 2rem;
  }
  .info-banner h4 { color: var(--accent-tertiary); margin-bottom: 0.5rem; }
  .info-banner p { font-size: 0.95rem; color: var(--secondary-text); margin: 0; }

  /* Feature Grid (Landing Page) */
  .feature-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 2rem;
    margin-top: 4rem;
  }

  .feature-card {
    background: rgba(30, 41, 59, 0.4);
    border: 1px solid var(--card-border);
    padding: 2rem;
    border-radius: var(--radius);
    transition: transform 0.3s ease, background 0.3s ease;
  }

  .feature-card:hover {
    transform: translateY(-5px);
    background: rgba(30, 41, 59, 0.6);
    border-color: var(--accent-secondary);
  }

  /* Navigation Tabs */
  .dashboard-nav {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 2rem;
    border-bottom: 1px solid var(--card-border);
    padding-bottom: 1rem;
    overflow-x: auto;
  }

  .dashboard-nav button {
    background: transparent;
    border: none;
    color: var(--secondary-text);
    padding: 0.8rem 1.5rem;
    border-radius: var(--radius-sm);
    cursor: pointer;
    font-weight: 600;
    transition: all 0.2s;
  }

  .dashboard-nav button:hover {
    color: var(--primary-text);
    background: rgba(255,255,255,0.03);
  }

  .dashboard-nav button.active {
    color: #fff;
    background: var(--accent-primary);
    box-shadow: 0 4px 12px rgba(59, 130, 246, 0.3);
  }

  /* Selection Buttons (Setup View) */
  .selection-button {
    background: rgba(30, 41, 59, 0.5);
    border: 1px solid var(--card-border);
    padding: 1.5rem;
    border-radius: var(--radius-sm);
    cursor: pointer;
    text-align: left;
    transition: all 0.2s;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
  }
  .selection-button strong { color: var(--primary-text); display: block; font-size: 1.1rem; }
  .selection-button span { color: var(--secondary-text); font-size: 0.9rem; }

  .selection-button:hover {
    border-color: var(--accent-primary);
    background: rgba(30, 41, 59, 0.8);
  }

  .selection-button.active {
    background: rgba(59, 130, 246, 0.1);
