import React, { useState } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { TEMPLATES, PROMPTS } from '../constants/projectData.ts';
import { User, Project } from '../types.ts';

interface ProjectSetupViewProps {
    onBack: () => void;
    onCreateProject: (data: any) => void;
    currentUser: User;
}

export const ProjectSetupView: React.FC<ProjectSetupViewProps> = ({ onBack, onCreateProject, currentUser }) => {
    const [name, setName] = useState('');
    const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
    const [projectMode, setProjectMode] = useState('fullscale');
    const [projectScope, setProjectScope] = useState('internal');
    const [teamSize, setTeamSize] = useState('medium');
    const [projectComplexity, setProjectComplexity] = useState('typical');
    const [creationMode, setCreationMode] = useState('template');
    const [customDiscipline, setCustomDiscipline] = useState('');
    const [isGeneratingDocs, setIsGeneratingDocs] = useState(false);
    const [error, setError] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        if (!name.trim()) { setError("Please enter a project name."); return; }

        let template;
        if (creationMode === 'template') {
            template = TEMPLATES.find(t => t.id === selectedTemplateId);
            if (!template) { setError("Please select a template."); return; }
            onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
        } else {
            if (!customDiscipline.trim()) { setError("Please enter a custom project type."); return; }

            setIsGeneratingDocs(true);
            try {
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

                const prompt = PROMPTS.generateDocumentList(customDiscipline.trim(), projectScope, teamSize, projectComplexity);
                const schema = {
                    type: Type.OBJECT, 
                    properties: { 
                        documents: {
                            type: Type.ARRAY, 
                            items: { 
                                type: Type.OBJECT, 
                                properties: {
                                    title: { type: Type.STRING },
                                    phase: { type: Type.NUMBER },
                                    sequence: { type: Type.NUMBER }
                                }, 
                                required: ['title', 'phase', 'sequence']
                            }
                        }
                    }, 
                    required: ['documents']
                };

                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview', 
                    contents: prompt, 
                    config: { 
                        responseMimeType: "application/json", 
                        responseSchema: schema,
                        thinkingConfig: { thinkingBudget: 0 }
                    },
                });

                const text = response.text;
                if (!text) throw new Error("The AI returned an empty response.");

                const parsedResponse = JSON.parse(text);
                const rawDocs = parsedResponse.documents;
                const generatedDocs = rawDocs.map((doc: any, i: number) => ({
                    id: `doc-custom-${i}-${Date.now()}`, 
                    title: doc.title, 
                    version: 'v1.0', 
                    status: 'Working', 
                    owner: currentUser.username, 
                    phase: doc.phase, 
                    sequence: doc.sequence,
                }));

                template = { id: 'custom', name: 'Custom Project', discipline: customDiscipline.trim(), documents: generatedDocs };
                onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
            } catch (err: any) {
                console.error("Project Generation Error:", err);
                setError(`Failed to generate project structure: ${err.message || 'Unknown error'}`);
            } finally {
                setIsGeneratingDocs(false);
            }
        }
    };

    return (
        <div style={{ maxWidth: '1200px', margin: '0 auto', animation: 'fadeIn 0.6s ease-out' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem', marginBottom: '3rem', borderBottom: '1px solid var(--card-border)', paddingBottom: '1.5rem' }}>
                <button onClick={onBack} className="button">← Back</button>
                <div>
                    <h1 style={{ fontSize: '2.5rem', marginBottom: '0.5rem' }}>Initialize New Mission</h1>
                    <p style={{ color: 'var(--secondary-text)' }}>Configure parameters for the HMAP automated planning system.</p>
                </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '3rem', alignItems: 'start' }}>
                <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '2.5rem' }}>

                    {/* Step 1: Identity */}
                    <div className="glass-card">
                        <h3 style={{ marginBottom: '1.5rem', color: 'var(--accent-primary)' }}>1. Mission Identity</h3>
                        <div className="form-group">
                            <label style={{ display: 'block', marginBottom: '0.8rem', fontWeight: 600 }}>Project Name</label>
                            <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g., Orbital Infrastructure Alpha" required style={{ fontSize: '1.2rem', padding: '1.2rem' }}/>
                        </div>
                    </div>

                    {/* Step 2: Configuration */}
                    <div className="glass-card">
                        <h3 style={{ marginBottom: '1.5rem', color: 'var(--accent-secondary)' }}>2. Execution Parameters</h3>

                        <div style={{ display: 'grid', gap: '2rem' }}>
                            <div>
                                <label style={{ display: 'block', marginBottom: '0.8rem', fontWeight: 600 }}>Execution Mode</label>
                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                                    <button type="button" className={`selection-button ${projectMode === 'fullscale' ? 'active' : ''}`} onClick={() => setProjectMode('fullscale')}>
                                        <strong>Full Scale (Standard)</strong>
                                        <span>Complete 9-phase HMAP cycle with rigorous documentation. Best for critical projects.</span>
                                    </button>
                                    <button type="button" className={`selection-button ${projectMode === 'minimal' ? 'active' : ''}`} onClick={() => setProjectMode('minimal')}>
                                        <strong>Minimal (Rapid)</strong>
                                        <span>Compressed workflow focusing only on essential deliverables. Best for prototypes.</span>
                                    </button>
                                </div>
                            </div>

                            <div>
                                <label style={{ display: 'block', marginBottom: '0.8rem', fontWeight: 600 }}>Operational Scope</label>
                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                                    <button type="button" className={`selection-button ${projectScope === 'internal' ? 'active' : ''}`} onClick={() => setProjectScope('internal')}>
                                        <strong>Internal Execution</strong>
                                        <span>Managed and delivered by your core team.</span>
                                    </button>
                                    <button type="button" className={`selection-button ${projectScope === 'subcontracted' ? 'active' : ''}`} onClick={() => setProjectScope('subcontracted')}>
                                        <strong>Subcontracted</strong>
                                        <span>Adds RFP, Contracts, and Vendor Management docs to the workflow.</span>
                                    </button>
                                </div>
                            </div>

                            <div>
                                <label style={{ display: 'block', marginBottom: '0.8rem', fontWeight: 600 }}>Team & Complexity Scale</label>
                                <div style={{ display: 'flex', gap: '1rem' }}>
                                    <select value={teamSize} onChange={(e) => setTeamSize(e.target.value)} style={{ flex: 1 }}>
                                        <option value="small">Small Team (1-3)</option>
                                        <option value="medium">Medium Team (4-15)</option>
                                        <option value="large">Large Team (16+)</option>
                                    </select>
                                    <select value={projectComplexity} onChange={(e) => setProjectComplexity(e.target.value)} style={{ flex: 1 }}>
                                        <option value="easy">Low Complexity</option>
                                        <option value="typical">Typical Complexity</option>
                                        <option value="complex">High Complexity</option>
                                    </select>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Step 3: Domain Logic */}
                    <div className="glass-card">
                        <h3 style={{ marginBottom: '1.5rem', color: 'var(--accent-tertiary)' }}>3. Domain Logic</h3>
                        <div style={{ display: 'flex', gap: '1rem', marginBottom: '1.5rem' }}>
                            <button type="button" className={`button ${creationMode === 'template' ? 'button-primary' : ''}`} onClick={() => setCreationMode('template')} style={{ flex: 1 }}>Use Proven Template</button>
                            <button type="button" className={`button ${creationMode === 'custom' ? 'button-primary' : ''}`} onClick={() => setCreationMode('custom')} style={{ flex: 1 }}>Generate Custom Logic</button>
                        </div>

                        {creationMode === 'template' ? (
                            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: '1rem', maxHeight: '400px', overflowY: 'auto', paddingRight: '0.5rem' }}>
                                {TEMPLATES.map(t => (
                                    <button key={t.id} type="button" className={`selection-button ${selectedTemplateId === t.id ? 'active' : ''}`} onClick={() => setSelectedTemplateId(t.id)}>
                                        <strong>{t.name}</strong>
                                        <span>{t.discipline}</span>
                                    </button>
                                ))}
                            </div>
                        ) : (
                            <div>
                                <label style={{ display: 'block', marginBottom: '0.8rem' }}>Describe Project Field/Discipline</label>
                                <input type="text" value={customDiscipline} onChange={(e) => setCustomDiscipline(e.target.value)} placeholder="e.g., Deep Sea Mining Protocol, AI Ethics Research..." />
                                <p style={{ fontSize: '0.9rem', color: 'var(--secondary-text)', marginTop: '0.5rem' }}>The AI will infer the necessary documentation structure based on this description.</p>
                            </div>
                        )}
                    </div>

                    {error && <div className="info-banner" style={{ borderLeftColor: 'var(--error-color)', background: 'rgba(239,68,68,0.1)' }}><h4 style={{ color: 'var(--error-color)' }}>Error</h4><p>{error}</p></div>}

                    <button type="submit" className="button button-primary" disabled={isGeneratingDocs} style={{ width: '100%', padding: '1.5rem', fontSize: '1.2rem' }}>
                        {isGeneratingDocs ? <span className="spinner"></span> : 'INITIALIZE WORKSPACE'}
                    </button>
                </form>

                {/* Sidebar Info */}
                <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', position: 'sticky', top: '100px' }}>
                    <div className="glass-card" style={{ borderLeft: '4px solid var(--accent-primary)' }}>
                        <h4 style={{ marginBottom: '0.5rem' }}>HMAP Logic</h4>
                        <p style={{ fontSize: '0.9rem', color: 'var(--secondary-text)' }}>
                            The <strong>Hyper-Agile Management Process</strong> divides projects into 9 phases. 
                            Your choices here configure the "Generative Seed" that the AI uses to draft your documents.
                        </p>
                    </div>
                    <div className="glass-card" style={{ borderLeft: '4px solid var(--warning-color)' }}>
                        <h4 style={{ marginBottom: '0.5rem' }}>Token Usage</h4>
                        <p style={{ fontSize: '0.9rem', color: 'var(--secondary-text)' }}>
                            Generating a custom project structure requires a complex AI query. Please allow 5-10 seconds for the neural architecture to form.
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

