import { GoogleGenAI, Type } from "@google/genai";
import { Project, Task, Milestone } from '../types.ts';
import { PROMPTS } from '../constants/projectData.ts';

// Helper to ensure valid JSON string is extracted if model adds backticks
const cleanJson = (text: string) => {
    return text.replace(/```json/g, '').replace(/```/g, '').trim();
};

export const executeTrackingDataWorkflow = async (
    project: Project,
    onProgress: (msg: string) => void
): Promise<{ tasks: Task[]; milestones: Milestone[] }> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = 'gemini-3-flash-preview';

    onProgress("Agent 1/4 (Extractor): Analyzing project documentation...");

    // Gather Context
    const wbsDoc = project.documents.find(d => 
        d.title.toLowerCase().includes("detailed plans") || 
        d.title.toLowerCase().includes("wbs")
    );
    const context = (wbsDoc && project.phasesData[wbsDoc.id]?.content) 
        ? project.phasesData[wbsDoc.id].content 
        : "No detailed plan content found.";

    if (context === "No detailed plan content found.") {
        throw new Error("Cannot generate timeline: 'Detailed Plans (WBS/WRS)' document is missing or empty.");
    }

    // STEP 1: EXTRACTION AGENT
    const extractSchema = {
        type: Type.OBJECT,
        properties: {
            tasks: {
                type: Type.ARRAY,
                items: {
                    type: Type.OBJECT,
                    properties: {
                        id: { type: Type.STRING },
                        name: { type: Type.STRING },
                        role: { type: Type.STRING },
                        duration: { type: Type.NUMBER },
                        dependencies: { type: Type.ARRAY, items: { type: Type.STRING } }
                    }
                }
            },
            milestones: {
                type: Type.ARRAY,
                items: {
                    type: Type.OBJECT,
                    properties: {
                        id: { type: Type.STRING },
                        name: { type: Type.STRING }
                    }
                }
            },
            roles: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ['tasks', 'milestones', 'roles']
    };

    const extractorRes = await ai.models.generateContent({
        model,
        contents: PROMPTS.timelineExtractor(context, project),
        config: { 
            responseMimeType: "application/json", 
            responseSchema: extractSchema,
            thinkingConfig: { thinkingBudget: 0 }
        }
    });

    let extractedData = JSON.parse(cleanJson(extractorRes.text || "{}"));

    // STEP 2: QA AGENT (JSON & LOGIC CHECK 1)
    onProgress("Agent 2/4 (QA): Validating extraction integrity...");
    const qa1Res = await ai.models.generateContent({
        model,
        contents: PROMPTS.jsonQA(JSON.stringify(extractedData), "Valid list of tasks, milestones, and roles. IDs must be unique."),
        config: { 
            responseMimeType: "application/json", 
            responseSchema: extractSchema,
            thinkingConfig: { thinkingBudget: 0 }
        }
    });
    extractedData = JSON.parse(cleanJson(qa1Res.text || "{}"));

    // STEP 3: SCHEDULER AGENT (SERIAL EXECUTION LOGIC)
    onProgress("Agent 3/4 (Scheduler): Optimizing workflow & calculating serial dates...");

    const scheduleSchema = {
        type: Type.OBJECT,
        properties: {
            tasks: {
                type: Type.ARRAY,
                items: {
                    type: Type.OBJECT,
                    properties: {
                        id: { type: Type.STRING },
                        name: { type: Type.STRING },
                        role: { type: Type.STRING },
                        startDate: { type: Type.STRING },
                        endDate: { type: Type.STRING },
                        dependencies: { type: Type.ARRAY, items: { type: Type.STRING } },
                        sprint: { type: Type.STRING }
                    }
                }
            },
            milestones: {
                type: Type.ARRAY,
                items: {
                    type: Type.OBJECT,
                    properties: {
                        id: { type: Type.STRING },
                        name: { type: Type.STRING },
                        date: { type: Type.STRING }
                    }
                }
            }
        },
        required: ['tasks', 'milestones']
    };

    const schedulerRes = await ai.models.generateContent({
        model,
        contents: PROMPTS.timelineScheduler(JSON.stringify(extractedData), project.startDate),
        config: { 
            responseMimeType: "application/json", 
            responseSchema: scheduleSchema,
            thinkingConfig: { thinkingBudget: 0 }
        }
    });

    let scheduledData = JSON.parse(cleanJson(schedulerRes.text || "{}"));

    // STEP 4: QA AGENT (FINAL VALIDATION)
    onProgress("Agent 4/4 (QA): Final validation of timeline logic...");
    const qa2Res = await ai.models.generateContent({
        model,
        contents: PROMPTS.jsonQA(JSON.stringify(scheduledData), "Valid project schedule. Task EndDate must be >= StartDate. No overlapping tasks for same role."),
        config: { 
            responseMimeType: "application/json", 
            responseSchema: scheduleSchema,
            thinkingConfig: { thinkingBudget: 0 }
        }
    });
    scheduledData = JSON.parse(cleanJson(qa2Res.text || "{}"));

    // Final Transformation to Application Types
    const finalTasks: Task[] = scheduledData.tasks.map((t: any, i: number) => ({
        id: t.id || `task-${Date.now()}-${i}`,
        name: t.name,
        role: t.role,
        startDate: t.startDate,
        endDate: t.endDate,
        status: 'todo',
        sprintId: t.sprint ? t.sprint.toLowerCase().replace(/\s/g, '') : 'sprint1',
        dependsOn: t.dependencies || [],
        isSubcontracted: false,
        comments: [],
        attachments: [],
        actualTime: null,
        actualCost: null,
        actualEndDate: null
    }));

    const finalMilestones: Milestone[] = scheduledData.milestones.map((m: any, i: number) => ({
        id: m.id || `milestone-${Date.now()}-${i}`,
        name: m.name,
        plannedDate: m.date,
        status: 'Planned'
    }));

    return { tasks: finalTasks, milestones: finalMilestones };
};

import React, { useState, useEffect, useMemo } from 'react';
import { TeamAssignmentsView } from './TeamView.tsx';
import { Project, Task, User } from '../types.ts';
import { WorkloadView } from './WorkloadView.tsx';
import { parseResourcesFromMarkdown } from '../utils/be-logic.ts';

// --- GANTT COMPONENTS ---

const GanttChart = ({ tasks, startDate, endDate }: { tasks: Task[], startDate: string, endDate: string }) => {
    const projectStart = new Date(startDate).getTime();
    const projectEnd = new Date(endDate).getTime();
    const totalDuration = projectEnd - projectStart;

    // Sort tasks by start date
    const sortedTasks = useMemo(() => [...tasks].sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime()), [tasks]);

    // Calculate Grid Columns (Weeks)
    const weeks = useMemo(() => {
        const weekArray = [];
        let current = new Date(startDate);
        const end = new Date(endDate);
        while (current <= end) {
            weekArray.push(new Date(current));
            current.setDate(current.getDate() + 7);
        }
        return weekArray;
    }, [startDate, endDate]);

    if (!tasks.length) return <p style={{padding: '2rem', textAlign: 'center', opacity: 0.6}}>No timeline data generated yet.</p>;

    return (
        <div className="gantt-container glass-card" style={{ padding: '2rem', overflowX: 'auto' }}>
            <div style={{ minWidth: '1000px' }}>
                {/* Header: Months/Weeks */}
                <div style={{ display: 'flex', borderBottom: '1px solid var(--border-color)', paddingBottom: '1rem', marginBottom: '1rem' }}>
                    <div style={{ width: '250px', flexShrink: 0, fontWeight: 'bold' }}>Task Name</div>
                    <div style={{ flexGrow: 1, position: 'relative', height: '30px' }}>
                        {weeks.map((week, i) => {
                            const left = ((week.getTime() - projectStart) / totalDuration) * 100;
                            return (
                                <div key={i} style={{ position: 'absolute', left: `${left}%`, fontSize: '0.8rem', color: 'var(--secondary-text)', transform: 'translateX(-50%)' }}>
                                    {week.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
                                </div>
                            );
                        })}
                    </div>
                </div>

                {/* Task Rows */}
                {sortedTasks.map((task) => {
                    const taskStart = new Date(task.startDate).getTime();
                    const taskEnd = new Date(task.endDate).getTime();
                    const left = Math.max(0, ((taskStart - projectStart) / totalDuration) * 100);
                    const width = Math.max(1, ((taskEnd - taskStart) / totalDuration) * 100);

                    const statusColor = task.status === 'done' ? 'var(--success-color)' : 
                                      task.status === 'inprogress' ? 'var(--accent-color)' : 
                                      task.status === 'review' ? 'var(--warning-color)' : 'var(--neon-purple)';

                    return (
                        <div key={task.id} style={{ display: 'flex', alignItems: 'center', marginBottom: '1rem', height: '40px' }}>
                            <div style={{ width: '250px', flexShrink: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', paddingRight: '1rem', fontSize: '0.9rem' }} title={task.name}>
                                {task.name}
                                <div style={{fontSize: '0.75rem', color: 'var(--secondary-text)'}}>{task.role}</div>
                            </div>
                            <div style={{ flexGrow: 1, position: 'relative', height: '100%', background: 'rgba(255,255,255,0.02)', borderRadius: '4px' }}>
                                {/* Gantt Bar */}
                                <div style={{
                                    position: 'absolute',
                                    left: `${left}%`,
                                    width: `${width}%`,
                                    height: '24px',
                                    top: '8px',
                                    backgroundColor: statusColor,
                                    borderRadius: '12px',
                                    boxShadow: `0 2px 10px ${statusColor}40`,
                                    opacity: 0.9,
                                    transition: 'all 0.3s ease',
                                    cursor: 'pointer',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center'
                                }} title={`${task.startDate} to ${task.endDate}`}>
                                    {width > 10 && <span style={{ fontSize: '0.75rem', fontWeight: 'bold', color: '#000', padding: '0 5px', whiteSpace: 'nowrap', overflow: 'hidden' }}>{task.sprintId}</span>}
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

// --- EXISTING COMPONENTS ---

const ResourcesView = ({ project, onUpdateProject }) => {
    const [resources, setResources] = useState(project.resources || []);
    const extractedResources = useMemo(() => {
        const resourceDoc = project.documents.find(d => d.title === 'Resources & Skills List');
        if (!resourceDoc || !project.phasesData || !project.phasesData[resourceDoc.id]?.content) return [];
        return parseResourcesFromMarkdown(project.phasesData[resourceDoc.id].content);
    }, [project.documents, project.phasesData]);

    useEffect(() => {
        const projectResources = project.resources || [];
        const currentResourceNames = new Set(projectResources.map(r => r.name));
        const newResourcesToAdd = extractedResources
            .filter(name => !currentResourceNames.has(name))
            .map(name => ({ name, estimate: 0, actual: 0 }));
        if (newResourcesToAdd.length > 0) {
            onUpdateProject({ resources: [...projectResources, ...newResourcesToAdd] });
        }
    }, [extractedResources, project.resources, onUpdateProject]);

    const handleUpdate = (index, field, value) => {
        const newResources = [...resources];
        newResources[index] = { ...newResources[index], [field]: field === 'name' ? value : parseFloat(value) || 0 };
        setResources(newResources);
    };

    const handleBlur = () => onUpdateProject({ resources });

    return (
        <div className="glass-card" style={{ padding: '0', borderLeft: 'none' }}>
            <table>
                <thead><tr><th>Resource Vector</th><th>Budgeted Allocation</th><th>Actual Consumption</th></tr></thead>
                <tbody>
                    {resources.map((r, i) => (
                        <tr key={i}>
                            <td><input type="text" value={r.name} onChange={e => handleUpdate(i, 'name', e.target.value)} onBlur={handleBlur} style={{ background: 'transparent', border: 'none', padding: '0.5rem' }} /></td>
                            <td><input type="number" value={r.estimate} onChange={e => handleUpdate(i, 'estimate', e.target.value)} onBlur={handleBlur} style={{ background: 'transparent', border: 'none', padding: '0.5rem' }} /></td>
                            <td><input type="number" value={r.actual} onChange={e => handleUpdate(i, 'actual', e.target.value)} onBlur={handleBlur} style={{ background: 'transparent', border: 'none', padding: '0.5rem' }} /></td>
                        </tr>
                    ))}
                    {resources.length === 0 && <tr><td colSpan={3} style={{ textAlign: 'center', padding: '4rem', opacity: 0.5 }}>No resources defined in planning phase.</td></tr>}
                </tbody>
            </table>
        </div>
    );
};

const TaskListView = ({ tasks, team, onTaskClick }) => (
    <div className="glass-card" style={{ padding: '0', borderLeft: 'none' }}>
        <table>
            <thead><tr><th>Task Identifier</th><th>Assigned Intelligence</th><th>Status</th><th>Target Date</th></tr></thead>
            <tbody>
                {tasks.map(t => (
                    <tr key={t.id} onClick={() => onTaskClick(t)} style={{cursor: 'pointer'}}>
                        <td style={{ fontWeight: 700 }}>{t.name}</td>
                        <td>{team.find(m => m.role === t.role)?.name || 'Unassigned'}</td>
                        <td><span className={`chip-${t.status === 'done' ? 'green' : t.status === 'inprogress' ? 'blue' : 'amber'}`}>{t.status}</span></td>
                        <td style={{ fontFamily: 'monospace' }}>{t.endDate}</td>
                    </tr>
                ))}
                {tasks.length === 0 && <tr><td colSpan={4} style={{ textAlign: 'center', padding: '4rem', opacity: 0.5 }}>Mission queue empty.</td></tr>}
            </tbody>
        </table>
    </div>
);

export const ProjectTrackingView: React.FC<{ project: Project; onUpdateTask: any; onUpdateMilestone: any; onUpdateTeam: any; onUpdateProject: any; onTaskClick: any; currentUser: User; }> = ({ project, onUpdateTask, onUpdateMilestone, onUpdateTeam, onUpdateProject, onTaskClick, currentUser }) => {
    const [trackingView, setTrackingView] = useState('Timeline');
    useEffect(() => {
        const saved = localStorage.getItem(`hmap-tracking-view-${project.id}`);
        if (saved) setTrackingView(saved);
    }, [project.id]);

    const handleViewChange = (view) => {
        setTrackingView(view);
        localStorage.setItem(`hmap-tracking-view-${project.id}`, view);
    };

    const viewOrder = ['Timeline', 'Task List', 'Kanban Board', 'Workload', 'Milestones', 'Team', 'Resources'];

    return (
        <div>
            <div className="dashboard-nav">
                {viewOrder.map(v => (
                    <button key={v} onClick={() => handleViewChange(v)} className={trackingView === v ? 'active' : ''}>{v}</button>
                ))}
            </div>

            <div style={{ animation: 'slideUp 0.6s cubic-bezier(0.16, 1, 0.3, 1)' }}>
                {trackingView === 'Timeline' && (
                    <GanttChart tasks={project.tasks} startDate={project.startDate} endDate={project.endDate} />
                )}
                {trackingView === 'Task List' && <TaskListView tasks={project.tasks} team={project.team} onTaskClick={onTaskClick} />}
                {trackingView === 'Resources' && <ResourcesView project={project} onUpdateProject={onUpdateProject} />}
                {trackingView === 'Team' && <div className="glass-card" style={{ padding: '3rem', borderLeft: 'none' }}><TeamAssignmentsView project={project} onUpdateTeam={onUpdateTeam} currentUser={currentUser} /></div>}
                {trackingView === 'Workload' && <div className="glass-card" style={{ borderLeft: 'none' }}><WorkloadView project={project} /></div>}
                {trackingView === 'Kanban Board' && (
                    <div className="tool-card" style={{ padding: '8rem 2rem', textAlign: 'center' }}>
                         <div style={{ fontSize: '4rem', marginBottom: '2rem', opacity: 0.2 }}>📋</div>
                        <h3 className="subsection-title">Kanban Interface Offline</h3>
                        <p style={{ color: 'var(--secondary-text)', maxWidth: '500px', margin: '0 auto' }}>Task visualization pipeline currently under maintenance.</p>
                    </div>
                )}
                {trackingView === 'Milestones' && (
                    <div className="glass-card" style={{ padding: '0', borderLeft: 'none' }}>
                        <table>
                            <thead><tr><th>Milestone Title</th><th>Target Date</th><th>Status</th></tr></thead>
                            <tbody>
                                {project.milestones.map(m => (
                                    <tr key={m.id}>
                                        <td style={{ fontWeight: 700 }}>{m.name}</td>
                                        <td style={{ fontFamily: 'monospace' }}>{m.plannedDate}</td>
                                        <td><span className={`chip-${m.status === 'Completed' ? 'green' : 'amber'}`}>{m.status}</span></td>
                                    </tr>
                                ))}
                                {project.milestones.length === 0 && <tr><td colSpan={3} style={{ textAlign: 'center', padding: '4rem', opacity: 0.5 }}>No critical milestones logged.</td></tr>}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

