async function withRetry<T>(fn: () => Promise<T>, retries = 2, delay = 1000): Promise<T> {
    let lastError: Error | any = new Error("Unknown error");
    for (let i = 0; i < retries; i++) {
        try {
            return await fn();
        } catch (error: any) {
            lastError = error;
            console.warn(`Attempt ${i + 1} failed. Retrying...`, error);
            if (error?.message?.includes("API_KEY_INVALID") || error?.message?.includes("safety")) {
                throw error;
            }
            if (i < retries - 1) {
                await new Promise(res => setTimeout(res, delay * Math.pow(2, i)));
            }
        }
    }
    throw lastError;
};

const getPromptFunction = (docTitle: string, phase: number) => {
    const title = docTitle.toLowerCase();
    if (phase === 1 && title.includes('concept proposal')) return PROMPTS.phase1;
    if (title.includes('resources & skills')) return PROMPTS.phase2;
    if (title.includes('swot') || title.includes('risk analysis')) return PROMPTS.phase3;
    if (title.includes('kickoff briefing')) return PROMPTS.phase4;
    if (title.includes('statement of work') || title.includes('sow')) return PROMPTS.phase5;
    if (title.includes('preliminary review')) return PROMPTS.phase6;
    if (title.includes('detailed plans')) return PROMPTS.phase7;

    if (phase === 8) {
        if (title.includes('sprint requirements') || title.includes('user story backlog')) return PROMPTS.phase8_sprintRequirements;
        if (title.includes('sprint plan review')) return PROMPTS.phase8_sprintPlanReview;
        if (title.includes('critical review')) return PROMPTS.phase8_criticalReview;
        return (name: string, disc: string, ctx: string, mode: any, scope: any, team: any, comp: any) => PROMPTS.phase8_generic(docTitle, name, disc, ctx, mode, scope, team, comp);
    }

    if (phase === 9) return PROMPTS.phase9;

    return (name: string, disc: string, ctx: string, mode: any, scope: any, team: any, comp: any) => PROMPTS.genericDocumentPrompt(docTitle, phase, name, disc, ctx, mode, scope, team, comp);
}

const getRelevantContext = (docToGenerate: any, allDocuments: any[], allPhasesData: any) => {
    const sortedDocuments = [...allDocuments]
        .filter(d => d.type !== 'image')
        .sort((a, b) => (a.phase - b.phase) || ((a.sequence || 0) - (b.sequence || 0)));
    const currentIndex = sortedDocuments.findIndex(d => d.id === docToGenerate.id);
    const firstDoc = sortedDocuments[0];
    const firstDocPhaseData = firstDoc ? allPhasesData[firstDoc.id] : null;
    const firstDocContext = (firstDoc && (firstDoc.status === 'Approved' || firstDoc.phase === 1) && firstDocPhaseData?.compactedContent) ? firstDocPhaseData.compactedContent : '';
    const prevDoc = currentIndex > 0 ? sortedDocuments[currentIndex - 1] : null;
    const prevDocPhaseData = prevDoc ? allPhasesData[prevDoc.id] : null;
    const prevDocContext = (prevDoc && (prevDoc.status === 'Approved' || (prevDocPhaseData?.content && prevDocPhaseData.content.length > 50)) && prevDocPhaseData?.compactedContent) ? prevDocPhaseData.compactedContent : '';
    return { firstDocContext, prevDocContext };
};

const MAX_PAYLOAD_CHARS = 25000;
const truncatePrompt = (prompt: string): string => {
    if (prompt.length <= MAX_PAYLOAD_CHARS) return prompt;
    return prompt.substring(0, MAX_PAYLOAD_CHARS) + "\n...[PROMPT TRUNCATED]...";
};

export const ProjectDashboard: React.FC<{ project: Project; onBack: () => void; saveProject: (project: Project) => void; currentUser: User; }> = ({ project, onBack, saveProject, currentUser }) => {
    const [projectData, setProjectData] = useState<Project>({ ...project });
    const [loadingPhase, setLoadingPhase] = useState<{ docId: string | null; step: string | null }>({ docId: null, step: null });
    const [error, setError] = useState('');
    const [activeTab, setActiveTab] = useState('Project Phases');
    const [isAutoGenerating, setIsAutoGenerating] = useState(false);
    const [selectedTask, setSelectedTask] = useState<Task | null>(null);
    const [aiReport, setAiReport] = useState({ title: '', content: '', isOpen: false });
    const [isGeneratingReport, setIsGeneratingReport] = useState<'risk' | 'summary' | null>(null);
    const [showBrief, setShowBrief] = useState(true);

    const isMounted = useRef(true);
    useEffect(() => {
        isMounted.current = true;
        logAction('Mount', 'ProjectDashboard', { projectId: project.id });
        window.scrollTo(0, 0);
        return () => { 
            isMounted.current = false; 
            logAction('Unmount', 'ProjectDashboard', { projectId: project.id });
        };
    }, []);

    const projectDataRef = useRef(projectData);
    useEffect(() => { projectDataRef.current = projectData; }, [projectData]);

    useEffect(() => {
        setProjectData(project);
    }, [project]);

    const projectPhases = useMemo(() => {
        return [...projectData.documents]
            .filter(d => d.type !== 'image')
            .sort((a, b) => (a.phase - b.phase) || ((a.sequence || 0) - (b.sequence || 0)))
            .map(doc => ({
                id: doc.id,
                title: doc.title,
                description: PHASES.find(p => parseInt(p.id.replace('phase', '')) === doc.phase)?.description || '',
                originalPhaseId: `phase${doc.phase}`
            }));
    }, [projectData.documents]);

    const handleSave = useCallback((update: Partial<Project> | ((prev: Project) => Partial<Project>)) => {
        if (!isMounted.current) {
            logAction('Warn', 'handleSave', { msg: 'Attempted save on unmounted component' });
            return;
        }

        const currentData = projectDataRef.current;
        const dataToMerge = typeof update === 'function' ? update(currentData) : update;
        const newState = { ...currentData, ...dataToMerge };

        setProjectData(newState);
        saveProject(newState);
    }, [saveProject]);

    const handleTabChange = useCallback((tabName: string) => {
        setActiveTab(tabName);
        localStorage.setItem(`hmap-active-tab-${project.id}`, tabName);
    }, [project.id]);

    useEffect(() => {
        const savedTab = localStorage.getItem(`hmap-active-tab-${project.id}`);
        setActiveTab(savedTab || 'Project Phases');
    }, [project.id]);

    const handleGenerateImages = useCallback(async (docId: string, artifacts: string[], textContent: string) => {
        if (artifacts.length === 0) return;
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const parentDoc = projectDataRef.current.documents.find(d => d.id === docId);
        if (!parentDoc) return;

        if (isMounted.current) setLoadingPhase({ docId, step: 'imaging' });
        try {
            const generatedImages: string[] = [];
            const artifactDocs: Document[] = [];

            for (const artifact of artifacts) {
                if (!isMounted.current) break;
                const prompt = `Professional technical ${artifact} for project "${projectDataRef.current.name}". Visual representation of: ${textContent.substring(0, 800)}. Schematic style.`;
                const result = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({
                    model: 'gemini-2.5-flash-image',
                    contents: { parts: [{ text: prompt }] },
                    config: { imageConfig: { aspectRatio: "16:9" } }
                }));
                const firstCandidate = result.candidates?.[0];
                if (!firstCandidate) continue;
                for (const part of firstCandidate.content.parts) {
                    if (part.inlineData) {
                        const dataUrl = `data:image/png;base64,${part.inlineData.data}`;
                        generatedImages.push(dataUrl);
                        artifactDocs.push({
                            id: `artifact-${docId}-${artifact.toLowerCase().replace(/\s/g, '-')}-${Date.now()}`,
                            title: `${parentDoc.title} - ${artifact}`,
                            version: 'v1.0', status: 'Working', owner: currentUser.username,
                            phase: parentDoc.phase, sequence: parentDoc.sequence + 1, type: 'image', parentDocId: docId
                        });
                    }
                }
            }

            if (isMounted.current) {
                handleSave(prev => {
                    const otherDocs = prev.documents.filter(d => d.parentDocId !== docId || d.type !== 'image');
                    const newPhasesData = { ...prev.phasesData };
                    newPhasesData[docId] = { ...newPhasesData[docId], images: generatedImages, selectedArtifacts: artifacts };
                    artifactDocs.forEach((aDoc, idx) => { newPhasesData[aDoc.id] = { content: generatedImages[idx] }; });
                    return { documents: [...otherDocs, ...artifactDocs], phasesData: newPhasesData };
                });
            }
        } catch (err) {
            console.error("Image generation failed:", err);
            if (isMounted.current) setError("Image generation failed.");
        } finally {
            if (isMounted.current) setLoadingPhase({ docId: null, step: null });
        }
    }, [handleSave, currentUser.username]);

    const handleGenerateContent = useCallback(async (docId: string, userInput: string, projectStateOverride?: Project) => {
        logAction('AI', 'handleGenerateContent', { docId, step: 'Start' });
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const currentProjectData = projectStateOverride || projectDataRef.current;
        const docToGenerate = currentProjectData.documents.find(d => d.id === docId);
        if (!docToGenerate) return { success: false, newContent: null, newCompactedContent: null };

        if (isMounted.current) setLoadingPhase({ docId, step: 'generating' });
        if (isMounted.current) setError('');

        try {
            const { firstDocContext, prevDocContext } = getRelevantContext(docToGenerate, currentProjectData.documents, currentProjectData.phasesData);
            const promptFn = getPromptFunction(docToGenerate.title, docToGenerate.phase);
            const primaryInput = docToGenerate.phase === 1 ? (userInput || "Starting documentation") : (`${firstDocContext}\n\n${prevDocContext}`.trim() || userInput);
            const promptText = promptFn(currentProjectData.name, currentProjectData.discipline, primaryInput, currentProjectData.mode, currentProjectData.scope, currentProjectData.teamSize, currentProjectData.complexity);

            logAction('AI', 'handleGenerateContent', { docId, step: 'Requesting generation' });
            const result = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({ 
                model: 'gemini-3-flash-preview', contents: truncatePrompt(promptText),
                config: { temperature: 0.7, thinkingConfig: { thinkingBudget: 0 } }
            }));

            if (!isMounted.current) return { success: false, newContent: null, newCompactedContent: null };

            const newContent = result.text || '';
            if (!newContent) throw new Error("Empty response.");

            if (isMounted.current) setLoadingPhase({ docId, step: 'compacting' });
            logAction('AI', 'handleGenerateContent', { docId, step: 'Compacting' });
            const compactRes = await withRetry<GenerateContentResponse>(() => ai.models.generateContent({ 
                model: 'gemini-3-flash-preview', contents: PROMPTS.compactContent(newContent),
                config: { thinkingConfig: { thinkingBudget: 0 } }
            }));

            if (!isMounted.current) return { success: false, newContent: null, newCompactedContent: null };

            const newCompacted = compactRes.text || newContent.substring(0, 500);

            handleSave(prev => ({ phasesData: { ...prev.phasesData, [docId]: { ...(prev.phasesData[docId] || {}), content: newContent, compactedContent: newCompacted } } }));
            logAction('AI', 'handleGenerateContent', { docId, step: 'Success' });
            return { success: true, newContent, newCompactedContent: newCompacted };
        } catch (err: any) {
            logAction('AI Error', 'handleGenerateContent', { docId, error: err.message });
            if (isMounted.current) setError(`AI Error: ${err.message}`);
            return { success: false, newContent: null, newCompactedContent: null };
        } finally {
            if (isMounted.current) setLoadingPhase({ docId: null, step: null });
        }
    }, [handleSave]);

    const handleUpdatePhaseData = useCallback(async (docId: string, content: string) => {
        handleSave(prev => ({ phasesData: { ...prev.phasesData, [docId]: { ...(prev.phasesData[docId] || {}), content } } }));
        const currentData = projectDataRef.current.phasesData[docId];
        if (currentData?.selectedArtifacts?.length) await handleGenerateImages(docId, currentData.selectedArtifacts, content);
    }, [handleSave, handleGenerateImages]);

    const handleChatToChange = useCallback(async (docId: string, userInstruction: string) => {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const currentContent = projectDataRef.current.phasesData[docId]?.content || '';

        if (isMounted.current) setLoadingPhase({ docId, step: 'generating' });
        if (isMounted.current) setError('');

        try {
            const prompt = `Modify this project document: "${userInstruction}".\n\nOriginal:\n${currentContent}`;
            const result = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });

            if (!isMounted.current) return;

            const newContent = result.text || '';
            const compactRes = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: PROMPTS.compactContent(newContent) });

            if (!isMounted.current) return;

            handleSave(prev => ({ phasesData: { ...prev.phasesData, [docId]: { ...(prev.phasesData[docId] || {}), content: newContent, compactedContent: compactRes.text } } }));
        } catch (e: any) { 
            if (isMounted.current) setError(`Instruction failed: ${e.message}`); 
        } finally { 
            if (isMounted.current) setLoadingPhase({ docId: null, step: null }); 
        }
    }, [handleSave]);

    const handleCompletePhase = useCallback((docId: string) => {
        handleSave(prev => ({ documents: prev.documents.map(d => d.id === docId ? { ...d, status: 'Approved' } : d) }));
    }, [handleSave]);

    const handleAttachFile = useCallback((docId: string, file: { name: string, data: string }) => {
        handleSave(prev => ({ phasesData: { ...prev.phasesData, [docId]: { ...(prev.phasesData[docId] || {}), attachments: [...(prev.phasesData[docId]?.attachments || []), file] } } }));
    }, [handleSave]);

    const handleRemoveAttachment = useCallback((docId: string, fileName: string) => {
        handleSave(prev => ({ phasesData: { ...prev.phasesData, [docId]: { ...(prev.phasesData[docId] || {}), attachments: (prev.phasesData[docId]?.attachments || []).filter(a => a.name !== fileName) } } }));
    }, [handleSave]);

    const handleSetGenerationMode = (mode: 'manual' | 'automatic') => handleSave({ generationMode: mode });

    const runAutomaticGeneration = useCallback(async () => {
        if (isAutoGenerating) return;
        setIsAutoGenerating(true);
        setError('');
        try {
            let state = { ...projectDataRef.current };
            const docs = [...state.documents]
                .filter(d => d.type !== 'image')
                .sort((a, b) => {
                    const phaseDiff = a.phase - b.phase;
                    if (phaseDiff !== 0) return phaseDiff;
                    return (a.sequence || 0) - (b.sequence || 0);
                });

            for (const doc of docs) {
                if (!isMounted.current) break;
                if (doc.status === 'Approved') continue;

                const res = await handleGenerateContent(doc.id, '', state);
                if (!res.success) break;

                if (!isMounted.current) break;
                handleCompletePhase(doc.id);

                state = { 
                    ...state, 
                    documents: state.documents.map(d => d.id === doc.id ? { ...d, status: 'Approved' } : d), 
                    phasesData: { 
                        ...state.phasesData, 
                        [doc.id]: { ...state.phasesData[doc.id], content: res.newContent, compactedContent: res.newCompactedContent } 
                    } 
                };
                await new Promise(r => setTimeout(r, 2000));
            }
        } finally { 
            if (isMounted.current) setIsAutoGenerating(false); 
        }
    }, [handleGenerateContent, handleCompletePhase, isAutoGenerating]);

    useEffect(() => { if (projectData.generationMode === 'automatic' && !isAutoGenerating) runAutomaticGeneration(); }, [projectData.generationMode, isAutoGenerating, runAutomaticGeneration]);

    const generateAgentPlan = useCallback(async () => {
        if (isMounted.current) setLoadingPhase({ docId: 'agent', step: 'Planner Agent: Processing...' });
        try {
            const { tasks, milestones } = await executeTrackingDataWorkflow(projectData, (msg) => {
                if (isMounted.current) setLoadingPhase({ docId: 'agent', step: msg });
            });
            if (isMounted.current) {
                handleSave({ tasks, milestones, isStarted: true });
                handleTabChange('Project Tracking');
            }
        } catch (e: any) { 
            if (isMounted.current) setError("Agentic planning failed: " + e.message); 
        } finally { 
            if (isMounted.current) setLoadingPhase({ docId: null, step: null }); 
        }
    }, [projectData, handleSave, handleTabChange]);

    const handleUpdateTask = (taskId: string, update: Partial<Task>) => {
        handleSave(prev => {
            const newTasks = prev.tasks.map(t => t.id === taskId ? { ...t, ...update } : t);
            const updatedTask = newTasks.find(t => t.id === taskId);
            let newNotifications = [...(prev.notifications || [])];

            if (update.status === 'done' && updatedTask) {
                newTasks.forEach(t => {
                    if (t.dependsOn.includes(taskId)) {
                        const isNowUnblocked = t.dependsOn.every(depId => newTasks.find(dt => dt.id === depId)?.status === 'done');
                        if (isNowUnblocked) {
                            newNotifications.push({
                                id: `notif-${Date.now()}-${t.id}`,
                                timestamp: new Date().toISOString(),
                                recipientId: t.role || 'Unassigned',
                                text: `Task "${t.name}" is now unblocked and ready for work!`,
                                read: false, taskId: t.id
                            });
                        }
                    }
                });
            }
            return { tasks: newTasks, notifications: newNotifications };
        });
    };

    const handleAnalyzeRisks = async () => {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        if (isMounted.current) setIsGeneratingReport('risk');
        try {
            const context = projectPhases.slice(0, 5).map(p => projectData.phasesData[p.id]?.compactedContent).join('\n');
            const res = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: PROMPTS.analyzeRisks(projectData, context) });
            if (isMounted.current) setAiReport({ title: 'AI Risk Analysis', content: res.text || '', isOpen: true });
        } catch (e) { 
            if (isMounted.current) setError('Risk analysis failed.'); 
        } finally { 
            if (isMounted.current) setIsGeneratingReport(null); 
        }
    };

    const handleGenerateSummary = async () => {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        if (isMounted.current) setIsGeneratingReport('summary');
        try {
            const context = projectPhases.slice(0, 5).map(p => projectData.phasesData[p.id]?.compactedContent).join('\n');
            const res = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: PROMPTS.generateStatusSummary(projectData, context) });
            if (isMounted.current) setAiReport({ title: 'Project Status Summary', content: res.text || '', isOpen: true });
        } catch (e) { 
            if (isMounted.current) setError('Summary generation failed.'); 
        } finally { 
            if (isMounted.current) setIsGeneratingReport(null); 
        }
    };

    const handleAddToDocuments = (title: string, content: string) => {
        const newDoc: Document = { id: `doc-ai-${Date.now()}`, title, version: 'v1.0', status: 'Working', owner: currentUser.username, phase: 8, sequence: 10 };
        handleSave(prev => ({ documents: [...prev.documents, newDoc], phasesData: { ...prev.phasesData, [newDoc.id]: { content } } }));
    };

    return (
        <section>
            {/* Header Area */}
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '2rem' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem' }}>
                    <button onClick={onBack} className="button">← Back</button>
                    <div>
                        <h1 style={{ fontSize: '2.4rem', margin: 0, lineHeight: 1 }}>{projectData.name}</h1>
                        <p style={{ color: 'var(--secondary-text)', fontSize: '1rem', marginTop: '0.5rem' }}>
                            {projectData.discipline} <span style={{ opacity: 0.3, margin: '0 8px' }}>|</span> Status: <span style={{ color: projectData.isStarted ? 'var(--success-color)' : 'var(--warning-color)' }}>{projectData.isStarted ? 'Executing' : 'Planning Phase'}</span>
                        </p>
                    </div>
                </div>
            </div>

            {/* Contextual Help Banner */}
            {showBrief && (
                <div className="info-banner" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <div>
                        <h4>Mission Brief: {activeTab}</h4>
                        <p style={{ maxWidth: '800px' }}>
                            {activeTab === 'Project Phases' && "This is the HMAP Planning Sequence. Generate, review, and approve documents sequentially. Once Phase 7 is approved, the system will auto-generate your Gantt charts and tracking boards."}
                            {activeTab === 'Dashboard' && "High-level overview of project health. Use the AI Engine to analyze risks or generate status reports for stakeholders."}
                            {activeTab === 'Project Tracking' && "Manage execution. Assign tasks to team members (extracted from the Resources doc), update progress, and track milestones."}
                            {activeTab === 'Documents' && "Central repository for all project artifacts. You can download the entire project history as a ZIP file here."}
                            {activeTab === 'Revision Control' && "Simulate changes before applying them. Use 'What-If' scenarios to see impact on budget and timeline."}
                        </p>
                    </div>
                    <button onClick={() => setShowBrief(false)} style={{ background: 'none', border: 'none', color: 'var(--secondary-text)', cursor: 'pointer', fontSize: '1.2rem' }}>&times;</button>
                </div>
            )}

            <nav className="dashboard-nav">
                <button onClick={() => handleTabChange('Dashboard')} className={activeTab === 'Dashboard' ? 'active' : ''}>Dashboard</button>
                <button onClick={() => handleTabChange('Project Phases')} className={activeTab === 'Project Phases' ? 'active' : ''}>Phases (HMAP)</button>
                <button onClick={() => handleTabChange('Documents')} className={activeTab === 'Documents' ? 'active' : ''}>Documents</button>
                <button onClick={() => handleTabChange('Project Tracking')} className={activeTab === 'Project Tracking' ? 'active' : ''}>Tracking</button>
                <button onClick={() => handleTabChange('Revision Control')} className={activeTab === 'Revision Control' ? 'active' : ''}>Revision Control</button>
            </nav>

            {loadingPhase.step && (
                <div className="status-message loading" style={{marginBottom: '2rem'}}>
                    <div className="spinner"></div>
                    <p>{loadingPhase.step}</p>
                </div>
            )}

            {activeTab === 'Dashboard' && (
                <DashboardView 
                    project={projectData} phasesData={projectData.phasesData} 
                    isPlanningComplete={projectData.documents.filter(d => d.type !== 'image').every(d => d.status === 'Approved')} 
                    projectPhases={projectPhases} onAnalyzeRisks={handleAnalyzeRisks} 
                    onGenerateSummary={handleGenerateSummary} isGeneratingReport={isGeneratingReport} 
                />
            )}

            {activeTab === 'Project Phases' && (
                <div>
                    <ProjectPhasesView 
                        project={projectData} projectPhases={projectPhases} phasesData={projectData.phasesData} 
                        documents={projectData.documents} error={error} loadingPhase={loadingPhase} 
                        handleUpdatePhaseData={handleUpdatePhaseData} handleCompletePhase={handleCompletePhase} 
                        handleGenerateContent={handleGenerateContent} handleGenerateImages={handleGenerateImages}
                        handleChatToChange={handleChatToChange} handleAttachFile={handleAttachFile} 
                        handleRemoveAttachment={handleRemoveAttachment} generationMode={projectData.generationMode} 
                        onSetGenerationMode={handleSetGenerationMode} isAutoGenerating={isAutoGenerating} 
                    />
                    {!projectData.isStarted && projectData.documents.filter(d => d.type !== 'image').every(d => d.status === 'Approved') && (
                        <div style={{textAlign: 'center', marginTop: '4rem', padding: '4rem', background: 'rgba(16, 185, 129, 0.05)', borderRadius: '12px', border: '1px dashed var(--success-color)'}}>
                            <h2 style={{color: 'var(--success-color)', marginBottom: '1rem'}}>Planning Complete!</h2>
                            <p style={{marginBottom: '2rem', color: 'var(--secondary-text)'}}>Run the Tracking Data Agent Workflow to generate your timeline and tasks using multi-agent synthesis.</p>
                            <button className="button button-primary" onClick={generateAgentPlan} style={{fontSize: '1.2rem', padding: '1.5rem 3rem'}}>Run 6-Agent Synthesis Workflow</button>
                        </div>
                    )}
                </div>
            )}

            {activeTab === 'Documents' && <DocumentsView project={projectData} documents={projectData.documents} onUpdateDocument={(id, status) => handleSave(p => ({ documents: p.documents.map(d => d.id === id ? { ...d, status } : d) }))} phasesData={projectData.phasesData} />}

            {activeTab === 'Project Tracking' && (
                <ProjectTrackingView 
                    project={projectData} onUpdateTask={handleUpdateTask} 
                    onUpdateMilestone={(mId, update) => handleSave(p => ({ milestones: p.milestones.map(m => m.id === mId ? { ...m, ...update } : m) }))} 
                    onUpdateTeam={(newTeam, newOwnerId) => handleSave({ team: newTeam, ownerId: newOwnerId || projectData.ownerId })} 
                    onUpdateProject={handleSave} onTaskClick={setSelectedTask} currentUser={currentUser} 
                />
            )}

            {activeTab === 'Revision Control' && <RevisionControlView project={projectData} onUpdateProject={handleSave} />}

            {selectedTask && (
                <TaskDetailModal 
                    isOpen={!!selectedTask} onClose={() => setSelectedTask(null)} 
                    onSave={(t) => handleUpdateTask(t.id, t)} task={selectedTask} 
                    project={projectData} currentUser={currentUser} 
                />
            )}

            <AiReportModal 
                isOpen={aiReport.isOpen} onClose={() => setAiReport(prev => ({ ...prev, isOpen: false }))} 
                title={aiReport.title} content={aiReport.content} onAddToDocuments={handleAddToDocuments} 
            />
        </section>
    );
};

import { GoogleGenAI } from "@google/genai";
import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { Header } from './components/Header.tsx';
import { LandingPage } from './views/LandingPage.tsx';
import { ProjectSetupView } from './views/ProjectSetupView.tsx';
import { ProjectDashboard } from './views/ProjectDashboard.tsx';
import { NewProjectModal } from './components/NewProjectModal.tsx';
import { DeleteProjectConfirmationModal } from './components/DeleteProjectConfirmationModal.tsx';
import { HelpModal } from './components/HelpModal.tsx';
import { GlobalStyles } from './styles/GlobalStyles.ts';
import { DEFAULT_SPRINTS, TEMPLATES, DEFAULT_DOCUMENTS } from './constants/projectData.ts';
import { logAction } from './utils/logging.ts';
import { AuthView } from './views/AuthView.tsx';
import * as authService from './utils/authService.ts';
import { subscribeToUpdates, notifyUpdate } from './utils/syncService.ts';
import { Project, Task, Notification, User } from './types.ts';

const App = () => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [isSettingUp, setIsSettingUp] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteConfirmationOpen, setIsDeleteConfirmationOpen] = useState(false);
  const [projectToDelete, setProjectToDelete] = useState<Project | null>(null);
  const [isHelpModalOpen, setIsHelpModalOpen] = useState(false);
  const [currentUser, setCurrentUser] = useState<User | null>(authService.getCurrentUser());

  // Guard to prevent processing sync events triggered by our own saves
  const isInternalUpdate = useRef(false);

  const userProjects = useMemo(() => {
    if (!projects || !currentUser) return [];
    return projects.filter(p => p.ownerId === currentUser.id || p.team?.some(member => member.userId === currentUser.id));
  }, [projects, currentUser]);

  const reloadStateFromStorage = useCallback(() => {
    if (isInternalUpdate.current) {
        logAction('Sync', 'App', { status: 'Ignored internal update' });
        isInternalUpdate.current = false;
        return;
    }

    logAction('Sync', 'App', { status: 'Reloading from storage' });
    const storedProjects = localStorage.getItem('hmap-projects');
    const storedUser = authService.getCurrentUser();

    if (storedUser) {
        setCurrentUser(storedUser);
    }

    if (storedProjects) {
        try {
            const parsed = JSON.parse(storedProjects);
            // Only update if data actually changed to avoid unnecessary re-renders
            if (JSON.stringify(parsed) !== JSON.stringify(projects)) {
                logAction('State Update', 'App', { reason: 'External change detected', projectCount: parsed.length });
                setProjects(parsed);

                const selectedProjectId = localStorage.getItem('hmap-selected-project-id');
                if (selectedProjectId) {
                    const updatedSelectedProject = parsed.find((p: Project) => p.id === selectedProjectId);
                    if (updatedSelectedProject) {
                        setSelectedProject(updatedSelectedProject);
                    }
                }
            }
        } catch (e) {
            console.error("Sync error", e);
        }
    }
  }, [projects]);

  useEffect(() => {
    const unsubscribe = subscribeToUpdates(reloadStateFromStorage);
    return () => unsubscribe();
  }, [reloadStateFromStorage]);

  useEffect(() => {
    try {
      const storedProjects = localStorage.getItem('hmap-projects');
      if (storedProjects) {
        const parsed = JSON.parse(storedProjects);
        setProjects(parsed);
      } else {
        localStorage.setItem('hmap-projects', JSON.stringify([]));
      }
    } catch (error: any) {
        console.error("Failed to load data from localStorage:", error);
        setProjects([]);
    }
  }, []);

  useEffect(() => {
    const selectedProjectId = localStorage.getItem('hmap-selected-project-id');

    if (currentUser && selectedProjectId && projects.length > 0) {
        const projectToSelect = projects.find(p => p.id === selectedProjectId);

        if (projectToSelect) {
            const isOwnerOrMember = projectToSelect.ownerId === currentUser.id || 
                                  projectToSelect.team?.some(member => member.userId === currentUser.id);
            if (isOwnerOrMember) {
                setSelectedProject(projectToSelect);
            } else {
                setSelectedProject(null);
                localStorage.removeItem('hmap-selected-project-id');
            }
        } else {
            // Project ID exists but project not found (deleted?)
            setSelectedProject(null);
            localStorage.removeItem('hmap-selected-project-id');
            // Do NOT automatically open modal here, let user choose from LandingPage
        }
    } else if (!currentUser) {
        setSelectedProject(null);
    }
  }, [currentUser, projects]);

  const saveProjectsToStorage = useCallback((updatedProjects: Project[]) => {
    try {
      isInternalUpdate.current = true;
      localStorage.setItem('hmap-projects', JSON.stringify(updatedProjects));
      notifyUpdate();
      // Reset flag after a delay to ensure the event has propagated and been ignored
      setTimeout(() => { isInternalUpdate.current = false; }, 500);
    } catch (e: any) {
      console.error("Failed to save projects to localStorage:", e);
      logAction('Error', 'App', { error: 'LocalStorage save failed', details: e.message });
    }
  }, []);

  const handleCreateProject = ({ name, template, mode, scope, teamSize, complexity }: any) => {
    if (!currentUser) return;
    const today = new Date();
    const endDate = new Date(today);
    endDate.setDate(today.getDate() + 44);

    const projectDocuments = JSON.parse(JSON.stringify(template.documents || DEFAULT_DOCUMENTS));

    const mandatoryDocs = [
        { title: 'Statement of Work (SOW)', phase: 5, sequence: 1 },
        { title: 'Resources & Skills List', phase: 2, sequence: 1 },
        { title: 'Detailed Plans (WBS/WRS)', phase: 7, sequence: 1 }
    ];

    mandatoryDocs.forEach(mandatoryDoc => {
        const simpleTitle = mandatoryDoc.title.replace(/\s\(.*\)/, '');
        const hasDoc = projectDocuments.some((doc: any) => doc.title.includes(simpleTitle));

        if (!hasDoc) {
            projectDocuments.push({
                id: `doc-mandatory-${Date.now()}-${mandatoryDoc.title.toLowerCase().replace(/[^a-z0-9]/g, '-')}`,
                title: mandatoryDoc.title, version: 'v1.0', status: 'Working', owner: 'A. User', phase: mandatoryDoc.phase,
                sequence: mandatoryDoc.sequence,
            });
        }
    });

    if (scope === 'subcontracted') {
        const hasRFP = projectDocuments.some((doc: any) => doc.title.toLowerCase().includes('request for proposal') || doc.title.toLowerCase().includes('rfp'));
        if (!hasRFP) {
            projectDocuments.push({
                id: `doc-subco-${Date.now()}-rfp`, title: 'Request for Proposal (RFP)', version: 'v1.0', status: 'Working', owner: 'A. User', phase: 2, sequence: 50,
            });
        }

        const hasContract = projectDocuments.some((doc: any) => doc.title.toLowerCase().includes('contract') || doc.title.toLowerCase().includes('agreement'));
        if (!hasContract) {
             projectDocuments.push({
                id: `doc-subco-${Date.now()}-contract`, title: "Draft Contract with T's & C's", version: 'v1.0', status: 'Working', owner: 'A. User', phase: 5, sequence: 50,
            });
        }
    }

    const newProject: Project = { 
        id: Date.now().toString(), name, mode, scope, generationMode: 'manual', teamSize, complexity: complexity || 'typical', discipline: template.discipline,
        ownerId: currentUser.id,
        phasesData: {},
        team: [{ userId: currentUser.id, role: 'Project Owner', name: currentUser.username, email: currentUser.email }],
        documents: projectDocuments, tasks: [], sprints: JSON.parse(JSON.stringify(DEFAULT_SPRINTS)), milestones: [], resources: [],
        avgBurdenedLaborRate: 125, budget: 100000,
        startDate: today.toISOString().split('T')[0],
        endDate: endDate.toISOString().split('T')[0],
        changeRequest: { title: 'Add new login provider', reason: 'User request for SSO', impactStr: '+15d +5000c' },
        scenarios: [
            { id: 1, name: 'A: Use contractors', impactStr: '+10d +8000c' },
            { id: 2, name: 'B: Defer feature', impactStr: '+0d +0c' },
        ],
        notifications: [],
    };
    const updatedProjects = [...projects, newProject];
    setProjects(updatedProjects);
    saveProjectsToStorage(updatedProjects);

    handleSelectProject(newProject);
    setIsSettingUp(false);
    logAction('Create Project', newProject.name, { newProject: newProject.id });
  };

  const handleSaveProject = useCallback((updatedProject: Project) => {
    // 1. Update React State immediately
    setProjects(prevProjects => {
        const updatedProjects = prevProjects.map(p => p.id === updatedProject.id ? updatedProject : p);
        // 2. Trigger storage save (will set isInternalUpdate = true)
        saveProjectsToStorage(updatedProjects);
        return updatedProjects;
    });

    // 3. Update local selection state
    setSelectedProject(updatedProject);
    logAction('Save Project', updatedProject.name, { projectId: updatedProject.id });
  }, [saveProjectsToStorage]);

  const handleSelectProject = (project: Project | null) => {
    logAction('Select Project', 'App', { projectId: project?.id || 'null' });
    setSelectedProject(project);
    if (project) {
        localStorage.setItem('hmap-selected-project-id', project.id);
        setIsSettingUp(false);
    } else {
        localStorage.removeItem('hmap-selected-project-id');
        setIsModalOpen(true); 
    }
  };

  const handleLogout = () => {
    authService.logout();
    setCurrentUser(null);
    setSelectedProject(null);
    setIsSettingUp(false);
    localStorage.removeItem('hmap-selected-project-id');
  };

  const handleRequestDeleteProject = (project: Project) => {
    setProjectToDelete(project);
    setIsDeleteConfirmationOpen(true);
    setIsModalOpen(false);
  };

  const handleConfirmDeletion = () => {
    if (!projectToDelete) return;
    const updatedProjects = projects.filter(p => p.id !== projectToDelete.id);
    setProjects(updatedProjects);
    saveProjectsToStorage(updatedProjects);

    if (selectedProject && selectedProject.id === projectToDelete.id) {
        setSelectedProject(null);
    }
    setProjectToDelete(null);
    setIsDeleteConfirmationOpen(false);
  };

  return (
    <>
        <style>{GlobalStyles}</style>

        {!currentUser ? (
            <AuthView onLogin={(user) => setCurrentUser(user)} />
        ) : (
            <>
                <Header 
                    onNewProject={() => setIsSettingUp(true)} 
                    onHomeClick={() => { setSelectedProject(null); setIsSettingUp(false); }}
                    disabled={false}
                    isLandingPage={!selectedProject && !isSettingUp}
                    currentUser={currentUser}
                    onLogout={handleLogout}
                    notifications={selectedProject?.notifications || []}
                    onNotificationClick={() => {}}
                    onMarkAllRead={() => {}}
                />
                <main>
                    {selectedProject ? (
                        <ProjectDashboard 
                            project={selectedProject} 
                            onBack={() => handleSelectProject(null)} 
                            saveProject={handleSaveProject}
                            currentUser={currentUser}
                        />
                    ) : isSettingUp ? (
                        <ProjectSetupView
                            onBack={() => setIsSettingUp(false)}
                            onCreateProject={handleCreateProject}
                            currentUser={currentUser}
                        />
                    ) : (
                        <LandingPage
                            projects={userProjects}
                            onSelectProject={(p) => p ? handleSelectProject(p) : setIsModalOpen(true)}
                            onNewProject={() => setIsSettingUp(true)}
                            currentUser={currentUser}
                        />
                    )}
                </main>

                <NewProjectModal 
                    isOpen={isModalOpen} 
                    onClose={() => setIsModalOpen(false)} 
                    onCreateProject={() => {}} 
                    projects={userProjects}
                    onSelectProject={handleSelectProject}
                    onRequestDelete={handleRequestDeleteProject}
                    currentUser={currentUser}
                    initialTab="select"
                />

                {projectToDelete && (
                  <DeleteProjectConfirmationModal
                      isOpen={isDeleteConfirmationOpen}
                      onClose={() => setIsDeleteConfirmationOpen(false)}
                      onConfirm={handleConfirmDeletion}
                      projectName={projectToDelete.name}
                  />
                )}
            </>
        )}

        <button className="help-fab" onClick={() => setIsHelpModalOpen(true)} aria-label="Open Help">?</button>
        <HelpModal isOpen={isHelpModalOpen} onClose={() => setIsHelpModalOpen(false)} />
    </>
  );
};

export default App;

