import React, { useState, useEffect, useRef } from 'react';
import { User, Notification } from '../types';

interface HeaderProps {
    onNewProject: () => void;
    onHomeClick: () => void;
    disabled: boolean;
    isLandingPage: boolean;
    currentUser: User;
    onLogout: () => void;
    notifications: Notification[];
    onNotificationClick: (notification: Notification) => void;
    onMarkAllRead: () => void;
}

export const Header: React.FC<HeaderProps> = ({ 
    onNewProject, onHomeClick, disabled, isLandingPage, currentUser, onLogout, 
    notifications = [], onNotificationClick, onMarkAllRead 
}) => {
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);
    const dropdownRef = useRef<HTMLDivElement>(null);

    const unreadCount = notifications.filter(n => !n.read).length;

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setIsDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    return (
        <header className="app-header">
            <h1 className="header-logo" onClick={onHomeClick}>
                Project Management Accelerator
            </h1>
            <div className="header-actions">
                {currentUser && (
                    <div className="user-controls">
                        <div className="notification-bell" title="Notifications" aria-label="Notifications" onClick={() => setIsDropdownOpen(!isDropdownOpen)}>
                            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"></path><path d="M13.73 21a2 2 0 0 1-3.46 0"></path></svg>
                            {unreadCount > 0 && <span className="notification-badge">{unreadCount}</span>}
                            {isDropdownOpen && (
                                <div className="notifications-dropdown" ref={dropdownRef}>
                                    <div className="notifications-header">
                                        <h4>Notifications</h4>
                                        {unreadCount > 0 && <button className="button button-small" onClick={onMarkAllRead}>Mark all read</button>}
                                    </div>
                                    <div className="notifications-list">
                                        {notifications.length > 0 ? (
                                            notifications.map(notif => (
                                                <div key={notif.id} className={`notification-item ${!notif.read ? 'unread' : ''}`} onClick={() => onNotificationClick(notif)}>
                                                    <p>{notif.text}</p>
                                                    <small className="text-secondary">{new Date(notif.timestamp).toLocaleString()}</small>
                                                </div>
                                            ))
                                        ) : (
                                            <p className="text-secondary text-center" style={{padding: '1rem'}}>No new notifications.</p>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                        <span>{currentUser.username}</span>
                        <button onClick={onLogout} className="button button-small">Logout</button>
                    </div>
                )}
                <button onClick={onNewProject} className="button" disabled={disabled}>
                    New Project
                </button>
            </div>
        </header>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { parseMarkdown } from '../utils/markdownParser.ts';
import { downloadLogs } from '../utils/logging.ts';

interface HelpModalProps {
    isOpen: boolean;
    onClose: () => void;
}

export const HelpModal: React.FC<HelpModalProps> = ({ isOpen, onClose }) => {
    const [content, setContent] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        if (isOpen) {
            setIsLoading(true);
            fetch('helpme.md')
                .then(response => {
                    if (!response.ok) {
                        throw new Error('Network response was not ok');
                    }
                    return response.text();
                })
                .then(text => {
                    setContent(text);
                    setIsLoading(false);
                })
                .catch(error => {
                    console.error('Error fetching help content:', error);
                    setContent('Could not load help content. Please try again later.');
                    setIsLoading(false);
                });
        }
    }, [isOpen]);

    const parsedContent = useMemo(() => parseMarkdown(content), [content]);

    if (!isOpen) return null;

    return (
        <div className="modal-overlay" onClick={onClose}>
            <div className="modal-content help-modal-content" onClick={(e) => e.stopPropagation()}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem', borderBottom: '1px solid var(--card-border)', paddingBottom: '1rem' }}>
                    <h2 style={{ margin: 0, fontSize: '1.8rem' }}>Mission Support</h2>
                    <button className="button-close" onClick={onClose} aria-label="Close help">&times;</button>
                </div>

                <div className="help-modal-body">
                    {isLoading ? <p>Loading help...</p> : parsedContent}
                </div>

                <div className="modal-actions" style={{justifyContent: 'space-between', marginTop: '2rem', borderTop: '1px solid var(--card-border)', paddingTop: '1.5rem'}}>
                    <button type="button" className="button" onClick={downloadLogs} style={{borderColor: 'var(--warning-color)', color: 'var(--warning-color)', fontSize: '0.9rem'}}>
                        Download Debug Logs
                    </button>
                    <button type="button" className="button button-primary" onClick={onClose}>Return to App</button>
                </div>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { TEMPLATES, PROMPTS } from '../constants/projectData.ts';
import { User, Project } from '../types.ts';

interface ProjectSetupViewProps {
    onBack: () => void;
    onCreateProject: (data: any) => void;
    currentUser: User;
}

export const ProjectSetupView: React.FC<ProjectSetupViewProps> = ({ onBack, onCreateProject, currentUser }) => {
    const [step, setStep] = useState(1);
    const [name, setName] = useState('');
    const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
    const [projectMode, setProjectMode] = useState('fullscale');
    const [projectScope, setProjectScope] = useState('internal');
    const [teamSize, setTeamSize] = useState('medium');
    const [projectComplexity, setProjectComplexity] = useState('typical');
    const [creationMode, setCreationMode] = useState('template');
    const [customDiscipline, setCustomDiscipline] = useState('');
    const [isGeneratingDocs, setIsGeneratingDocs] = useState(false);
    const [error, setError] = useState('');

    const handleNext = () => {
        setError('');
        if (!name.trim()) {
            setError("Please enter a project name to proceed.");
            return;
        }
        if (creationMode === 'template' && !selectedTemplateId) {
            setError("Please select a project template.");
            return;
        }
        if (creationMode === 'custom' && !customDiscipline.trim()) {
            setError("Please define the custom project logic.");
            return;
        }
        setStep(2);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        let template;
        if (creationMode === 'template') {
            template = TEMPLATES.find(t => t.id === selectedTemplateId);
            if (!template) { setError("Please select a template."); return; }
            onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
        } else {
            setIsGeneratingDocs(true);
            try {
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

                const prompt = PROMPTS.generateDocumentList(customDiscipline.trim(), projectScope, teamSize, projectComplexity);
                const schema = {
                    type: Type.OBJECT, 
                    properties: { 
                        documents: {
                            type: Type.ARRAY, 
                            items: { 
                                type: Type.OBJECT, 
                                properties: {
                                    title: { type: Type.STRING },
                                    phase: { type: Type.NUMBER },
                                    sequence: { type: Type.NUMBER }
                                }, 
                                required: ['title', 'phase', 'sequence']
                            }
                        }
                    }, 
                    required: ['documents']
                };

                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview', 
                    contents: prompt, 
                    config: { 
                        responseMimeType: "application/json", 
                        responseSchema: schema,
                        thinkingConfig: { thinkingBudget: 0 }
                    },
                });

                const text = response.text;
                if (!text) {
                    throw new Error("The AI returned an empty response.");
                }

                const parsedResponse = JSON.parse(text);
                const rawDocs = parsedResponse.documents;
                const generatedDocs = rawDocs.map((doc: any, i: number) => ({
                    id: `doc-custom-${i}-${Date.now()}`, 
                    title: doc.title, 
                    version: 'v1.0', 
                    status: 'Working', 
                    owner: currentUser.username, 
                    phase: doc.phase, 
                    sequence: doc.sequence,
                }));

                template = { id: 'custom', name: 'Custom Project', discipline: customDiscipline.trim(), documents: generatedDocs };
                onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
            } catch (err: any) {
                console.error("Project Generation Error:", err);
                setError(`Failed to generate project structure: ${err.message || 'Unknown error'}`);
            } finally {
                setIsGeneratingDocs(false);
            }
        }
    };

    return (
        <div className="setup-container" style={{ maxWidth: '900px', margin: '0 auto' }}>
            <div className="setup-header">
                <button onClick={() => step === 1 ? onBack() : setStep(1)} className="button">
                    ← {step === 1 ? 'Back' : 'Previous Step'}
                </button>
                <div>
                    <h1 style={{ fontSize: '2.5rem', marginBottom: '0.5rem' }}>
                        {step === 1 ? 'Mission Identity' : 'Operational Parameters'}
                    </h1>
                    <div style={{ display: 'flex', gap: '0.5rem' }}>
                        <div style={{ height: '4px', width: '40px', background: step >= 1 ? 'var(--accent-color)' : 'var(--card-border)', borderRadius: '2px' }}></div>
                        <div style={{ height: '4px', width: '40px', background: step >= 2 ? 'var(--accent-color)' : 'var(--card-border)', borderRadius: '2px' }}></div>
                    </div>
                </div>
            </div>

            <div className="glass-card" style={{ padding: '3rem' }}>
                {step === 1 && (
                    <div className="form-stack">
                        <div className="form-group">
                            <label>Project Name</label>
                            <input 
                                type="text" 
                                value={name} 
                                onChange={(e) => setName(e.target.value)} 
                                placeholder="e.g., Orbital Infrastructure Alpha" 
                                autoFocus
                            />
                        </div>

                        <div className="form-group">
                            <label>Discipline & Logic Core</label>
                            <div style={{ display: 'flex', gap: '1rem', marginBottom: '1.5rem' }}>
                                <button type="button" className={`button ${creationMode === 'template' ? 'active' : ''}`} onClick={() => setCreationMode('template')}>Use Template</button>
                                <button type="button" className={`button ${creationMode === 'custom' ? 'active' : ''}`} onClick={() => setCreationMode('custom')}>Custom Logic</button>
                            </div>

                            {creationMode === 'template' ? (
                                <div style={{ 
                                    display: 'grid', 
                                    gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', 
                                    gap: '1rem', 
                                    maxHeight: '400px', 
                                    overflowY: 'auto', 
                                    padding: '1rem', 
                                    background: 'rgba(0,0,0,0.2)', 
                                    borderRadius: '12px', 
                                    border: '1px solid var(--border-color)' 
                                }}>
                                    {TEMPLATES.map(t => (
                                        <button 
                                            key={t.id} 
                                            type="button" 
                                            className={`selection-button ${selectedTemplateId === t.id ? 'active' : ''}`} 
                                            onClick={() => setSelectedTemplateId(t.id)} 
                                            style={{ padding: '1.2rem' }}
                                        >
                                            <strong>{t.name}</strong>
                                            <span style={{ fontSize: '0.8rem', opacity: 0.6 }}>{t.discipline}</span>
                                        </button>
                                    ))}
                                </div>
                            ) : (
                                <div className="form-group">
