import React, { useState } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { TEMPLATES, PROMPTS } from '../constants/projectData.ts';
import { User, Project } from '../types.ts';

interface ProjectSetupViewProps {
    onBack: () => void;
    onCreateProject: (data: any) => void;
    currentUser: User;
}

export const ProjectSetupView: React.FC<ProjectSetupViewProps> = ({ onBack, onCreateProject, currentUser }) => {
    const [step, setStep] = useState(1);
    const [name, setName] = useState('');
    const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
    const [projectMode, setProjectMode] = useState('fullscale');
    const [projectScope, setProjectScope] = useState('internal');
    const [teamSize, setTeamSize] = useState('medium');
    const [projectComplexity, setProjectComplexity] = useState('typical');
    const [creationMode, setCreationMode] = useState('template');
    const [customDiscipline, setCustomDiscipline] = useState('');
    const [isGeneratingDocs, setIsGeneratingDocs] = useState(false);
    const [error, setError] = useState('');

    const handleNext = () => {
        setError('');
        if (!name.trim()) {
            setError("Please enter a project name to proceed.");
            return;
        }
        if (creationMode === 'template' && !selectedTemplateId) {
            setError("Please select a project template.");
            return;
        }
        if (creationMode === 'custom' && !customDiscipline.trim()) {
            setError("Please define the custom project logic.");
            return;
        }
        setStep(2);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        let template;
        if (creationMode === 'template') {
            template = TEMPLATES.find(t => t.id === selectedTemplateId);
            if (!template) { setError("Please select a template."); return; }
            onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
        } else {
            setIsGeneratingDocs(true);
            try {
                // Fix: Initialize AI locally right before usage as per guidelines.
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

                const prompt = PROMPTS.generateDocumentList(customDiscipline.trim(), projectScope, teamSize, projectComplexity);
                const schema = {
                    type: Type.OBJECT, 
                    properties: { 
                        documents: {
                            type: Type.ARRAY, 
                            items: { 
                                type: Type.OBJECT, 
                                properties: {
                                    title: { type: Type.STRING },
                                    phase: { type: Type.NUMBER },
                                    sequence: { type: Type.NUMBER }
                                }, 
                                required: ['title', 'phase', 'sequence']
                            }
                        }
                    }, 
                    required: ['documents']
                };

                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview', 
                    contents: prompt, 
                    config: { 
                        responseMimeType: "application/json", 
                        responseSchema: schema,
                        thinkingConfig: { thinkingBudget: 0 }
                    },
                });

                const text = response.text;
                if (!text) {
                    throw new Error("The AI returned an empty response.");
                }

                const parsedResponse = JSON.parse(text);
                if (!parsedResponse.documents || !Array.isArray(parsedResponse.documents)) {
                    throw new Error("Invalid document structure returned by AI.");
                }

                const rawDocs = parsedResponse.documents;
                const generatedDocs = rawDocs.map((doc: any, i: number) => ({
                    id: `doc-custom-${i}-${Date.now()}`, 
                    title: doc.title, 
                    version: 'v1.0', 
                    status: 'Working', 
                    owner: currentUser.username, 
                    phase: doc.phase, 
                    sequence: doc.sequence,
                }));

                template = { id: 'custom', name: 'Custom Project', discipline: customDiscipline.trim(), documents: generatedDocs };
                onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
            } catch (err: any) {
                console.error("Project Generation Error:", err);
                setError(`Failed to generate project structure: ${err.message || 'Unknown error'}`);
            } finally {
                setIsGeneratingDocs(false);
            }
        }
    };

    return (
        <div className="setup-container" style={{ maxWidth: '900px', margin: '0 auto' }}>
            <div className="setup-header">
                <button onClick={() => step === 1 ? onBack() : setStep(1)} className="button">
                    ← {step === 1 ? 'Back' : 'Previous Step'}
                </button>
                <div>
                    <h1 style={{ fontSize: '2.5rem', marginBottom: '0.5rem' }}>
                        {step === 1 ? 'Mission Identity' : 'Operational Parameters'}
                    </h1>
                    <div style={{ display: 'flex', gap: '0.5rem' }}>
                        <div style={{ height: '4px', width: '40px', background: step >= 1 ? 'var(--accent-color)' : 'var(--card-border)', borderRadius: '2px' }}></div>
                        <div style={{ height: '4px', width: '40px', background: step >= 2 ? 'var(--accent-color)' : 'var(--card-border)', borderRadius: '2px' }}></div>
                    </div>
                </div>
            </div>

            <div className="glass-card" style={{ padding: '3rem' }}>
                {step === 1 && (
                    <div className="form-stack">
                        <div className="form-group">
                            <label>Project Name <span style={{ fontSize: '0.8rem', color: 'var(--secondary-text)', fontWeight: 'normal' }}>({name.length}/256)</span></label>
                            <textarea 
                                value={name} 
                                onChange={(e) => setName(e.target.value)} 
                                placeholder="e.g., Orbital Infrastructure Alpha" 
                                autoFocus
                                maxLength={256}
                                rows={2}
                                style={{ resize: 'vertical' }}
                            />
                        </div>

                        <div className="form-group">
                            <label>Discipline & Logic Core</label>
                            <div style={{ display: 'flex', gap: '1rem', marginBottom: '1.5rem' }}>
                                <button type="button" className={`button ${creationMode === 'template' ? 'active' : ''}`} onClick={() => setCreationMode('template')}>Use Template</button>
                                <button type="button" className={`button ${creationMode === 'custom' ? 'active' : ''}`} onClick={() => setCreationMode('custom')}>Custom Logic</button>
                            </div>

                            {creationMode === 'template' ? (
                                <div style={{ 
                                    display: 'grid', 
                                    gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', 
                                    gap: '1rem', 
                                    maxHeight: '400px', 
                                    overflowY: 'auto', 
                                    padding: '1rem', 
                                    background: 'rgba(0,0,0,0.2)', 
                                    borderRadius: '12px', 
                                    border: '1px solid var(--border-color)' 
                                }}>
                                    {TEMPLATES.map(t => (
                                        <button 
                                            key={t.id} 
                                            type="button" 
                                            className={`selection-button ${selectedTemplateId === t.id ? 'active' : ''}`} 
                                            onClick={() => setSelectedTemplateId(t.id)} 
                                            style={{ padding: '1.2rem' }}
                                        >
                                            <strong>{t.name}</strong>
                                            <span style={{ fontSize: '0.8rem', opacity: 0.6 }}>{t.discipline}</span>
                                        </button>
                                    ))}
                                </div>
                            ) : (
                                <div className="form-group">
                                    <label style={{ fontSize: '0.9rem', color: 'var(--secondary-text)' }}>Custom Discipline Name</label>
                                    <input type="text" value={customDiscipline} onChange={(e) => setCustomDiscipline(e.target.value)} placeholder="e.g., Deep Sea Mining Protocol" />
                                </div>
                            )}
                        </div>

                        {error && <p className="status-message error">{error}</p>}

                        <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '2rem' }}>
                            <button type="button" className="button button-primary button-large" onClick={handleNext}>
                                Next: Configuration →
                            </button>
                        </div>
                    </div>
                )}

                {step === 2 && (
                    <form onSubmit={handleSubmit} className="form-stack">
                        <div className="form-group">
                            <label>Team Intelligence Scale</label>
                            <div className="selection-grid-3">
                                <button type="button" className={`selection-button ${teamSize === 'small' ? 'active' : ''}`} onClick={() => setTeamSize('small')}>
                                    <div style={{ fontSize: '1.5rem', marginBottom: '0.5rem' }}>⚡</div>
                                    <strong>Small Team</strong>
                                    <span>1-3 Core Agents</span>
                                </button>
                                <button type="button" className={`selection-button ${teamSize === 'medium' ? 'active' : ''}`} onClick={() => setTeamSize('medium')}>
                                    <div style={{ fontSize: '1.5rem', marginBottom: '0.5rem' }}>🚀</div>
                                    <strong>Medium Team</strong>
                                    <span>4-15 Agents</span>
                                </button>
                                <button type="button" className={`selection-button ${teamSize === 'large' ? 'active' : ''}`} onClick={() => setTeamSize('large')}>
                                    <div style={{ fontSize: '1.5rem', marginBottom: '0.5rem' }}>🏢</div>
                                    <strong>Large Org</strong>
                                    <span>16+ Agents</span>
                                </button>
                            </div>
                        </div>

                        <div className="setup-grid" style={{ gap: '2rem', marginTop: '1rem' }}>
                            <div className="form-group">
                                <label>Execution Mode</label>
                                <div className="selection-grid">
                                    <button type="button" className={`selection-button ${projectMode === 'fullscale' ? 'active' : ''}`} onClick={() => setProjectMode('fullscale')}>
                                        <strong>Full Scale</strong>
                                        <span>Complete HMAP cycle</span>
                                    </button>
                                    <button type="button" className={`selection-button ${projectMode === 'minimal' ? 'active' : ''}`} onClick={() => setProjectMode('minimal')}>
                                        <strong>Minimal</strong>
                                        <span>Rapid deployment</span>
                                    </button>
                                </div>
                            </div>

                            <div className="form-group">
                                <label>Operational Scope</label>
                                <div className="selection-grid">
                                    <button type="button" className={`selection-button ${projectScope === 'internal' ? 'active' : ''}`} onClick={() => setProjectScope('internal')}>
                                        <strong>Internal</strong>
                                        <span>In-house execution</span>
                                    </button>
                                    <button type="button" className={`selection-button ${projectScope === 'subcontracted' ? 'active' : ''}`} onClick={() => setProjectScope('subcontracted')}>
                                        <strong>Subcontracted</strong>
                                        <span>Vendor managed</span>
                                    </button>
                                </div>
                            </div>
                        </div>

                        {error && <p className="status-message error">{error}</p>}

                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '3rem', borderTop: '1px solid var(--card-border)', paddingTop: '2rem' }}>
                            <p style={{ color: 'var(--secondary-text)', fontSize: '0.9rem', maxWidth: '60%' }}>
                                By initializing, the AI will construct the HMAP document sequence based on these parameters.
                            </p>
                            <button type="submit" className="button button-primary button-large" disabled={isGeneratingDocs}>
                                {isGeneratingDocs ? <div className="spinner"></div> : 'INITIALIZE PROJECT'}
                            </button>
                        </div>
                    </form>
                )}
            </div>
        </div>
    );
};

