};

import React, { useState } from 'react';
import { GoogleGenAI, Type } from "@google/genai";
import { TEMPLATES, PROMPTS } from '../constants/projectData.ts';
import { User, Project } from '../types.ts';

interface ProjectSetupViewProps {
    onBack: () => void;
    onCreateProject: (data: any) => void;
    currentUser: User;
}

export const ProjectSetupView: React.FC<ProjectSetupViewProps> = ({ onBack, onCreateProject, currentUser }) => {
    const [step, setStep] = useState(1);
    const [name, setName] = useState('');
    const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);
    const [projectMode, setProjectMode] = useState('fullscale');
    const [projectScope, setProjectScope] = useState('internal');
    const [teamSize, setTeamSize] = useState('medium');
    const [projectComplexity, setProjectComplexity] = useState('typical');
    const [creationMode, setCreationMode] = useState('template');
    const [customDiscipline, setCustomDiscipline] = useState('');
    const [isGeneratingDocs, setIsGeneratingDocs] = useState(false);
    const [error, setError] = useState('');

    const handleNext = () => {
        setError('');
        if (!name.trim()) {
            setError("Please enter a project name to proceed.");
            return;
        }
        if (creationMode === 'template' && !selectedTemplateId) {
            setError("Please select a project template.");
            return;
        }
        if (creationMode === 'custom' && !customDiscipline.trim()) {
            setError("Please define the custom project logic.");
            return;
        }
        setStep(2);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        let template;
        if (creationMode === 'template') {
            template = TEMPLATES.find(t => t.id === selectedTemplateId);
            if (!template) { setError("Please select a template."); return; }
            onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
        } else {
            setIsGeneratingDocs(true);
            try {
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

                const prompt = PROMPTS.generateDocumentList(customDiscipline.trim(), projectScope, teamSize, projectComplexity);
                const schema = {
                    type: Type.OBJECT, 
                    properties: { 
                        documents: {
                            type: Type.ARRAY, 
                            items: { 
                                type: Type.OBJECT, 
                                properties: {
                                    title: { type: Type.STRING },
                                    phase: { type: Type.NUMBER },
                                    sequence: { type: Type.NUMBER }
                                }, 
                                required: ['title', 'phase', 'sequence']
                            }
                        }
                    }, 
                    required: ['documents']
                };

                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview', 
                    contents: prompt, 
                    config: { 
                        responseMimeType: "application/json", 
                        responseSchema: schema,
                        thinkingConfig: { thinkingBudget: 0 }
                    },
                });

                const text = response.text;
                if (!text) {
                    throw new Error("The AI returned an empty response.");
                }

                const parsedResponse = JSON.parse(text);
                const rawDocs = parsedResponse.documents;
                const generatedDocs = rawDocs.map((doc: any, i: number) => ({
                    id: `doc-custom-${i}-${Date.now()}`, 
                    title: doc.title, 
                    version: 'v1.0', 
                    status: 'Working', 
                    owner: currentUser.username, 
                    phase: doc.phase, 
                    sequence: doc.sequence,
                }));

                template = { id: 'custom', name: 'Custom Project', discipline: customDiscipline.trim(), documents: generatedDocs };
                onCreateProject({ name, template, mode: projectMode, scope: projectScope, teamSize, complexity: projectComplexity });
            } catch (err: any) {
                console.error("Project Generation Error:", err);
                setError(`Failed to generate project structure: ${err.message || 'Unknown error'}`);
            } finally {
                setIsGeneratingDocs(false);
            }
        }
    };

    return (
        <div className="setup-container">
            <div className="setup-header">
                <button onClick={() => step === 1 ? onBack() : setStep(1)} className="button">
                    ← {step === 1 ? 'Back' : 'Previous Step'}
                </button>
                <div>
                    <h1 style={{ fontSize: '2.5rem', marginBottom: '0.5rem' }}>
                        {step === 1 ? 'Mission Identity' : 'Operational Parameters'}
                    </h1>
                    <div style={{ display: 'flex', gap: '0.5rem' }}>
                        <div style={{ height: '4px', width: '40px', background: step >= 1 ? 'var(--accent-color)' : 'var(--card-border)', borderRadius: '2px' }}></div>
                        <div style={{ height: '4px', width: '40px', background: step >= 2 ? 'var(--accent-color)' : 'var(--card-border)', borderRadius: '2px' }}></div>
                    </div>
                </div>
            </div>

            <div className="glass-card" style={{ padding: '3rem' }}>
                {step === 1 && (
                    <div className="form-stack">
                        <div className="form-group">
                            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.8rem', alignItems: 'center' }}>
                                <label style={{ margin: 0 }}>Project Name</label>
                                <span style={{ fontSize: '0.85rem', color: 'var(--secondary-text)', opacity: 0.8 }}>
                                    {name.length}/256
                                </span>
                            </div>
                            <textarea 
                                value={name} 
                                onChange={(e) => setName(e.target.value)} 
                                placeholder="e.g., Orbital Infrastructure Alpha - Phase 1 Expansion" 
                                autoFocus
                                maxLength={256}
                                rows={3}
                                style={{ resize: 'vertical' }}
                            />
                        </div>

                        <div className="form-group">
                            <label>Discipline & Logic Core</label>
                            <div style={{ display: 'flex', gap: '1rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
                                <button type="button" className={`button ${creationMode === 'template' ? 'active' : ''}`} onClick={() => setCreationMode('template')}>Use Template</button>
                                <button type="button" className={`button ${creationMode === 'custom' ? 'active' : ''}`} onClick={() => setCreationMode('custom')}>Custom Logic</button>
                            </div>

                            {creationMode === 'template' ? (
                                <div style={{ 
                                    display: 'grid', 
                                    gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', 
                                    gap: '1rem', 
                                    maxHeight: '400px', 
                                    overflowY: 'auto', 
                                    padding: '1rem', 
                                    background: 'rgba(0,0,0,0.2)', 
                                    borderRadius: '12px', 
                                    border: '1px solid var(--border-color)' 
                                }}>
                                    {TEMPLATES.map(t => (
                                        <button 
                                            key={t.id} 
                                            type="button" 
                                            className={`selection-button ${selectedTemplateId === t.id ? 'active' : ''}`} 
                                            onClick={() => setSelectedTemplateId(t.id)} 
                                            style={{ padding: '1.2rem' }}
                                        >
                                            <strong>{t.name}</strong>
                                            <span style={{ fontSize: '0.8rem', opacity: 0.6 }}>{t.discipline}</span>
                                        </button>
                                    ))}
                                </div>
                            ) : (
                                <div className="form-group">
                                    <label style={{ fontSize: '0.9rem', color: 'var(--secondary-text)' }}>Custom Discipline Name</label>
                                    <input type="text" value={customDiscipline} onChange={(e) => setCustomDiscipline(e.target.value)} placeholder="e.g., Deep Sea Mining Protocol" />
                                </div>
                            )}
                        </div>

                        {error && <p className="status-message error">{error}</p>}

                        <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '2rem' }}>
                            <button type="button" className="button button-primary button-large" onClick={handleNext}>
                                Next: Configuration →
                            </button>
                        </div>
                    </div>
                )}

                {step === 2 && (
                    <form onSubmit={handleSubmit} className="form-stack">
                        <div className="form-group">
                            <label>Team Intelligence Scale</label>
                            <div className="selection-grid-3">
                                <button type="button" className={`selection-button ${teamSize === 'small' ? 'active' : ''}`} onClick={() => setTeamSize('small')}>
                                    <div style={{ fontSize: '1.5rem', marginBottom: '0.5rem' }}>⚡</div>
                                    <strong>Small Team</strong>
                                    <span>1-3 Core Agents</span>
                                </button>
                                <button type="button" className={`selection-button ${teamSize === 'medium' ? 'active' : ''}`} onClick={() => setTeamSize('medium')}>
                                    <div style={{ fontSize: '1.5rem', marginBottom: '0.5rem' }}>🚀</div>
                                    <strong>Medium Team</strong>
                                    <span>4-15 Agents</span>
                                </button>
                                <button type="button" className={`selection-button ${teamSize === 'large' ? 'active' : ''}`} onClick={() => setTeamSize('large')}>
                                    <div style={{ fontSize: '1.5rem', marginBottom: '0.5rem' }}>🏢</div>
                                    <strong>Large Org</strong>
                                    <span>16+ Agents</span>
                                </button>
                            </div>
                        </div>

                        <div className="setup-grid" style={{ gap: '2rem', marginTop: '1rem' }}>
                            <div className="form-group">
                                <label>Execution Mode</label>
                                <div className="selection-grid">
                                    <button type="button" className={`selection-button ${projectMode === 'fullscale' ? 'active' : ''}`} onClick={() => setProjectMode('fullscale')}>
                                        <strong>Full Scale</strong>
                                        <span>Complete HMAP cycle</span>
                                    </button>
                                    <button type="button" className={`selection-button ${projectMode === 'minimal' ? 'active' : ''}`} onClick={() => setProjectMode('minimal')}>
                                        <strong>Minimal</strong>
                                        <span>Rapid deployment</span>
                                    </button>
                                </div>
                            </div>

                            <div className="form-group">
                                <label>Operational Scope</label>
                                <div className="selection-grid">
                                    <button type="button" className={`selection-button ${projectScope === 'internal' ? 'active' : ''}`} onClick={() => setProjectScope('internal')}>
                                        <strong>Internal</strong>
                                        <span>In-house execution</span>
                                    </button>
                                    <button type="button" className={`selection-button ${projectScope === 'subcontracted' ? 'active' : ''}`} onClick={() => setProjectScope('subcontracted')}>
                                        <strong>Subcontracted</strong>
                                        <span>Vendor managed</span>
                                    </button>
                                </div>
                            </div>
                        </div>

                        {error && <p className="status-message error">{error}</p>}

                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '3rem', borderTop: '1px solid var(--card-border)', paddingTop: '2rem', flexWrap: 'wrap', gap: '1rem' }}>
                            <p style={{ color: 'var(--secondary-text)', fontSize: '0.9rem', maxWidth: '60%' }}>
                                By initializing, the AI will construct the HMAP document sequence based on these parameters.
                            </p>
                            <button type="submit" className="button button-primary button-large" disabled={isGeneratingDocs}>
                                {isGeneratingDocs ? <div className="spinner"></div> : 'INITIALIZE PROJECT'}
                            </button>
                        </div>
                    </form>
                )}
            </div>
        </div>
    );
};

import React, { useMemo } from 'react';
import { Project, Task } from '../types.ts';

const diffInDays = (date1: string, date2: string) => {
    if (!date1 || !date2) return 0;
    const d1 = new Date(date1);
    const d2 = new Date(date2);
    return Math.max(0, Math.round((d2.getTime() - d1.getTime()) / (1000 * 60 * 60 * 24)) + 1);
};

const currencyFormat = (num: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(num || 0);

export const DashboardView: React.FC<{ 
    project: Project; 
    phasesData: any; 
    isPlanningComplete: boolean; 
    projectPhases: any[]; 
    onAnalyzeRisks: () => void; 
    onGenerateSummary: () => void; 
    isGeneratingReport: 'risk' | 'summary' | null; 
}> = ({ 
    project, phasesData, isPlanningComplete, projectPhases, 
    onAnalyzeRisks, onGenerateSummary, isGeneratingReport 
}) => {
    const { 
        tasks = [], 
        documents = [], 
        milestones = [], 
        resources = [], 
        avgBurdenedLaborRate = 0, 
        budget = 0,
        startDate,
        endDate
    } = project;

    const metrics = useMemo(() => {
        const totalTasks = tasks.length;
        const completedTasks = tasks.filter(t => t.status === 'done').length;
        const progressPercent = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

        const inProgressCount = tasks.filter(t => t.status === 'inprogress').length;
        const reviewCount = tasks.filter(t => t.status === 'review').length;
        const todoCount = tasks.filter(t => t.status === 'todo').length;

        const overdueCount = tasks.filter(t => t.status !== 'done' && new Date(t.endDate) < new Date()).length;
        const blockedCount = tasks.filter(task =>
            task.status !== 'done' &&
            task.dependsOn?.some(depId => {
                const prereq = tasks.find(t => t.id === depId);
                return prereq && prereq.status !== 'done';
            })
        ).length;

        const totalEstimatedLabor = tasks.reduce((sum, task) => {
            const duration = diffInDays(task.startDate, task.endDate);
            return sum + (duration * 8 * (avgBurdenedLaborRate || 0));
        }, 0);

        const actualLaborCost = tasks.reduce((sum, task) => {
            if (task.status === 'done' || task.actualTime) {
                const duration = task.actualTime || diffInDays(task.startDate, task.endDate);
                return sum + (duration * 8 * (avgBurdenedLaborRate || 0));
            }
            return sum;
        }, 0);

        const totalEstimatedResources = resources.reduce((sum, r) => sum + (r.estimate || 0), 0);
        const actualResourceCost = resources.reduce((sum, r) => sum + (r.actual || 0), 0);

        const totalProjected = totalEstimatedLabor + totalEstimatedResources;
        const totalSpent = actualLaborCost + actualResourceCost;
        const budgetVariance = budget - totalProjected;

        const totalProjectDuration = diffInDays(startDate, endDate);
        const daysElapsed = diffInDays(startDate, new Date().toISOString().split('T')[0]);
        const timeProgress = totalProjectDuration > 0 ? Math.min(100, Math.max(0, Math.round((daysElapsed / totalProjectDuration) * 100))) : 0;

        return {
            progressPercent,
            totalTasks,
            completedTasks,
            inProgressCount,
            reviewCount,
            todoCount,
            overdueCount,
            blockedCount,
            totalProjected,
            totalSpent,
            budgetVariance,
            timeProgress,
            daysLeft: Math.max(0, totalProjectDuration - daysElapsed)
        };
    }, [tasks, resources, budget, avgBurdenedLaborRate, startDate, endDate]);

    const riskLevel = metrics.overdueCount > 3 || metrics.blockedCount > 5 ? 'CRITICAL' : (metrics.overdueCount > 0 ? 'MODERATE' : 'OPTIMAL');
    const riskColor = riskLevel === 'CRITICAL' ? 'var(--error-color)' : riskLevel === 'MODERATE' ? 'var(--warning-color)' : 'var(--success-color)';

    return (
        <div className="dashboard-grid" style={{ animation: 'slideUp 0.8s ease' }}>
            <div className="glass-card widget-gauge" style={{ gridColumn: 'span 4' }}>
                <div style={{ position: 'relative', width: '200px', height: '200px', marginBottom: '2rem' }}>
                    <svg viewBox="0 0 100 100" style={{ transform: 'rotate(-90deg)', width: '100%', height: '100%' }}>
                        <circle cx="50" cy="50" r="45" fill="transparent" stroke="rgba(255,255,255,0.05)" strokeWidth="8" />
                        <circle cx="50" cy="50" r="45" fill="transparent" stroke="var(--accent-color)" strokeWidth="8" 
                                strokeDasharray="283" strokeDashoffset={283 - (283 * metrics.progressPercent) / 100}
                                strokeLinecap="round" style={{ transition: 'stroke-dashoffset 1s ease-in-out' }} />
                    </svg>
                    <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)' }}>
                        <h2 style={{ fontSize: '3.5rem', margin: 0 }}>{metrics.progressPercent}%</h2>
                        <span style={{ fontSize: '0.9rem', color: 'var(--secondary-text)', textTransform: 'uppercase', letterSpacing: '2px' }}>Complete</span>
                    </div>
                </div>
                <div style={{ display: 'flex', gap: '2rem', width: '100%', justifyContent: 'center' }}>
                    <div>
                        <div style={{ fontSize: '1.8rem', fontWeight: 700 }}>{metrics.totalTasks}</div>
                        <div style={{ fontSize: '0.8rem', color: 'var(--secondary-text)', textTransform: 'uppercase' }}>Total Tasks</div>
                    </div>
                    <div>
                        <div style={{ fontSize: '1.8rem', fontWeight: 700, color: 'var(--success-color)' }}>{metrics.completedTasks}</div>
                        <div style={{ fontSize: '0.8rem', color: 'var(--secondary-text)', textTransform: 'uppercase' }}>Resolved</div>
                    </div>
                </div>
            </div>

            <div className="glass-card widget-financial" style={{ gridColumn: 'span 8' }}>
                <h3 className="subsection-title" style={{ marginBottom: '2.5rem' }}>Financial Health Spectrum</h3>
                <div className="financial-grid" style={{ display: 'grid', gridTemplateColumns: '1.5fr 1fr', gap: '4rem' }}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>
                        <div>
                            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.8rem' }}>
                                <span style={{ color: 'var(--secondary-text)' }}>Projected Cost vs. Budget</span>
                                <span>{currencyFormat(metrics.totalProjected)} / {currencyFormat(budget)}</span>
                            </div>
                            <div style={{ height: '12px', background: 'rgba(255,255,255,0.05)', borderRadius: '10px', overflow: 'hidden' }}>
                                <div style={{ 
                                    height: '100%', 
                                    width: `${Math.min(100, (metrics.totalProjected / (budget || 1)) * 100)}%`, 
                                    background: metrics.budgetVariance < 0 ? 'var(--error-color)' : 'var(--success-color)',
                                    boxShadow: `0 0 15px ${metrics.budgetVariance < 0 ? 'var(--error-color)' : 'var(--success-color)'}`
                                }}></div>
                            </div>
                        </div>
                        <div>
                            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.8rem' }}>
                                <span style={{ color: 'var(--secondary-text)' }}>Burned to Date</span>
                                <span>{currencyFormat(metrics.totalSpent)}</span>
                            </div>
                            <div style={{ height: '12px', background: 'rgba(255,255,255,0.05)', borderRadius: '10px', overflow: 'hidden' }}>
                                <div style={{ 
                                    height: '100%', 
                                    width: `${Math.min(100, (metrics.totalSpent / (metrics.totalProjected || 1)) * 100)}%`, 
                                    background: 'var(--neon-purple)',
                                    boxShadow: '0 0 15px var(--neon-purple)'
                                }}></div>
                            </div>
                        </div>
                    </div>
                    <div style={{ borderLeft: '1px solid var(--card-border)', paddingLeft: '3rem', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
                        <div style={{ marginBottom: '2rem' }}>
                            <div style={{ fontSize: '0.9rem', color: 'var(--secondary-text)', marginBottom: '0.5rem' }}>Variance</div>
                            <h2 style={{ fontSize: '2.5rem', color: metrics.budgetVariance < 0 ? 'var(--error-color)' : 'var(--success-color)' }}>
                                {currencyFormat(metrics.budgetVariance)}
                            </h2>
                        </div>
                        <div style={{ display: 'flex', gap: '1rem' }}>
                             <span className={`chip-${metrics.budgetVariance < 0 ? 'red' : 'green'}`}>
                                {metrics.budgetVariance < 0 ? 'OVER BUDGET' : 'UNDER BUDGET'}
                             </span>
                        </div>
                    </div>
                </div>
            </div>

            <div className="glass-card widget-velocity" style={{ gridColumn: 'span 5' }}>
                <h3 className="subsection-title">Schedule Velocity</h3>
                <div style={{ textAlign: 'center', padding: '1rem 0' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '1.5rem', fontSize: '1.1rem' }}>
                        <span>Days Elapsed</span>
                        <span style={{ fontWeight: 700 }}>{metrics.timeProgress}%</span>
                    </div>
                    <div style={{ position: 'relative', height: '40px', background: 'rgba(255,255,255,0.05)', borderRadius: '20px', padding: '5px' }}>
                        <div style={{ 
                            height: '100%', 
                            width: `${metrics.timeProgress}%`, 
                            background: 'linear-gradient(90deg, var(--neon-purple), var(--accent-color))', 
                            borderRadius: '15px',
                            boxShadow: '0 0 20px var(--accent-glow)'
                        }}></div>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '1.5rem' }}>
                        <div style={{ textAlign: 'left' }}>
                            <div style={{ color: 'var(--secondary-text)', fontSize: '0.8rem' }}>Start Date</div>
                            <div style={{ fontWeight: 600 }}>{startDate || 'TBD'}</div>
                        </div>
                        <div style={{ textAlign: 'center' }}>
                             <div style={{ color: 'var(--accent-color)', fontSize: '1.4rem', fontWeight: 800 }}>{metrics.daysLeft}</div>
                             <div style={{ fontSize: '0.7rem', color: 'var(--secondary-text)', textTransform: 'uppercase' }}>Days Remaining</div>
                        </div>
                        <div style={{ textAlign: 'right' }}>
                            <div style={{ color: 'var(--secondary-text)', fontSize: '0.8rem' }}>End Date</div>
                            <div style={{ fontWeight: 600 }}>{endDate || 'TBD'}</div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="glass-card widget-radar" style={{ gridColumn: 'span 4' }}>
                <h3 className="subsection-title">Stability Radar</h3>
