import { User } from '../types.ts';
import { auth } from './firebaseConfig.ts';
import { 
    createUserWithEmailAndPassword, 
    signInWithEmailAndPassword, 
    signOut, 
    onAuthStateChanged as firebaseOnAuthStateChanged,
    updateProfile
} from "firebase/auth";

const USERS_KEY = 'hmap-users';
const SESSION_KEY = 'hmap-session';

// --- Local Helpers ---
const getLocalUsers = (): User[] => {
    try {
        const users = localStorage.getItem(USERS_KEY);
        return users ? JSON.parse(users) : [];
    } catch (error) {
        return [];
    }
};

const saveLocalUsers = (users: User[]) => {
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
};

// --- Service Methods ---

export const register = async (username: string, email: string, password: string): Promise<User | null> => {
    if (auth) {
        try {
            const userCredential = await createUserWithEmailAndPassword(auth, email, password);
            await updateProfile(userCredential.user, { displayName: username });

            const user: User = {
                id: userCredential.user.uid,
                username: username,
                email: email,
                notificationPrefs: { teams: false, slack: false, outlook: false, gmail: false }
            };
            return user;
        } catch (error) {
            console.error("Firebase Registration Error:", error);
            throw error;
        }
    } else {
        // Local Fallback
        const users = getLocalUsers();
        if (users.some(u => u.username === username || u.email === email)) {
            throw new Error("User already exists locally.");
        }
        const newUser: User = { 
            id: `user-${Date.now()}`, 
            username, 
            email, 
            password, // Note: Storing plain text password locally is for prototype only
            notificationPrefs: { teams: false, slack: false, outlook: false, gmail: false }
        };
        saveLocalUsers([...users, newUser]);
        return newUser;
    }
};

export const login = async (email: string, password: string): Promise<User | null> => {
    if (auth) {
        try {
            const userCredential = await signInWithEmailAndPassword(auth, email, password);
            const user: User = {
                id: userCredential.user.uid,
                username: userCredential.user.displayName || email.split('@')[0],
                email: email,
                notificationPrefs: { teams: false, slack: false, outlook: false, gmail: false }
            };
            return user;
        } catch (error) {
            console.error("Firebase Login Error:", error);
            return null;
        }
    } else {
        // Local Fallback
        const users = getLocalUsers();
        const user = users.find(u => u.email === email && u.password === password);
        if (user) {
            localStorage.setItem(SESSION_KEY, JSON.stringify(user));
            return user;
        }
        return null;
    }
};

export const logout = async (): Promise<void> => {
    if (auth) {
        await signOut(auth);
    }
    localStorage.removeItem(SESSION_KEY);
};

export const getCurrentUser = async (): Promise<User | null> => {
    // If Firebase is active, we rely on onAuthStateChanged in the App component mostly,
    // but this can return the local session snapshot if needed.
    if (auth) {
        const fbUser = auth.currentUser;
        if (fbUser) {
            return {
                id: fbUser.uid,
                username: fbUser.displayName || fbUser.email?.split('@')[0] || 'User',
                email: fbUser.email || '',
            };
        }
    }

    // Check local storage fallback
    try {
        const session = localStorage.getItem(SESSION_KEY);
        if (session) return JSON.parse(session);
    } catch (e) {
        console.error(e);
    }
    return null;
};

export const onAuthStateChanged = (callback: (user: User | null) => void) => {
    if (auth) {
        return firebaseOnAuthStateChanged(auth, (fbUser) => {
            if (fbUser) {
                const user: User = {
                    id: fbUser.uid,
                    username: fbUser.displayName || fbUser.email?.split('@')[0] || 'User',
                    email: fbUser.email || '',
                };
                // Sync session to local storage for hybrid access
                localStorage.setItem(SESSION_KEY, JSON.stringify(user));
                callback(user);
            } else {
                localStorage.removeItem(SESSION_KEY);
                callback(null);
            }
        });
    } else {
        // Mock listener for local storage changes
        const checkLocal = () => {
            const session = localStorage.getItem(SESSION_KEY);
            callback(session ? JSON.parse(session) : null);
        };
        window.addEventListener('storage', checkLocal);
        checkLocal(); // Initial check
        return () => window.removeEventListener('storage', checkLocal);
    }
};

import { Project } from '../types.ts';
import { db } from './firebaseConfig.ts';
import { 
    collection, 
    doc, 
    setDoc, 
    getDocs, 
    query, 
    where, 
    onSnapshot,
    writeBatch
} from "firebase/firestore";

const DB_NAME = 'HMAP_Data';
const DB_VERSION = 1;
const STORE_NAME = 'projects';

// --- IndexedDB Helpers ---
const openDB = (): Promise<IDBDatabase> => {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onupgradeneeded = (event) => {
            const db = (event.target as IDBOpenDBRequest).result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME, { keyPath: 'id' });
            }
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
    });
};

const saveToIndexedDB = async (projects: Project[]): Promise<void> => {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const clearRequest = store.clear();
        clearRequest.onsuccess = () => {
            if (projects.length === 0) {
                resolve();
                return;
            }
            let completed = 0;
            projects.forEach(project => {
                store.put(project).onsuccess = () => {
                    completed++;
                    if (completed === projects.length) resolve();
                };
            });
        };
        transaction.onerror = () => reject(transaction.error);
    });
};

// --- Firestore Helpers ---
const saveToFirestore = async (projects: Project[], userId: string) => {
    if (!db || !userId) return;

    try {
        const batch = writeBatch(db);
        const projectsRef = collection(db, 'projects');

        projects.forEach(project => {
            // Only sync projects where the user is the owner or explicitly shared
            // For simplicity in this demo, we sync if ownerId matches or they are in team
            if (project.ownerId === userId || project.team.some(m => m.userId === userId)) {
                const docRef = doc(projectsRef, project.id);
                // Sanitize undefined values which Firestore hates
                const sanitized = JSON.parse(JSON.stringify(project)); 
                batch.set(docRef, sanitized, { merge: true });
            }
        });

        await batch.commit();
        console.log("Synced projects to Firestore");
    } catch (e) {
        console.error("Firestore sync error:", e);
    }
};

// --- Main Exported Functions ---

export const saveProjectsToDB = async (projects: Project[], userId?: string): Promise<void> => {
    try {
        // 1. Local Persistence (Fast, Offline)
        await saveToIndexedDB(projects);

        // 2. Cloud Duplication (Async)
        if (userId && db) {
            saveToFirestore(projects, userId).catch(e => console.warn("Background sync failed", e));
        }
    } catch (e) {
        console.error("Storage Error", e);
        throw e;
    }
};

export const loadProjectsFromDB = async (): Promise<Project[]> => {
    try {
        const db = await openDB();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction(STORE_NAME, 'readonly');
            const store = transaction.objectStore(STORE_NAME);
            const request = store.getAll();
            request.onsuccess = () => resolve(request.result as Project[] || []);
            request.onerror = () => reject(request.error);
        });
    } catch (e) {
        console.error("IndexedDB Load Error", e);
        return [];
    }
};

export const migrateFromLocalStorage = async (): Promise<Project[] | null> => {
    const localData = localStorage.getItem('hmap-projects');
    if (localData) {
        try {
            const projects = JSON.parse(localData);
            if (Array.isArray(projects) && projects.length > 0) {
                await saveProjectsToDB(projects);
                localStorage.removeItem('hmap-projects'); 
                return projects;
            }
        } catch (e) {
            console.error("Migration failed", e);
        }
    }
    return null;
};

// --- Real-time Sync Listener ---
export const subscribeToRemoteChanges = (userId: string, onUpdate: (projects: Project[]) => void) => {
    if (!db || !userId) return () => {};

    const q = query(collection(db, 'projects'), where('team', 'array-contains', { userId, role: 'Project Owner' })); 
    // Note: The simple query above might fail depending on exact object structure in array. 
    // A broader query: where ownerId == userId is safer for MVP.

    const qOwner = query(collection(db, 'projects'), where('ownerId', '==', userId));

    const unsubscribe = onSnapshot(qOwner, (snapshot) => {
        const remoteProjects: Project[] = [];
        snapshot.forEach((doc) => {
            remoteProjects.push(doc.data() as Project);
        });

        if (remoteProjects.length > 0) {
            // Save to local DB to keep them in sync
            saveToIndexedDB(remoteProjects).then(() => {
                onUpdate(remoteProjects);
            });
        }
    });

    return unsubscribe;
};

